#[doc(hidden)]
pub const STATIC_PREFIX_RESUME_DESCRIPTOR_V1_MAGIC: &[u8; 8] = b"FRESPXK1";
#[doc(hidden)]
pub const STATIC_PREFIX_RESUME_DESCRIPTOR_V1_VERSION: u32 = 1;
#[doc(hidden)]
pub const STATIC_PREFIX_RESUME_DESCRIPTOR_V1_HEADER_BYTES: usize = 32;
#[doc(hidden)]
pub const STATIC_PREFIX_RESUME_DESCRIPTOR_V1_STATE_BYTES: usize = 16;
#[doc(hidden)]
pub const STATIC_PREFIX_RESUME_DESCRIPTOR_V1_MAX_BYTES: usize = 256 * 1024 * 1024;
/// Packed compiler-private object sidecar for transient slow-prefix
/// continuation.
#[doc(hidden)]
pub const STATIC_PREFIX_RESUME_DESCRIPTOR_V2_MAGIC: &[u8; 8] = b"FRESPXK2";
#[doc(hidden)]
pub const STATIC_PREFIX_RESUME_DESCRIPTOR_V2_VERSION: u32 = 2;
#[doc(hidden)]
pub const STATIC_PREFIX_RESUME_DESCRIPTOR_V2_HEADER_BYTES: usize = 32;
#[doc(hidden)]
pub const STATIC_PREFIX_RESUME_DESCRIPTOR_V2_STATE_BYTES: usize = 4;
const PROGRAM_FORMAT_VERSION_V1: u32 = 1;
const PROGRAM_FORMAT_VERSION_V2: u32 = 2;
const PROGRAM_FORMAT_VERSION_V3: u32 = 3;
const PROGRAM_FORMAT_VERSION_V4: u32 = 4;
const PROGRAM_FORMAT_VERSION_V5: u32 = 5;
const PROGRAM_FORMAT_VERSION_V6: u32 = 6;
const PROGRAM_FORMAT_VERSION_V7: u32 = 7;
const PROGRAM_FORMAT_VERSION_V8: u32 = 8;
/// Canonical stable-program version used by the optimizer-free generic NFA
/// export and its allocation-free resource census.
pub const GENERIC_NFA_PROGRAM_FORMAT_VERSION: u32 = PROGRAM_FORMAT_VERSION_V4;
// V4 remains the canonical FIFO format without a graph-dispatch marker. V5
// adds canonically rederived graph dispatch while retaining FIFO DFA replay.
// V6 binds older optimizing DFA artifacts to descending class-mass replay.
// V7 marks an optimizing ordered-NFA fallback that has no retained DFA
// payload, so an explicitly requested slow lowering can preserve that choice
// after restore. This is artifact provenance, not authorization: module
// lowering still requires a separate optimizing API call.
// V8 binds fresh optimizing DFA artifacts to descending estimated-frequency
// replay while preserving the exact V6 canonical regeneration contract.
const PROGRAM_FORMAT_VERSION: u32 = PROGRAM_FORMAT_VERSION_V4;
const PROGRAM_FLAG_NFA_MANDATORY_SUFFIX: u8 = 1 << 0;
const PROGRAM_FLAG_NFA_MANDATORY_CUT: u8 = 1 << 1;
const PROGRAM_FLAG_NFA_EXACT_PRODUCT: u8 = 1 << 2;
const PROGRAM_FLAG_NFA_PARTIAL_DFA: u8 = 1 << 3;
const PROGRAM_FLAG_NFA_ORDERED_EDGE_DISPATCH: u8 = 1 << 4;
const PROGRAM_FLAG_NFA_EPSILON_CLOSURE_DISPATCH: u8 = 1 << 5;
const PROGRAM_FLAG_NFA_OPTIMIZING_FALLBACK: u8 = 1 << 6;
const PROGRAM_V3_KNOWN_FLAGS: u8 = PROGRAM_FLAG_NFA_MANDATORY_SUFFIX
    | PROGRAM_FLAG_NFA_MANDATORY_CUT
    | PROGRAM_FLAG_NFA_EXACT_PRODUCT;
const PROGRAM_KNOWN_FLAGS: u8 = PROGRAM_FLAG_NFA_MANDATORY_SUFFIX
    | PROGRAM_FLAG_NFA_MANDATORY_CUT
    | PROGRAM_FLAG_NFA_EXACT_PRODUCT
    | PROGRAM_FLAG_NFA_PARTIAL_DFA;
const PROGRAM_V5_GRAPH_DISPATCH_FLAGS: u8 = PROGRAM_FLAG_NFA_ORDERED_EDGE_DISPATCH
    | PROGRAM_FLAG_NFA_EPSILON_CLOSURE_DISPATCH;
const PROGRAM_V5_KNOWN_FLAGS: u8 = PROGRAM_KNOWN_FLAGS | PROGRAM_V5_GRAPH_DISPATCH_FLAGS;
const PROGRAM_V6_KNOWN_FLAGS: u8 = PROGRAM_V5_KNOWN_FLAGS;
const PROGRAM_V7_KNOWN_FLAGS: u8 =
    PROGRAM_V5_KNOWN_FLAGS | PROGRAM_FLAG_NFA_OPTIMIZING_FALLBACK;
const PROGRAM_V8_KNOWN_FLAGS: u8 = PROGRAM_V6_KNOWN_FLAGS;
const DEFAULT_LINE_TERMINATOR: u8 = b'\n';

static NEXT_PROGRAM_INSTANCE_IDENTITY: AtomicU64 = AtomicU64::new(1);

fn next_program_instance_identity() -> u64 {
    NEXT_PROGRAM_INSTANCE_IDENTITY
        .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |identity| {
            identity.checked_add(1)
        })
        .unwrap_or_else(|_| panic!("program instance identity space exhausted"))
}

/// Exact semantic artifact identity plus a process-local clone lineage.
///
/// Independently constructed programs still compare the complete stable
/// SHA-256 digest. A program and its derived clones share the unique lineage,
/// letting their prepared workspaces take one integer comparison on the hot
/// path without an auxiliary allocation or atomic reference-count update.
#[derive(Clone, Copy, Debug)]
struct ProgramIdentity {
    artifact: [u8; 32],
    instance: u64,
}

impl ProgramIdentity {
    const UNASSIGNED: Self = Self {
        artifact: [0; 32],
        instance: 0,
    };

    fn new(artifact: [u8; 32]) -> Self {
        Self {
            artifact,
            instance: next_program_instance_identity(),
        }
    }

    #[inline]
    fn compatible(&self, other: &Self) -> bool {
        self.instance == other.instance || self.artifact == other.artifact
    }
}
/// Number of bytes that a runtime must read before it can discover the exact
/// serialized artifact extent.
pub const PROGRAM_HEADER_LEN: usize = 24;
/// Hard ceiling accepted by the stable deserializer and runtime boundary.
///
/// This matches the default compiler program budget. It bounds the only raw
/// pointer extent that the runtime discovers from the artifact itself.
pub const MAX_SERIALIZED_PROGRAM_BYTES: usize = 256 * 1024 * 1024;
const MIN_SERIALIZED_PROGRAM_BYTES: usize = PROGRAM_HEADER_LEN + 52 + 8;

#[cfg(test)]
std::thread_local! {
    static TEST_SERIALIZE_CALLS: Cell<usize> = const { Cell::new(0) };
}

#[cfg(test)]
pub(crate) fn reset_test_serialize_calls() {
    TEST_SERIALIZE_CALLS.with(|calls| calls.set(0));
}

#[cfg(test)]
pub(crate) fn test_serialize_calls() -> usize {
    TEST_SERIALIZE_CALLS.with(Cell::get)
}
/// Maximum fixed byte depth inspected by the source-independent anchored
/// prefix analysis.
pub const MAX_ANCHORED_PREFIX_BYTES: usize = 16;
/// Maximum fixed byte depth inspected by the source-independent anchored
/// suffix analysis. Index zero is the final consumed byte.
pub(crate) const MAX_ANCHORED_SUFFIX_BYTES: usize = 8;
/// Hard work ceiling for anchored-prefix derivation.
///
/// Work charges state visits, edge visits, and bytes inserted into a set. A
/// graph that reaches this ceiling simply receives no prefix optimization; it
/// remains fully executable through the same semantic program.
const MAX_ANCHORED_PREFIX_WORK: u64 = 1_000_000;
/// Hard work ceiling for anchored-suffix derivation.
const MAX_ANCHORED_SUFFIX_WORK: u64 = 1_000_000;
/// Hard work ceiling for the optional graph-wide exact-width proof.
const MAX_EXACT_WIDTH_WORK: u64 = 1_000_000;
/// Hard work ceiling for the optional graph-wide minimum-width proof used by
/// compiler-only absolute whole-window admission.
const MAX_MIN_MATCH_WIDTH_WORK: u64 = 1_000_000;
/// Hard work ceiling for the optional graph-wide maximum-width proof.
const MAX_MATCH_WIDTH_WORK: u64 = 1_000_000;
/// Independent ceilings for the optional exact-product NFA proof. The proof
/// explores every byte from every distinct epsilon-closed frontier, so each
/// kind of abstract operation is bounded separately and a frontier explosion
/// can only decline this sidecar.
const MAX_NFA_EXACT_PRODUCT_STATE_WORK: u64 = 4_000_000;
const MAX_NFA_EXACT_PRODUCT_EDGE_WORK: u64 = 8_000_000;
const MAX_NFA_EXACT_PRODUCT_BYTE_WORK: u64 = 1_000_000;
const MAX_NFA_EXACT_PRODUCT_FRONTIER_WORK: u64 = 4_000_000;
const MAX_NFA_EXACT_PRODUCT_FRONTIERS: usize = 1_024;
const MAX_NFA_EXACT_PRODUCT_MEMORY_BYTES: usize = 16 * 1024 * 1024;
/// Maximum conservative false-candidate work admitted for the portable NFA
/// mandatory-suffix accelerator. The product is the proved maximum match
/// width times the primary suffix-column cardinality.
const MAX_NFA_SUFFIX_CANDIDATE_WORK: usize = 64;
const MAX_NFA_SUFFIX_REVERSE_STATES: usize = 4_096;
const MAX_NFA_SUFFIX_REVERSE_CELLS: usize = 262_144;
const MAX_NFA_SUFFIX_REVERSE_WORK: u64 = 8_000_000;
const MAX_NFA_SUFFIX_REVERSE_MEMORY_BYTES: usize = 16 * 1024 * 1024;
/// Permit a short burst before measuring suffix-filter density. Thereafter the
/// scanner admits four times the uniform expected hit rate for its one-to-
/// three-byte primary set and falls back to the ordinary ordered NFA when the
/// observed input is denser.
const NFA_SUFFIX_PRIMARY_HIT_CREDIT: usize = 8;
const NFA_SUFFIX_PRIMARY_HIT_DENOMINATOR: usize = 64;
/// Bound cumulative reverse verification for mandatory suffixes whose match
/// width is unbounded (or whose width proof exhausted its resource envelope).
/// One late sparse candidate may inspect the complete preceding window, but
/// repeated false candidates may not turn the accelerator into a quadratic
/// scan. The credit keeps short windows and a small burst of candidates out of
/// the ordinary executor without weakening the asymptotic bound.
const NFA_SUFFIX_SCAN_ONLY_REVERSE_WORK_CREDIT: usize = 1_024;
const NFA_SUFFIX_SCAN_ONLY_REVERSE_WORK_MULTIPLIER: usize = 2;
/// Bound the optional graph proof that a terminal suffix byte cannot be
/// consumed anywhere before the terminal edge of an accepting path. The
/// analysis is source independent and declines the optimization on exhaustion.
const MAX_NFA_SUFFIX_TERMINAL_BARRIER_WORK: u64 = 4_000_000;
/// A graph-wide byte cut must be substantially selective before its probe is
/// placed in front of the ordinary ordered-NFA executor. For a uniformly
/// distributed source, 64 members imply one hit every four bytes; broader
/// sets cannot amortize even their short scalar admission probe. Real sources
/// can still benefit from any narrower class that is absent from a window.
const MAX_NFA_MANDATORY_CUT_CARDINALITY: u16 = 64;
/// An ordinary mandatory cut always names a real Thompson state. This reserved
/// value lets the mutually exclusive cut slot retain a complete exact-product
/// scanner without changing the scanner enum or compiled-program layout.
const NFA_EXACT_PRODUCT_ROOT_SENTINEL: u32 = u32::MAX;
/// Because the cut is an extra pass, it must halve the strongest existing
/// forward column's uniform expected hit rate. This prevents a marginally
/// narrower interior class from displacing K0's already-vectorized filter.
const NFA_MANDATORY_CUT_MIN_SELECTIVITY_GAIN: u16 = 2;
/// Keep a common positive search out of vector setup. A miss through this
/// short prefix earns the target-dispatched block classifier for the rest of
/// the window.
const NFA_MANDATORY_CUT_SCALAR_PREFIX_BYTES: usize = 8;

/// Checked failure while reconstructing a stable AOT semantic program.
#[derive(Clone, Debug, Eq, PartialEq)]
#[non_exhaustive]
pub enum ProgramFormatError {
    /// A fixed field, tag, count, table shape, or trailing extent is invalid.
    Malformed(&'static str),
    /// The embedded Thompson graph failed the canonical automaton validator.
    Automaton(fre_automata::CompileError),
    /// A bounded reconstruction allocation could not be reserved.
    Allocation(&'static str),
}

impl fmt::Display for ProgramFormatError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Malformed(detail) => write!(formatter, "malformed AOT program: {detail}"),
            Self::Automaton(error) => write!(formatter, "invalid AOT automaton: {error}"),
            Self::Allocation(table) => {
                write!(formatter, "could not allocate bounded AOT {table} table")
            }
        }
    }
}

impl std::error::Error for ProgramFormatError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Automaton(error) => Some(error),
            Self::Malformed(_) | Self::Allocation(_) => None,
        }
    }
}

impl From<fre_automata::CompileError> for ProgramFormatError {
    fn from(value: fre_automata::CompileError) -> Self {
        Self::Automaton(value)
    }
}

/// Capture-free result promised by one compiled entry point.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum OutputContract {
    Exists,
    SelectedEnd,
    Span,
}

/// Compiler-private endpoint composition proof for the complete bounded
/// bit-parallel machine. `exact_match_width` distinguishes a false-only
/// variable-width oracle from a machine whose first accepting boundary is the
/// complete ordered endpoint result.
#[derive(Clone, Copy, Debug)]
pub(crate) struct NativeBitParallelEndpointOracleView<'a> {
    pub(crate) machine: NativeBitParallelExistsView<'a>,
    pub(crate) output: OutputContract,
    pub(crate) exact_match_width: Option<usize>,
}

impl OutputContract {
    const fn tag(self) -> u8 {
        match self {
            Self::Exists => 0,
            Self::SelectedEnd => 1,
            Self::Span => 2,
        }
    }

    pub(crate) fn from_tag(tag: u8) -> Result<Self, ProgramFormatError> {
        match tag {
            0 => Ok(Self::Exists),
            1 => Ok(Self::SelectedEnd),
            2 => Ok(Self::Span),
            _ => Err(ProgramFormatError::Malformed("unknown output-contract tag")),
        }
    }
}

/// Allocation-free census of one canonical optimizer-free generic NFA wire.
///
/// The SHA-256 identity binds every reported dimension to the exact complete
/// wire, including output contract and line profile. The graph and workspace
/// byte counts are target-exact prospective logical payloads before vector
/// capacity or allocator rounding. They are not construction receipts.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct GenericNfaProgramCensus {
    artifact_identity: [u8; 32],
    output: OutputContract,
    line_terminator: u8,
    serialized_bytes: usize,
    raw_graph_logical_bytes: usize,
    semantic_graph_logical_bytes: usize,
    workspace_shape: WorkspaceShape,
    workspace_layout: WorkspaceLayout,
}

impl GenericNfaProgramCensus {
    /// Strictly validate and size a borrowed canonical generic-NFA program.
    ///
    /// This routine does not allocate. It admits exactly the normalized V4
    /// ordered-NFA representation emitted by
    /// [`CompiledProgram::serialize_generic_nfa`]: zero program flags and no
    /// DFA payload. Every raw state, offset, target, edge kind, and byte bound
    /// is validated before the identity-bound census is returned.
    ///
    /// # Errors
    ///
    /// Returns a typed malformed-program, unsupported-representation, or
    /// workspace-arithmetic error. The stable program extent remains capped
    /// by [`MAX_SERIALIZED_PROGRAM_BYTES`].
    pub fn from_wire(bytes: &[u8]) -> Result<Self, GenericNfaProgramCensusError> {
        census_generic_nfa_program(bytes)
    }

    #[must_use]
    pub const fn artifact_identity(self) -> [u8; 32] {
        self.artifact_identity
    }

    #[must_use]
    pub const fn output_contract(self) -> OutputContract {
        self.output
    }

    #[must_use]
    pub const fn line_terminator(self) -> u8 {
        self.line_terminator
    }

    #[must_use]
    pub const fn serialized_bytes(self) -> usize {
        self.serialized_bytes
    }

    /// Prospective logical payload of one normalized raw graph's six `SoA`
    /// tables, before vector capacity or allocator rounding.
    ///
    /// A constructor must still measure and recheck its actual retained
    /// capacities before publication; this census is not an allocation
    /// receipt.
    #[must_use]
    pub const fn raw_graph_logical_bytes(self) -> usize {
        self.raw_graph_logical_bytes
    }

    /// Prospective logical payload of the semantic representation's two graph
    /// copies: the canonical raw plan and executable automaton.
    ///
    /// This is exactly twice [`Self::raw_graph_logical_bytes`], not a claim
    /// about `Vec` capacity or allocator-retained bytes. It excludes the
    /// automaton's inline derived byte-class map.
    #[must_use]
    pub const fn semantic_graph_logical_bytes(self) -> usize {
        self.semantic_graph_logical_bytes
    }

    #[must_use]
    pub const fn workspace_shape(self) -> WorkspaceShape {
        self.workspace_shape
    }

    #[must_use]
    pub const fn workspace_layout(self) -> WorkspaceLayout {
        self.workspace_layout
    }

    /// Check that `bytes` is the exact complete wire bound to this census.
    ///
    /// This is an allocation-free identity check, not a second structural
    /// validation pass.
    #[must_use]
    pub fn authenticates_wire(self, bytes: &[u8]) -> bool {
        bytes.len() == self.serialized_bytes
            && <[u8; 32]>::from(Sha256::digest(bytes)) == self.artifact_identity
    }
}

/// Checked failure while taking a generic-NFA wire census.
#[derive(Clone, Debug, Eq, PartialEq)]
#[non_exhaustive]
pub enum GenericNfaProgramCensusError {
    /// The stable program header or normalized raw graph is malformed.
    Program(ProgramFormatError),
    /// The header selects a representation outside the canonical
    /// optimizer-free generic NFA form. Its body is not further validated.
    Unsupported(&'static str),
    /// Exact ordinary workspace sizing overflowed.
    Workspace(fre_automata::SearchError),
}

impl fmt::Display for GenericNfaProgramCensusError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Program(error) => error.fmt(formatter),
            Self::Unsupported(detail) => {
                write!(formatter, "unsupported generic-NFA program wire: {detail}")
            }
            Self::Workspace(error) => write!(formatter, "generic-NFA workspace: {error}"),
        }
    }
}

impl std::error::Error for GenericNfaProgramCensusError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Program(error) => Some(error),
            Self::Workspace(error) => Some(error),
            Self::Unsupported(_) => None,
        }
    }
}

impl From<ProgramFormatError> for GenericNfaProgramCensusError {
    fn from(value: ProgramFormatError) -> Self {
        Self::Program(value)
    }
}

/// Result of executing a program with its statically selected contract.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum MatchResult {
    Exists(bool),
    SelectedEnd(Option<usize>),
    Span(Option<(usize, usize)>),
}

impl MatchResult {
    #[must_use]
    pub const fn is_match(self) -> bool {
        match self {
            Self::Exists(found) => found,
            Self::SelectedEnd(found) => found.is_some(),
            Self::Span(found) => found.is_some(),
        }
    }
}

/// Half-open byte range searched by a compiled program.
///
/// Construction is cheap and validation happens transactionally at
/// [`CompiledProgram::search`], before either engine reads the haystack.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct SearchWindow {
    start: usize,
    end: usize,
}

/// Result of the authenticated runtime preflight for native incomplete
/// retained rows.
///
/// A complete suffix/cut proof or an adaptive native-entry decline returns
/// the semantic result directly. Otherwise the native table may enter on the
/// exact non-empty, possibly narrowed window without replaying either
/// accelerator.
#[doc(hidden)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum RetainedPartialPreflight {
    Complete(MatchResult),
    Enter(SearchWindow),
}

/// Result of resolving one admitted mutable native-row hole.
///
/// A published cell belongs to the freshly reprojected descriptor and the
/// triggering source byte remains unread. The exact admission is re-armed, so
/// generated code can retry that byte and resolve another later hole without
/// deoptimizing the whole search. An uncacheable transition completes through
/// K0 and returns its final semantic result instead.
#[doc(hidden)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum DynamicNativeRowsHoleResolution {
    PublishedCell {
        cell: u32,
        native_rows_address: usize,
    },
    Complete(MatchResult),
}

/// Read-only projection of one retained native hole into the independently
/// owned immutable continuation table.
///
/// Constructing this value neither consumes nor settles the admitted native
/// transaction. The runtime must first publish the matching prepared header,
/// then transfer the same one-shot transaction from the retained root to the
/// immutable continuation owner through the checked method below.
#[doc(hidden)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct FrozenRetainedPartialResumeProjection {
    program_instance: u64,
    workspace_address: usize,
    window: SearchWindow,
    resume_state: usize,
    resume_position: usize,
    canonical_state: usize,
    pending_end: Option<usize>,
    cache_identity: u64,
    format_version: u32,
    fully_prefilled: FullyPrefilledFallbackReceipt,
}

impl FrozenRetainedPartialResumeProjection {
    /// Canonical immutable-table state selected by the retained hole ordinal.
    #[doc(hidden)]
    #[must_use]
    pub const fn canonical_state(&self) -> usize {
        self.canonical_state
    }

    /// Pending endpoint word for the native continuation ABI. Zero means the
    /// authenticated state has no pending endpoint.
    #[doc(hidden)]
    #[must_use]
    pub const fn pending_end_word(&self) -> usize {
        match self.pending_end {
            Some(end) => end,
            None => 0,
        }
    }

    /// Immutable row generation authenticated by this projection.
    #[doc(hidden)]
    #[must_use]
    pub const fn format_version(&self) -> u32 {
        self.format_version
    }
}

/// Fixed-layout read-only view of one prepared K0 warmed-root cache.
///
/// Addresses are represented as exposed-provenance `usize` values rather than
/// Rust pointers so the prepared workspace remains movable and `Send`. They
/// become live only after the final owning prepared regex has reached its
/// exclusive call site, and remain valid only for the synchronous native scan
/// admitted by that preflight. They must not be retained across a helper call,
/// re-entry, or destruction. A generated entry must authenticate the immutable
/// `cache_identity` before following either source address and conservatively
/// side-exit on an unpublished cell or a learned-loop row it does not own with
/// an independent authenticated scanner. The identity binds the descriptor to
/// one fixed-capacity cache generation. Replacement publishes a fresh identity
/// after invalidating the prior rows; the identity is not a single-use ticket.
#[doc(hidden)]
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
#[repr(C)]
pub struct DynamicNativeRowsV1 {
    pub rows_address: usize,
    pub class_map_address: usize,
    pub live_cells: usize,
    pub row_stride: u32,
    pub unfilled_cell: u32,
    pub accept_mask: u32,
    pub next_row_token_mask: u32,
    pub cache_identity: u64,
    pub learned_loop_row_count: u32,
    // Fixed-capacity ownership boundary for canonical K0 loop scanners.
    // Generated entries must side-exit before a listed row unless an
    // independent authenticated scanner owns that exact row and skip.
    pub learned_loop_rows: [u32; 4],
    pub initial_row: u32,
    pub initial_flags: u32,
}

/// Unpublished-cell sentinel required by [`DynamicNativeRowsV1`].
#[doc(hidden)]
pub const DYNAMIC_NATIVE_ROWS_V1_UNFILLED_CELL: u32 = u32::MAX;
/// Accepting-transition bit required by [`DynamicNativeRowsV1`].
#[doc(hidden)]
pub const DYNAMIC_NATIVE_ROWS_V1_ACCEPT_MASK: u32 = 1 << 31;
/// Encoded next-row field required by [`DynamicNativeRowsV1`].
#[doc(hidden)]
pub const DYNAMIC_NATIVE_ROWS_V1_NEXT_ROW_TOKEN_MASK: u32 = (1 << 29) - 1;
const FROZEN_DYNAMIC_SOURCE_START_PROPAGATE: u32 = 1 << 29;
const FROZEN_DYNAMIC_SOURCE_START_RESET: u32 = 1 << 30;
const FROZEN_DYNAMIC_SOURCE_START_MASK: u32 =
    FROZEN_DYNAMIC_SOURCE_START_PROPAGATE | FROZEN_DYNAMIC_SOURCE_START_RESET;

impl SearchWindow {
    #[must_use]
    pub const fn new(start: usize, end: usize) -> Self {
        Self { start, end }
    }

    #[must_use]
    pub const fn full(haystack: &[u8]) -> Self {
        Self {
            start: 0,
            end: haystack.len(),
        }
    }

    #[must_use]
    pub const fn start(self) -> usize {
        self.start
    }

    #[must_use]
    pub const fn end(self) -> usize {
        self.end
    }
}

/// Structurally selected target-neutral execution engine.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum EngineKind {
    /// Universal prioritized Thompson-NFA execution.
    OrderedNfa,
    /// Complete byte-local ordered-DFA execution.
    OrderedDfa,
    /// Complete ordered DFA whose state keys include byte-local assertion
    /// context.
    ///
    /// This variant is observable only on a fresh optimizing compilation.
    /// Stable program serialization deliberately stores its universal
    /// ordered-NFA representation, so deserializing those bytes reports
    /// [`Self::OrderedNfa`] and has no contextual sidecar.
    OrderedContextDfa,
}

/// Structural reason that one target-neutral execution engine was selected.
///
/// No source spelling, pattern identity, or benchmark identity participates in
/// this decision. [`CompiledProgram::determinization_report`] and
/// [`CompiledProgram::context_determinization_report`] preserve the exact
/// resource and completed work behind their respective fallbacks.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum EngineSelectionReason {
    /// The caller explicitly selected the fast universal ordered-NFA route.
    FastMode,
    /// Optimizing mode completed ordered determinization.
    CompleteDfa,
    /// Optimizing mode completed contextual ordered determinization. The
    /// fresh program and emitted object use the self-contained contextual DFA.
    CompleteContextDfa,
    /// Context assertions were present, but contextual determinization was
    /// structurally unsupported or declined under its resource limits. The
    /// universal ordered-NFA representation remains executable; inspect
    /// [`CompiledProgram::context_determinization_report`] for exact details.
    ContextAssertions,
    /// Complete determinization was structurally declined under its limits;
    /// inspect [`CompiledProgram::determinization_report`] for exact details.
    DeterminizationResourceLimit,
}

impl EngineKind {
    const fn tag(self) -> u8 {
        match self {
            // Contextual sidecars are intentionally absent from the stable
            // wire format. Their semantic artifact is the ordered NFA.
            Self::OrderedNfa | Self::OrderedContextDfa => 0,
            Self::OrderedDfa => 1,
        }
    }

    fn from_tag(tag: u8) -> Result<Self, ProgramFormatError> {
        match tag {
            0 => Ok(Self::OrderedNfa),
            1 => Ok(Self::OrderedDfa),
            _ => Err(ProgramFormatError::Malformed("unknown engine tag")),
        }
    }
}

/// Immutable dimensions of one compiled semantic program.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ProgramStats {
    pub engine: EngineKind,
    /// Compile-time selection provenance, if retained by this value.
    pub engine_selection_reason: Option<EngineSelectionReason>,
    pub thompson_states: usize,
    pub thompson_edges: usize,
    pub serialized_bytes: usize,
    pub dfa: Option<DfaStats>,
    /// Canonical rows retained after bounded determinization declined.
    pub partial_dfa: Option<PartialDfaStats>,
    /// Fresh contextual-determinization outcome. This is `None` for
    /// assertion-free programs, Fast mode, and deserialized artifacts.
    pub context_determinization: Option<ContextDeterminizationReport>,
    /// Compile-time determinization provenance, if retained by this value.
    pub determinization: Option<DeterminizationReport>,
    /// Structural fixed prefix available to native candidate filtering.
    pub anchored_prefix: AnchoredPrefixStats,
    /// Proven maximum consumed byte width, or `None` when the graph is
    /// structurally unbounded or the optional bounded proof declined.
    pub max_match_width: Option<usize>,
}

/// Dimensions and exact construction limits of a retained partial DFA.
///
/// A resource-fallback receipt without this value executes the universal NFA
/// directly; a present value proves that the prepared optimizing entry can
/// run complete canonical rows and resume K0 at authenticated holes.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct PartialDfaStats {
    pub complete_rows: usize,
    pub discovered_states: usize,
    pub resume_frontiers: usize,
    pub resume_items: usize,
    pub effective_limits: DeterminizeLimits,
    /// Whether the prepared optimizing entry can scan this prefix shape.
    pub optimized_entry_supported: bool,
    /// Minimum window length at which the optimizing entry considers rows.
    pub min_input_bytes: usize,
}

/// Fresh-compilation provenance for optional contextual determinization.
///
/// Exactly one of `stats` and `decline` is present. The report is intentionally
/// omitted from the stable semantic-program wire format together with the
/// contextual DFA sidecar.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ContextDeterminizationReport {
    /// Limits supplied by the caller.
    pub requested_limits: DeterminizeLimits,
    /// Limits after clamping to the stable artifact construction ceilings.
    pub effective_limits: DeterminizeLimits,
    /// Complete contextual machine dimensions, when construction succeeded.
    pub stats: Option<ContextDfaStats>,
    /// Exact construction decline, when no contextual machine was retained.
    pub decline: Option<ContextDfaDecline>,
}

impl ContextDeterminizationReport {
    fn complete(requested_limits: DeterminizeLimits, stats: ContextDfaStats) -> Self {
        Self {
            requested_limits,
            effective_limits: requested_limits.effective_for_stable_artifact(),
            stats: Some(stats),
            decline: None,
        }
    }

    fn declined(requested_limits: DeterminizeLimits, decline: ContextDfaDecline) -> Self {
        Self {
            requested_limits,
            effective_limits: requested_limits.effective_for_stable_artifact(),
            stats: None,
            decline: Some(decline),
        }
    }
}

/// Result of the bounded, graph-only anchored-prefix analysis.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct AnchoredPrefixStats {
    /// Number of leading bytes every accepting path must consume.
    ///
    /// This is capped at [`MAX_ANCHORED_PREFIX_BYTES`]. A value at the cap is
    /// still a lower bound: an accepting path may require more bytes.
    pub guaranteed_bytes: usize,
    /// Positions whose conservative byte set excludes at least one byte.
    pub selective_positions: usize,
    /// Deterministic derivation work charged before completion or decline.
    pub derivation_work: u64,
    /// Whether the fixed work ceiling declined this optional analysis.
    pub resource_limited: bool,
    /// Whether the analysis conservatively traversed context assertions.
    pub context_assertions: bool,
}

/// Internal result of the bounded, graph-only anchored-suffix analysis.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[allow(
    dead_code,
    reason = "internal suffix receipt is staged for native code-generation policy"
)]
pub(crate) struct AnchoredSuffixStats {
    /// Number of trailing bytes every accepting path must consume.
    pub(crate) guaranteed_bytes: usize,
    /// Positions whose conservative byte set excludes at least one byte.
    pub(crate) selective_positions: usize,
    /// Deterministic derivation work charged before completion or decline.
    pub(crate) derivation_work: u64,
    /// Whether the fixed work or allocation ceiling declined the analysis.
    pub(crate) resource_limited: bool,
    /// Whether the analysis conservatively traversed context assertions.
    pub(crate) context_assertions: bool,
}

/// Internal receipt for the bounded maximum-match-width proof.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) struct MaxMatchWidthStats {
    pub(crate) width: Option<usize>,
    pub(crate) derivation_work: u64,
    pub(crate) resource_limited: bool,
    pub(crate) unbounded: bool,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) struct AnchoredByteSet {
    words: [u64; 4],
}

impl AnchoredByteSet {
    const EMPTY: Self = Self { words: [0; 4] };

    /// Construct one graph-neutral byte column from its four 64-bit words.
    #[must_use]
    #[allow(
        dead_code,
        reason = "native interior-literal lowering consumes this construction seam"
    )]
    pub(crate) const fn from_words(words: [u64; 4]) -> Self {
        Self { words }
    }

    fn insert_range(&mut self, start: u8, end: u8, work: &mut AnchoredWork) -> bool {
        for byte in start..=end {
            if !work.charge(1) {
                return false;
            }
            let index = usize::from(byte);
            self.words[index / 64] |= 1_u64 << (index % 64);
        }
        true
    }

    pub(crate) const fn words(self) -> [u64; 4] {
        self.words
    }

    pub(crate) fn contains(self, byte: u8) -> bool {
        let index = usize::from(byte);
        self.words[index / 64] & (1_u64 << (index % 64)) != 0
    }

    pub(crate) fn cardinality(self) -> u16 {
        self.words
            .iter()
            .map(|word| u16::try_from(word.count_ones()).unwrap_or(u16::MAX))
            .sum()
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) struct AnchoredPrefix {
    sets: [AnchoredByteSet; MAX_ANCHORED_PREFIX_BYTES],
    len: u8,
    derivation_work: u64,
    resource_limited: bool,
    context_assertions: bool,
}

impl AnchoredPrefix {
    const EMPTY: Self = Self {
        sets: [AnchoredByteSet::EMPTY; MAX_ANCHORED_PREFIX_BYTES],
        len: 0,
        derivation_work: 0,
        resource_limited: false,
        context_assertions: false,
    };

    pub(crate) fn sets(&self) -> &[AnchoredByteSet] {
        &self.sets[..usize::from(self.len)]
    }

    fn stats(self) -> AnchoredPrefixStats {
        AnchoredPrefixStats {
            guaranteed_bytes: usize::from(self.len),
            selective_positions: self
                .sets()
                .iter()
                .filter(|set| set.cardinality() < 256)
                .count(),
            derivation_work: self.derivation_work,
            resource_limited: self.resource_limited,
            context_assertions: self.context_assertions,
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) struct AnchoredSuffix {
    /// `sets[0]` classifies the final consumed byte, `sets[1]` the preceding
    /// byte, and so on.
    sets: [AnchoredByteSet; MAX_ANCHORED_SUFFIX_BYTES],
    len: u8,
    derivation_work: u64,
    resource_limited: bool,
    context_assertions: bool,
}

impl AnchoredSuffix {
    const EMPTY: Self = Self {
        sets: [AnchoredByteSet::EMPTY; MAX_ANCHORED_SUFFIX_BYTES],
        len: 0,
        derivation_work: 0,
        resource_limited: false,
        context_assertions: false,
    };

    pub(crate) fn sets(&self) -> &[AnchoredByteSet] {
        &self.sets[..usize::from(self.len)]
    }

    /// Return the exact graph-proved set for the final consumed byte when it
    /// is fragmented and the graph is large enough to amortize start-aware
    /// native candidate scanning. Contiguous sets remain owned by the
    /// established V3 terminal-range selector.
    fn native_terminal_exact_set(&self, edge_count: usize) -> Option<[u64; 4]> {
        if edge_count < MIN_NATIVE_ORDERED_NFA_TERMINAL_RANGE_EDGES {
            return None;
        }
        let set = self.sets().first().copied()?;
        let cardinality = set.cardinality();
        if cardinality == 0 || cardinality > MAX_NATIVE_ORDERED_NFA_TERMINAL_EXACT_SET_CARDINALITY {
            return None;
        }
        let mut members = (u8::MIN..=u8::MAX).filter(|&byte| set.contains(byte));
        let start = members.next()?;
        let end = members.next_back().unwrap_or(start);
        let width = u16::from(end)
            .checked_sub(u16::from(start))?
            .checked_add(1)?;
        if width == cardinality {
            return None;
        }
        Some(set.words())
    }

    /// Return the exact single inclusive range proved for the final consumed
    /// byte, when the graph is large enough to amortize an extra range scan.
    fn native_terminal_range_v1(
        &self,
        edge_count: usize,
    ) -> Option<NativeOrderedNfaTerminalRangeV1> {
        if edge_count < MIN_NATIVE_ORDERED_NFA_TERMINAL_RANGE_EDGES {
            return None;
        }
        let set = self.sets().first().copied()?;
        let cardinality = set.cardinality();
        if cardinality == 0 || cardinality == 256 {
            return None;
        }
        let mut members = (u8::MIN..=u8::MAX).filter(|&byte| set.contains(byte));
        let start = members.next()?;
        let end = members.next_back().unwrap_or(start);
        let width = u16::from(end)
            .checked_sub(u16::from(start))?
            .checked_add(1)?;
        if width != cardinality {
            return None;
        }
        Some(NativeOrderedNfaTerminalRangeV1 {
            start,
            end,
            reverse_depth: 0,
        })
    }

    #[allow(
        dead_code,
        reason = "internal suffix receipt is staged for native code-generation policy"
    )]
    fn stats(self) -> AnchoredSuffixStats {
        AnchoredSuffixStats {
            guaranteed_bytes: usize::from(self.len),
            selective_positions: self
                .sets()
                .iter()
                .filter(|set| set.cardinality() < 256)
                .count(),
            derivation_work: self.derivation_work,
            resource_limited: self.resource_limited,
            context_assertions: self.context_assertions,
        }
    }
}

/// Optional portable accelerator for ordered-NFA programs with a graph-proved
/// non-empty terminal suffix.
///
/// The suffix column is only a necessary filter. Every hit is verified by an
/// independently determinized reverse machine seeded from all Accept states.
/// For endpoint-sensitive contracts, reverse verification is used only to
/// discover the globally earliest viable start when maximum width is finite;
/// the ordinary ordered NFA is then replayed from that start through its
/// complete proved width. That final replay, rather than the unordered reverse
/// subset, selects alternation and greedy/lazy priority. Without an admitted
/// finite width, exhausting the suffix scanner still proves no match for every
/// output. Sparse candidates are reverse-verified within a linear work
/// envelope. `Exists` may return directly from that exact proof, while an
/// endpoint-sensitive proved match is handed back to the ordinary ordered NFA
/// so the accelerator never double-walks an unbounded match to recover
/// priority.
#[derive(Clone, Debug)]
struct NfaMandatorySuffix {
    primary_bytes: [u8; 3],
    primary_count: u8,
    primary_depth: u8,
    minimum_width: u8,
    maximum_width: Option<usize>,
    /// Every primary byte is consumed only by a terminal edge whose target
    /// cannot continue consuming. A verified first primary endpoint is then a
    /// source barrier: no later match can begin before it and cross it.
    terminal_barrier: bool,
    reverse: SeededReverseDfa,
}

/// Find the first member of an arbitrary byte set through the host-selected
/// wide/narrow classifier and a scalar tail.
#[cfg(test)]
fn find_full_byte_set_member(
    set: ByteSet256,
    classifier: &ByteSetClassifier,
    bytes: &[u8],
) -> Option<usize> {
    let mut position = 0usize;
    while bytes.len().saturating_sub(position) >= BYTE_SET_WIDE_BLOCK_BYTES {
        let end = position.checked_add(BYTE_SET_WIDE_BLOCK_BYTES)?;
        let block: &[u8; BYTE_SET_WIDE_BLOCK_BYTES] =
            bytes.get(position..end)?.try_into().ok()?;
        let mask = classifier.classify_32(block).member_mask();
        if mask != 0 {
            return position.checked_add(usize::try_from(mask.trailing_zeros()).ok()?);
        }
        position = end;
    }
    if bytes.len().saturating_sub(position) >= BYTE_SET_BLOCK_BYTES {
        let end = position.checked_add(BYTE_SET_BLOCK_BYTES)?;
        let block: &[u8; BYTE_SET_BLOCK_BYTES] =
            bytes.get(position..end)?.try_into().ok()?;
        let mask = classifier.classify_16(block).member_mask();
        if mask != 0 {
            return position.checked_add(usize::try_from(mask.trailing_zeros()).ok()?);
        }
        position = end;
    }
    bytes
        .get(position..)?
        .iter()
        .position(|&byte| set.contains(byte))
        .and_then(|offset| position.checked_add(offset))
}

/// Complete scanner for an exact fixed-width Cartesian byte product.
///
/// This sidecar is admitted only when a bounded graph walk proves that every
/// epsilon-closed frontier admits exactly the same anchored byte set at its
/// current depth, and every member reaches an accepting frontier after the
/// exact width. Distinct byte choices may retain distinct Thompson frontiers;
/// this preserves equivalent duplicated continuations without confusing a
/// correlated alternation for a Cartesian language. Scanning one selective
/// column and checking the remaining columns can then replace ordered-NFA
/// execution without losing alternation or greediness semantics. Tiny sets
/// retain the memchr family; every larger selective set uses the same
/// target-dispatched full-byte classifier as the general runtime.
#[derive(Clone, Copy, Debug)]
struct NfaExactProduct {
    primary_offset: u8,
    width: u8,
}

#[derive(Clone, Debug)]
struct NfaExactProductPlan {
    product: NfaExactProduct,
    scanner: NfaMandatoryCutScanner,
}

impl NfaExactProductPlan {
    fn derive(
        raw: &RawPlan,
        prefix: &AnchoredPrefix,
        exact_width: Option<usize>,
        engine: &ProgramEngine,
    ) -> Option<Self> {
        if !matches!(engine, ProgramEngine::OrderedNfa) || prefix.context_assertions {
            return None;
        }
        let width = exact_width?;
        if width == 0 || width != prefix.sets().len() || width > MAX_ANCHORED_PREFIX_BYTES {
            return None;
        }
        let (primary_offset, primary) = prefix
            .sets()
            .iter()
            .copied()
            .enumerate()
            .filter(|(_, set)| (1..=255).contains(&usize::from(set.cardinality())))
            .min_by_key(|(offset, set)| (set.cardinality(), *offset != 0, *offset))?;
        if !nfa_prefix_is_exact_product(raw, prefix.sets()) {
            return None;
        }
        let cardinality = usize::from(primary.cardinality());
        let scanner = if cardinality <= 3 {
            let mut bytes = [0_u8; 3];
            let mut count = 0usize;
            for byte in u8::MIN..=u8::MAX {
                if !primary.contains(byte) {
                    continue;
                }
                *bytes.get_mut(count)? = byte;
                count = count.checked_add(1)?;
            }
            if count != cardinality {
                return None;
            }
            NfaMandatoryCutScanner::Small {
                bytes,
                count: u8::try_from(count).ok()?,
            }
        } else {
            let set = ByteSet256::from_words(primary.words());
            NfaMandatoryCutScanner::Full {
                set,
                classifier: ByteSetClassifier::new(set),
            }
        };
        Some(Self {
            product: NfaExactProduct {
                primary_offset: u8::try_from(primary_offset).ok()?,
                width: u8::try_from(width).ok()?,
            },
            scanner,
        })
    }
}

impl NfaExactProduct {
    #[inline]
    fn no_match(output: OutputContract) -> MatchResult {
        match output {
            OutputContract::Exists => MatchResult::Exists(false),
            OutputContract::SelectedEnd => MatchResult::SelectedEnd(None),
            OutputContract::Span => MatchResult::Span(None),
        }
    }

    #[inline]
    fn matched(start: usize, width: usize, output: OutputContract) -> MatchResult {
        let end = start
            .checked_add(width)
            .expect("validated exact-product candidate width");
        match output {
            OutputContract::Exists => MatchResult::Exists(true),
            OutputContract::SelectedEnd => MatchResult::SelectedEnd(Some(end)),
            OutputContract::Span => MatchResult::Span(Some((start, end))),
        }
    }

    #[inline(always)]
    fn matches_at(
        prefix: &AnchoredPrefix,
        haystack: &[u8],
        start: usize,
        primary_offset: usize,
    ) -> bool {
        prefix
            .sets()
            .iter()
            .copied()
            .enumerate()
            .filter(|(depth, _)| *depth != primary_offset)
            .all(|(depth, set)| {
                start
                    .checked_add(depth)
                    .and_then(|position| haystack.get(position))
                    .is_some_and(|&byte| set.contains(byte))
            })
    }

    #[inline]
    fn find_small_primary(bytes: [u8; 3], count: u8, haystack: &[u8]) -> Option<usize> {
        match count {
            1 => memchr(bytes[0], haystack),
            2 => memchr2(bytes[0], bytes[1], haystack),
            3 => memchr3(bytes[0], bytes[1], bytes[2], haystack),
            _ => None,
        }
    }

    #[inline(never)]
    fn search_small(
        self,
        bytes: [u8; 3],
        count: u8,
        prefix: &AnchoredPrefix,
        haystack: &[u8],
        mut scan: usize,
        scan_end: usize,
        output: OutputContract,
    ) -> MatchResult {
        let width = usize::from(self.width);
        let offset = usize::from(self.primary_offset);
        while scan < scan_end {
            let Some(source) = haystack.get(scan..scan_end) else {
                return Self::no_match(output);
            };
            let Some(relative) = Self::find_small_primary(bytes, count, source) else {
                return Self::no_match(output);
            };
            let Some(hit) = scan.checked_add(relative) else {
                return Self::no_match(output);
            };
            let Some(start) = hit.checked_sub(offset) else {
                return Self::no_match(output);
            };
            if Self::matches_at(prefix, haystack, start, offset) {
                return Self::matched(start, width, output);
            }
            let Some(next) = hit.checked_add(1) else {
                return Self::no_match(output);
            };
            scan = next;
        }
        Self::no_match(output)
    }

    #[inline(never)]
    fn search_full_blocks(
        self,
        set: ByteSet256,
        classifier: &ByteSetClassifier,
        prefix: &AnchoredPrefix,
        haystack: &[u8],
        mut scan: usize,
        scan_end: usize,
        output: OutputContract,
    ) -> MatchResult {
        let width = usize::from(self.width);
        let offset = usize::from(self.primary_offset);
        while scan_end.saturating_sub(scan) >= BYTE_SET_WIDE_BLOCK_BYTES {
            let Some(end) = scan.checked_add(BYTE_SET_WIDE_BLOCK_BYTES) else {
                return Self::no_match(output);
            };
            let Some(block) = haystack
                .get(scan..end)
                .and_then(|bytes| <&[u8; BYTE_SET_WIDE_BLOCK_BYTES]>::try_from(bytes).ok())
            else {
                return Self::no_match(output);
            };
            let mut mask = classifier.classify_32(block).member_mask();
            while mask != 0 {
                let lane = usize::try_from(mask.trailing_zeros())
                    .expect("a 32-bit candidate lane fits usize");
                let hit = scan
                    .checked_add(lane)
                    .expect("candidate lane remains inside the search window");
                let start = hit
                    .checked_sub(offset)
                    .expect("primary scan begins at the anchored offset");
                if Self::matches_at(prefix, haystack, start, offset) {
                    return Self::matched(start, width, output);
                }
                mask &= mask - 1;
            }
            scan = end;
        }
        if scan_end.saturating_sub(scan) >= BYTE_SET_BLOCK_BYTES {
            let Some(end) = scan.checked_add(BYTE_SET_BLOCK_BYTES) else {
                return Self::no_match(output);
            };
            let Some(block) = haystack
                .get(scan..end)
                .and_then(|bytes| <&[u8; BYTE_SET_BLOCK_BYTES]>::try_from(bytes).ok())
            else {
                return Self::no_match(output);
            };
            let mut mask = classifier.classify_16(block).member_mask();
            while mask != 0 {
                let lane = usize::try_from(mask.trailing_zeros())
                    .expect("a 16-bit candidate lane fits usize");
                let hit = scan
                    .checked_add(lane)
                    .expect("candidate lane remains inside the search window");
                let start = hit
                    .checked_sub(offset)
                    .expect("primary scan begins at the anchored offset");
                if Self::matches_at(prefix, haystack, start, offset) {
                    return Self::matched(start, width, output);
                }
                mask &= mask - 1;
            }
            scan = end;
        }
        while scan < scan_end {
            let Some(&byte) = haystack.get(scan) else {
                return Self::no_match(output);
            };
            if set.contains(byte) {
                let start = scan
                    .checked_sub(offset)
                    .expect("primary scan begins at the anchored offset");
                if Self::matches_at(prefix, haystack, start, offset) {
                    return Self::matched(start, width, output);
                }
            }
            let Some(next) = scan.checked_add(1) else {
                return Self::no_match(output);
            };
            scan = next;
        }
        Self::no_match(output)
    }

    #[inline(always)]
    fn search(
        self,
        scanner: &NfaMandatoryCutScanner,
        prefix: &AnchoredPrefix,
        haystack: &[u8],
        window: SearchWindow,
        output: OutputContract,
    ) -> MatchResult {
        let width = usize::from(self.width);
        let offset = usize::from(self.primary_offset);
        let Some(last_start) = window.end.checked_sub(width) else {
            return Self::no_match(output);
        };
        if last_start < window.start {
            return Self::no_match(output);
        }
        let Some(scan) = window.start.checked_add(offset) else {
            return Self::no_match(output);
        };
        let Some(scan_end) = last_start
            .checked_add(offset)
            .and_then(|last| last.checked_add(1))
        else {
            return Self::no_match(output);
        };
        match scanner {
            NfaMandatoryCutScanner::Small { bytes, count } => self.search_small(
                *bytes, *count, prefix, haystack, scan, scan_end, output,
            ),
            NfaMandatoryCutScanner::Full { set, classifier } => self.search_full_blocks(
                *set, classifier, prefix, haystack, scan, scan_end, output,
            ),
            NfaMandatoryCutScanner::Ascii { .. } => Self::no_match(output),
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[allow(
    clippy::struct_field_names,
    reason = "uniform max_ names keep each independent proof ceiling explicit"
)]
struct NfaExactProductLimits {
    max_state_work: u64,
    max_edge_work: u64,
    max_byte_work: u64,
    max_frontier_work: u64,
    max_frontiers: usize,
    max_memory_bytes: usize,
}

impl Default for NfaExactProductLimits {
    fn default() -> Self {
        Self {
            max_state_work: MAX_NFA_EXACT_PRODUCT_STATE_WORK,
            max_edge_work: MAX_NFA_EXACT_PRODUCT_EDGE_WORK,
            max_byte_work: MAX_NFA_EXACT_PRODUCT_BYTE_WORK,
            max_frontier_work: MAX_NFA_EXACT_PRODUCT_FRONTIER_WORK,
            max_frontiers: MAX_NFA_EXACT_PRODUCT_FRONTIERS,
            max_memory_bytes: MAX_NFA_EXACT_PRODUCT_MEMORY_BYTES,
        }
    }
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct NfaExactProductProofStats {
    state_work: u64,
    edge_work: u64,
    byte_work: u64,
    frontier_work: u64,
    frontiers: usize,
    memory_bytes: usize,
}

struct NfaExactProductResources {
    limits: NfaExactProductLimits,
    stats: NfaExactProductProofStats,
}

impl NfaExactProductResources {
    const fn new(limits: NfaExactProductLimits) -> Self {
        Self {
            limits,
            stats: NfaExactProductProofStats {
                state_work: 0,
                edge_work: 0,
                byte_work: 0,
                frontier_work: 0,
                frontiers: 0,
                memory_bytes: 0,
            },
        }
    }

    fn charge(used: &mut u64, amount: u64, limit: u64) -> Option<()> {
        let next = used.checked_add(amount)?;
        if next > limit {
            return None;
        }
        *used = next;
        Some(())
    }

    fn charge_state(&mut self, amount: usize) -> Option<()> {
        Self::charge(
            &mut self.stats.state_work,
            u64::try_from(amount).ok()?,
            self.limits.max_state_work,
        )
    }

    fn charge_edge(&mut self, amount: usize) -> Option<()> {
        Self::charge(
            &mut self.stats.edge_work,
            u64::try_from(amount).ok()?,
            self.limits.max_edge_work,
        )
    }

    fn charge_byte(&mut self, amount: usize) -> Option<()> {
        Self::charge(
            &mut self.stats.byte_work,
            u64::try_from(amount).ok()?,
            self.limits.max_byte_work,
        )
    }

    fn charge_frontier(&mut self, amount: usize) -> Option<()> {
        Self::charge(
            &mut self.stats.frontier_work,
            u64::try_from(amount).ok()?,
            self.limits.max_frontier_work,
        )
    }

    fn retain_memory(&mut self, amount: usize) -> Option<()> {
        let next = self.stats.memory_bytes.checked_add(amount)?;
        if next > self.limits.max_memory_bytes {
            return None;
        }
        self.stats.memory_bytes = next;
        Some(())
    }

    fn publish_frontier(&mut self) -> Option<()> {
        let next = self.stats.frontiers.checked_add(1)?;
        if next > self.limits.max_frontiers || next > MAX_NFA_EXACT_PRODUCT_FRONTIERS {
            return None;
        }
        self.stats.frontiers = next;
        Some(())
    }
}

fn nfa_exact_product_state_edges(raw: &RawPlan, state: usize) -> Option<core::ops::Range<usize>> {
    let begin = usize::try_from(*raw.edge_offsets.get(state)?).ok()?;
    let end = usize::try_from(*raw.edge_offsets.get(state.checked_add(1)?)?).ok()?;
    (begin <= end
        && end <= raw.edge_targets.len()
        && end <= raw.edge_kinds.len()
        && end <= raw.byte_starts.len()
        && end <= raw.byte_ends.len())
    .then_some(begin..end)
}

fn nfa_exact_product_clear_frontier(
    frontier: &mut [u64],
    resources: &mut NfaExactProductResources,
) -> Option<()> {
    resources.charge_frontier(frontier.len())?;
    frontier.fill(0);
    Some(())
}

fn nfa_exact_product_frontier_is_empty(
    frontier: &[u64],
    resources: &mut NfaExactProductResources,
) -> Option<bool> {
    resources.charge_frontier(frontier.len())?;
    Some(frontier.iter().all(|word| *word == 0))
}

/// Complete one epsilon closure from the states already present in `stack`.
/// Consuming states are published as a canonical bitmap and acceptance is
/// returned separately. Stack pops, zero-width edges, and bitmap insertions
/// are independently charged before they are performed.
#[allow(
    clippy::too_many_arguments,
    reason = "closure scratch and each independently audited resource remain explicit"
)]
fn nfa_exact_product_epsilon_closure(
    raw: &RawPlan,
    states: usize,
    stack_limit: usize,
    stack: &mut Vec<u32>,
    seen_generation: &mut [u32],
    generation: &mut u32,
    frontier: &mut [u64],
    resources: &mut NfaExactProductResources,
) -> Option<bool> {
    *generation = generation.checked_add(1)?;
    let current_generation = *generation;
    let mut accepting = false;
    while let Some(state) = stack.pop() {
        resources.charge_state(1)?;
        let state = usize::try_from(state).ok()?;
        let seen = seen_generation.get_mut(state)?;
        if *seen == current_generation {
            continue;
        }
        *seen = current_generation;
        match raw.roles.get(state)? {
            StateRole::Split => {
                for edge in nfa_exact_product_state_edges(raw, state)? {
                    resources.charge_edge(1)?;
                    if raw.edge_kinds.get(edge) != Some(&EdgeKind::Epsilon) {
                        return None;
                    }
                    let target = *raw.edge_targets.get(edge)?;
                    if usize::try_from(target).map_or(true, |target| target >= states)
                        || stack.len() >= stack_limit
                    {
                        return None;
                    }
                    stack.push(target);
                }
            }
            StateRole::Consume => {
                resources.charge_frontier(1)?;
                *frontier.get_mut(state / 64)? |= 1_u64 << (state % 64);
            }
            StateRole::Accept => accepting = true,
            _ => return None,
        }
    }
    Some(accepting)
}

fn nfa_exact_product_intern_frontier(
    arena: &mut Vec<Vec<u64>>,
    frontier: &[u64],
    resources: &mut NfaExactProductResources,
) -> Option<usize> {
    let comparison_work = arena.len().checked_mul(frontier.len())?;
    resources.charge_frontier(comparison_work)?;
    if let Some(index) = arena.iter().position(|known| known.as_slice() == frontier) {
        return Some(index);
    }

    resources.publish_frontier()?;
    resources.charge_frontier(frontier.len().checked_add(1)?)?;
    resources.retain_memory(frontier.len().checked_mul(core::mem::size_of::<u64>())?)?;
    let mut stored = Vec::new();
    stored.try_reserve_exact(frontier.len()).ok()?;
    stored.extend_from_slice(frontier);
    arena.push(stored);
    arena.len().checked_sub(1)
}

fn nfa_exact_product_fixed_memory_bytes(
    states: usize,
    stack_slots: usize,
    frontier_words: usize,
) -> Option<usize> {
    states
        .checked_mul(core::mem::size_of::<u32>())?
        .checked_add(stack_slots.checked_mul(core::mem::size_of::<u32>())?)?
        .checked_add(frontier_words.checked_mul(core::mem::size_of::<u64>())?)?
        .checked_add(
            MAX_NFA_EXACT_PRODUCT_FRONTIERS.checked_mul(core::mem::size_of::<Vec<u64>>())?,
        )?
        .checked_add(
            MAX_NFA_EXACT_PRODUCT_FRONTIERS
                .checked_mul(core::mem::size_of::<usize>())?
                .checked_mul(2)?,
        )?
        .checked_add(MAX_NFA_EXACT_PRODUCT_FRONTIERS.checked_mul(core::mem::size_of::<u32>())?)
}

/// Prove that the graph language is exactly the Cartesian product of `sets`.
///
/// Each canonical frontier is an epsilon-closed set of consuming Thompson
/// states. Every one of the 256 bytes is explored from every frontier. Its
/// structural availability must equal the anchored set for that depth; each
/// admitted byte then produces and interns its own next frontier. This keeps
/// equivalent duplicated branches while exposing correlations as differing
/// per-frontier byte sets. Every final transition must reach Accept.
#[allow(
    clippy::too_many_lines,
    reason = "shape validation, exact resource accounting, closure, and frontier publication form one proof"
)]
fn nfa_prefix_exact_product_proof(
    raw: &RawPlan,
    sets: &[AnchoredByteSet],
    limits: NfaExactProductLimits,
) -> Option<NfaExactProductProofStats> {
    if sets.is_empty() {
        return None;
    }
    let states = raw.roles.len();
    let edges = raw.edge_targets.len();
    let start = usize::try_from(raw.start).ok()?;
    if states == 0
        || start >= states
        || raw.edge_offsets.len() != states.checked_add(1)?
        || raw.edge_kinds.len() != edges
        || raw.byte_starts.len() != edges
        || raw.byte_ends.len() != edges
        || raw.edge_offsets.first().copied() != Some(0)
        || usize::try_from(*raw.edge_offsets.last()?).ok()? != edges
    {
        return None;
    }
    let frontier_words = states.checked_add(63)?.checked_div(64)?;
    let stack_limit = edges.checked_add(1)?;
    let fixed_memory = nfa_exact_product_fixed_memory_bytes(states, stack_limit, frontier_words)?;
    let mut resources = NfaExactProductResources::new(limits);
    resources.retain_memory(fixed_memory)?;
    resources.charge_state(states)?;
    resources.charge_frontier(frontier_words.checked_add(MAX_NFA_EXACT_PRODUCT_FRONTIERS)?)?;

    let mut seen_generation = Vec::new();
    seen_generation.try_reserve_exact(states).ok()?;
    seen_generation.resize(states, 0_u32);
    let mut stack = Vec::new();
    stack.try_reserve_exact(stack_limit).ok()?;
    let mut scratch = Vec::new();
    scratch.try_reserve_exact(frontier_words).ok()?;
    scratch.resize(frontier_words, 0_u64);
    let mut arena: Vec<Vec<u64>> = Vec::new();
    arena
        .try_reserve_exact(MAX_NFA_EXACT_PRODUCT_FRONTIERS)
        .ok()?;
    let mut current = Vec::new();
    current
        .try_reserve_exact(MAX_NFA_EXACT_PRODUCT_FRONTIERS)
        .ok()?;
    let mut next = Vec::new();
    next.try_reserve_exact(MAX_NFA_EXACT_PRODUCT_FRONTIERS)
        .ok()?;
    let mut next_seen = Vec::new();
    next_seen
        .try_reserve_exact(MAX_NFA_EXACT_PRODUCT_FRONTIERS)
        .ok()?;
    next_seen.resize(MAX_NFA_EXACT_PRODUCT_FRONTIERS, 0_u32);
    let mut generation = 0_u32;

    nfa_exact_product_clear_frontier(&mut scratch, &mut resources)?;
    stack.push(raw.start);
    if nfa_exact_product_epsilon_closure(
        raw,
        states,
        stack_limit,
        &mut stack,
        &mut seen_generation,
        &mut generation,
        &mut scratch,
        &mut resources,
    )? || nfa_exact_product_frontier_is_empty(&scratch, &mut resources)?
    {
        return None;
    }
    let initial = nfa_exact_product_intern_frontier(&mut arena, &scratch, &mut resources)?;
    current.push(initial);

    for (depth, expected) in sets.iter().copied().enumerate() {
        let final_depth = depth.checked_add(1)? == sets.len();
        let next_generation = u32::try_from(depth.checked_add(1)?).ok()?;
        next.clear();
        for &frontier_index in &current {
            for byte in u8::MIN..=u8::MAX {
                resources.charge_byte(1)?;
                resources.charge_frontier(arena.get(frontier_index)?.len())?;
                stack.clear();
                {
                    let frontier = arena.get(frontier_index)?;
                    for (word_index, &word) in frontier.iter().enumerate() {
                        let mut members = word;
                        while members != 0 {
                            resources.charge_state(1)?;
                            let bit = usize::try_from(members.trailing_zeros()).ok()?;
                            members &= members.checked_sub(1)?;
                            let state = word_index.checked_mul(64)?.checked_add(bit)?;
                            if raw.roles.get(state) != Some(&StateRole::Consume) {
                                return None;
                            }
                            for edge in nfa_exact_product_state_edges(raw, state)? {
                                resources.charge_edge(1)?;
                                if raw.edge_kinds.get(edge) != Some(&EdgeKind::ByteRange) {
                                    return None;
                                }
                                let (&range_start, &range_end, &target) = (
                                    raw.byte_starts.get(edge)?,
                                    raw.byte_ends.get(edge)?,
                                    raw.edge_targets.get(edge)?,
                                );
                                if range_start > range_end
                                    || usize::try_from(target)
                                        .map_or(true, |target| target >= states)
                                {
                                    return None;
                                }
                                if range_start <= byte && byte <= range_end {
                                    if stack.len() >= stack_limit {
                                        return None;
                                    }
                                    stack.push(target);
                                }
                            }
                        }
                    }
                }

                let structural_member = !stack.is_empty();
                if structural_member != expected.contains(byte) {
                    return None;
                }
                if !structural_member {
                    continue;
                }
                nfa_exact_product_clear_frontier(&mut scratch, &mut resources)?;
                let accepting = nfa_exact_product_epsilon_closure(
                    raw,
                    states,
                    stack_limit,
                    &mut stack,
                    &mut seen_generation,
                    &mut generation,
                    &mut scratch,
                    &mut resources,
                )?;
                if final_depth {
                    if !accepting {
                        return None;
                    }
                    continue;
                }
                if accepting || nfa_exact_product_frontier_is_empty(&scratch, &mut resources)? {
                    return None;
                }
                let target =
                    nfa_exact_product_intern_frontier(&mut arena, &scratch, &mut resources)?;
                let mark = next_seen.get_mut(target)?;
                resources.charge_frontier(1)?;
                if *mark != next_generation {
                    *mark = next_generation;
                    next.push(target);
                }
            }
        }
        if final_depth {
            return Some(resources.stats);
        }
        if next.is_empty() {
            return None;
        }
        core::mem::swap(&mut current, &mut next);
    }
    None
}

fn nfa_prefix_is_exact_product(raw: &RawPlan, sets: &[AnchoredByteSet]) -> bool {
    nfa_prefix_exact_product_proof(raw, sets, NfaExactProductLimits::default()).is_some()
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum NfaMandatorySuffixScan {
    Candidate(usize),
    Exhausted,
    Fallback,
}

fn byte_set_overlaps_range(set: AnchoredByteSet, start: u8, end: u8) -> bool {
    if start > end {
        return false;
    }
    let words = set.words();
    let first = usize::from(start / 64);
    let last = usize::from(end / 64);
    for word in first..=last {
        let low = if word == first {
            u64::MAX << u32::from(start % 64)
        } else {
            u64::MAX
        };
        let high = if word == last {
            u64::MAX >> u32::from(63_u8.saturating_sub(end % 64))
        } else {
            u64::MAX
        };
        if words.get(word).is_some_and(|bits| bits & low & high != 0) {
            return true;
        }
    }
    false
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum NfaTerminalSuffixBarrierOutcome {
    Proven,
    Declined,
    Allocation,
}

/// Prove that every member of the final suffix column is a source barrier.
///
/// The reverse epsilon closure of every accept identifies the exact consuming
/// edges that can terminate a match. Their union must equal `terminal`. After
/// any such edge, epsilon closure must be terminal-only, and no other
/// consuming edge may accept a terminal byte. Consequently a match cannot
/// consume one terminal byte in its body and finish at a later one. Once the
/// first suffix endpoint is reverse-verified, its earliest start is therefore
/// globally leftmost and ordered replay may be anchored there.
///
/// This is deliberately conservative. Malformed relations, the fixed work
/// ceiling, assertions, overlapping body ranges, and terminal continuations
/// decline the proof. Allocation is reported separately so a newly admitted
/// caller can preserve fail-closed allocator semantics; the legacy boolean
/// wrapper below continues to treat it as an ordinary absent proof.
#[allow(
    clippy::too_many_lines,
    reason = "keeping the two graph closures and their shared invariants contiguous makes the barrier proof auditable"
)]
pub(crate) fn nfa_terminal_suffix_barrier_outcome(
    raw: &RawPlan,
    terminal: AnchoredByteSet,
) -> NfaTerminalSuffixBarrierOutcome {
    let mut work = AnchoredWork::new(MAX_NFA_SUFFIX_TERMINAL_BARRIER_WORK);
    let proven = nfa_terminal_suffix_barrier_with_work(raw, terminal, &mut work);
    if proven {
        NfaTerminalSuffixBarrierOutcome::Proven
    } else if work.allocation_failed {
        NfaTerminalSuffixBarrierOutcome::Allocation
    } else {
        NfaTerminalSuffixBarrierOutcome::Declined
    }
}

fn nfa_terminal_suffix_barrier_with_work(
    raw: &RawPlan,
    terminal: AnchoredByteSet,
    work: &mut AnchoredWork,
) -> bool {
    if terminal.cardinality() == 0
        || raw.roles.is_empty()
        || raw.edge_offsets.len() != raw.roles.len().saturating_add(1)
        || raw.edge_targets.len() != raw.edge_kinds.len()
        || raw.byte_starts.len() != raw.edge_kinds.len()
        || raw.byte_ends.len() != raw.edge_kinds.len()
    {
        return false;
    }

    let Some(incoming) = AnalysisIncoming::build(raw, work) else {
        return false;
    };
    let states = raw.roles.len();
    let edges = raw.edge_kinds.len();

    let mut reverse_seen = Vec::new();
    if reverse_seen.try_reserve_exact(states).is_err() {
        work.mark_allocation_failure();
        return false;
    }
    reverse_seen.resize(states, false);
    let mut terminal_edges = Vec::new();
    if terminal_edges.try_reserve_exact(edges).is_err() {
        work.mark_allocation_failure();
        return false;
    }
    terminal_edges.resize(edges, false);
    let mut stack = Vec::new();
    if stack.try_reserve(states).is_err() {
        work.mark_allocation_failure();
        return false;
    }
    for (state, &role) in raw.roles.iter().enumerate() {
        if !work.charge(1) {
            return false;
        }
        if role == StateRole::Accept {
            let Ok(state) = u32::try_from(state) else {
                return false;
            };
            if !anchored_push(&mut stack, state, work) {
                return false;
            }
        }
    }
    if stack.is_empty() {
        return false;
    }

    while let Some(state) = stack.pop() {
        if !work.charge(1) {
            return false;
        }
        let Ok(state) = usize::try_from(state) else {
            return false;
        };
        let Some(seen) = reverse_seen.get_mut(state) else {
            return false;
        };
        if *seen {
            continue;
        }
        *seen = true;
        let Some(row) = incoming.by_target.get(state) else {
            return false;
        };
        for &incoming_edge in row {
            if !work.charge(1) {
                return false;
            }
            let (Ok(source), Ok(edge)) = (
                usize::try_from(incoming_edge.source),
                usize::try_from(incoming_edge.edge),
            ) else {
                return false;
            };
            match (raw.roles.get(source), raw.edge_kinds.get(edge)) {
                (Some(StateRole::Split), Some(EdgeKind::Epsilon)) => {
                    if !anchored_push(&mut stack, incoming_edge.source, work) {
                        return false;
                    }
                }
                (Some(StateRole::Consume), Some(EdgeKind::ByteRange)) => {
                    let Some(mark) = terminal_edges.get_mut(edge) else {
                        return false;
                    };
                    *mark = true;
                }
                _ => return false,
            }
        }
    }

    let mut terminal_union = AnchoredByteSet::EMPTY;
    let mut forward_stack = Vec::new();
    if forward_stack.try_reserve(states).is_err() {
        work.mark_allocation_failure();
        return false;
    }
    for (edge, &is_terminal) in terminal_edges.iter().enumerate() {
        if !work.charge(1) {
            return false;
        }
        let (Some(&kind), Some(&start), Some(&end), Some(&target)) = (
            raw.edge_kinds.get(edge),
            raw.byte_starts.get(edge),
            raw.byte_ends.get(edge),
            raw.edge_targets.get(edge),
        ) else {
            return false;
        };
        if kind != EdgeKind::ByteRange || start > end {
            if is_terminal {
                return false;
            }
            continue;
        }
        if is_terminal {
            if !terminal_union.insert_range(start, end, work) {
                return false;
            }
            if !anchored_push(&mut forward_stack, target, work) {
                return false;
            }
        } else if byte_set_overlaps_range(terminal, start, end) {
            return false;
        }
    }
    if terminal_union != terminal || forward_stack.is_empty() {
        return false;
    }

    // A terminal edge must enter an epsilon-only closure that cannot resume
    // consumption. This also rejects an accepting/continuing loop such as
    // `a+`, where the final byte class legitimately occurs in the body.
    let mut forward_seen = Vec::new();
    if forward_seen.try_reserve_exact(states).is_err() {
        work.mark_allocation_failure();
        return false;
    }
    forward_seen.resize(states, false);
    while let Some(state) = forward_stack.pop() {
        if !work.charge(1) {
            return false;
        }
        let Ok(state) = usize::try_from(state) else {
            return false;
        };
        let Some(seen) = forward_seen.get_mut(state) else {
            return false;
        };
        if *seen {
            continue;
        }
        *seen = true;
        match raw.roles.get(state) {
            Some(StateRole::Accept) => {
                if analysis_state_edges(raw, state).is_none_or(|row| !row.is_empty()) {
                    return false;
                }
            }
            Some(StateRole::Split) => {
                let Some(row) = analysis_state_edges(raw, state) else {
                    return false;
                };
                for edge in row {
                    if !work.charge(1) || raw.edge_kinds.get(edge) != Some(&EdgeKind::Epsilon) {
                        return false;
                    }
                    let Some(&target) = raw.edge_targets.get(edge) else {
                        return false;
                    };
                    if !anchored_push(&mut forward_stack, target, work) {
                        return false;
                    }
                }
            }
            _ => return false,
        }
    }
    true
}

pub(crate) fn nfa_terminal_suffix_is_barrier(
    raw: &RawPlan,
    terminal: AnchoredByteSet,
) -> bool {
    matches!(
        nfa_terminal_suffix_barrier_outcome(raw, terminal),
        NfaTerminalSuffixBarrierOutcome::Proven
    )
}

impl NfaMandatorySuffix {
    fn native_requirement(&self) -> Option<NativeRetainedSuffixRequirement> {
        let scan_offset = self
            .minimum_width
            .checked_sub(self.primary_depth)?
            .checked_sub(1)?;
        let mut membership = [0_u64; 4];
        for &byte in self
            .primary_bytes
            .get(..usize::from(self.primary_count))?
        {
            let byte = usize::from(byte);
            membership[byte / 64] |= 1_u64 << (byte % 64);
        }
        Some(NativeRetainedSuffixRequirement {
            scan_offset,
            membership,
            minimum_width: self.minimum_width,
        })
    }

    fn derive(
        raw: &RawPlan,
        prefix: &AnchoredPrefix,
        suffix: &AnchoredSuffix,
        maximum_width: Option<usize>,
        unbounded: bool,
    ) -> Option<Self> {
        let minimum_width = suffix.sets().len();
        if minimum_width == 0
            || maximum_width.is_some_and(|maximum_width| maximum_width < minimum_width)
        {
            return None;
        }

        let (primary_depth, primary) = suffix
            .sets()
            .iter()
            .copied()
            .enumerate()
            .filter(|(_, set)| (1..=3).contains(&usize::from(set.cardinality())))
            .min_by_key(|(depth, set)| (set.cardinality(), *depth))?;
        let primary_count = usize::from(primary.cardinality());
        let best_forward_count = prefix
            .sets()
            .iter()
            .copied()
            .map(AnchoredByteSet::cardinality)
            .min()
            .map_or(256, usize::from);
        // The ordinary K0 executor already scans the strongest guaranteed
        // forward column. A reverse sidecar normally earns its extra
        // verification and replay work only when its endpoint column is more
        // selective. An equally small terminal barrier on an unbounded graph
        // is the narrow exception: unlike the forward byte class, it cannot
        // occur in the match body, so its scan can reject the whole window
        // without walking every dense root candidate.
        if primary_count > best_forward_count
            || (primary_count == best_forward_count && (!unbounded || primary_depth != 0))
        {
            return None;
        }
        let equal_selectivity = primary_count == best_forward_count;
        let equal_terminal_barrier = if equal_selectivity {
            if !nfa_terminal_suffix_is_barrier(raw, primary) {
                return None;
            }
            true
        } else {
            false
        };
        // A small finite bound admits earliest-start recovery and ordered
        // replay. Wider finite graphs still retain the scan-only/no-match
        // proof and the adaptively bounded reverse verifier; treating them
        // like an unbounded graph avoids discarding a generally useful
        // accelerator solely because bounded endpoint replay is unavailable.
        let maximum_width = maximum_width.filter(|maximum_width| {
            maximum_width
                .checked_mul(primary_count)
                .is_some_and(|work| work <= MAX_NFA_SUFFIX_CANDIDATE_WORK)
        });

        let mut primary_bytes = [0_u8; 3];
        let mut count = 0usize;
        for byte in 0..=u8::MAX {
            if primary.contains(byte) {
                *primary_bytes.get_mut(count)? = byte;
                count = count.checked_add(1)?;
            }
        }
        if count != primary_count {
            return None;
        }

        let reverse_limits = SeededReverseLimits {
            max_states: MAX_NFA_SUFFIX_REVERSE_STATES,
            max_cells: MAX_NFA_SUFFIX_REVERSE_CELLS,
            max_work: MAX_NFA_SUFFIX_REVERSE_WORK,
            max_memory_bytes: MAX_NFA_SUFFIX_REVERSE_MEMORY_BYTES,
            max_addressable_bytes: MAX_NFA_SUFFIX_REVERSE_MEMORY_BYTES,
        };
        let SeededReverseBuild::Complete(reverse) =
            build_seeded_reverse_exact(raw, SeededReverseSeed::AcceptStates, reverse_limits)
        else {
            return None;
        };
        // A non-empty anchored suffix proves every match consumes at least one
        // byte. Refuse a contradictory reverse artifact instead of allowing a
        // zero-width event to bypass the suffix filter.
        if reverse.initial_reaches_start() {
            return None;
        }
        let terminal_barrier = if equal_selectivity {
            equal_terminal_barrier
        } else {
            primary_depth == 0 && nfa_terminal_suffix_is_barrier(raw, primary)
        };

        Some(Self {
            primary_bytes,
            primary_count: u8::try_from(primary_count).ok()?,
            primary_depth: u8::try_from(primary_depth).ok()?,
            minimum_width: u8::try_from(minimum_width).ok()?,
            maximum_width,
            terminal_barrier,
            reverse,
        })
    }

    fn owns_suffix_first_prepared_route(
        &self,
        prefix: &AnchoredPrefix,
        maximum_width: MaxMatchWidthStats,
    ) -> bool {
        let best_forward_count = prefix
            .sets()
            .iter()
            .copied()
            .map(AnchoredByteSet::cardinality)
            .min()
            .map_or(256, usize::from);
        maximum_width.unbounded
            && self.terminal_barrier
            && usize::from(self.primary_count) == best_forward_count
    }

    fn find_primary(&self, haystack: &[u8]) -> Option<usize> {
        match self.primary_count {
            1 => memchr(self.primary_bytes[0], haystack),
            2 => memchr2(self.primary_bytes[0], self.primary_bytes[1], haystack),
            3 => memchr3(
                self.primary_bytes[0],
                self.primary_bytes[1],
                self.primary_bytes[2],
                haystack,
            ),
            _ => None,
        }
    }

    fn primary_hits_are_dense(
        &self,
        window_start: usize,
        endpoint: usize,
        primary_hits: usize,
    ) -> bool {
        let scanned = endpoint.saturating_sub(window_start);
        let proportional = scanned.saturating_mul(usize::from(self.primary_count))
            / NFA_SUFFIX_PRIMARY_HIT_DENOMINATOR;
        primary_hits > NFA_SUFFIX_PRIMARY_HIT_CREDIT.saturating_add(proportional)
    }

    /// Admit another scan-only reverse verification while cumulative charged
    /// work remains linear in the portion of the window reached so far.
    fn next_scan_only_reverse_work(
        reverse_work: usize,
        window_start: usize,
        endpoint: usize,
    ) -> Option<usize> {
        let candidate_work = endpoint.checked_sub(window_start)?;
        let next_reverse_work = reverse_work.checked_add(candidate_work)?;
        let permitted_work = candidate_work
            .saturating_mul(NFA_SUFFIX_SCAN_ONLY_REVERSE_WORK_MULTIPLIER)
            .saturating_add(NFA_SUFFIX_SCAN_ONLY_REVERSE_WORK_CREDIT);
        (next_reverse_work <= permitted_work).then_some(next_reverse_work)
    }

    /// Return the next endpoint whose complete graph-proved suffix columns
    /// match. `maximum_endpoint` is inclusive and never exceeds the semantic
    /// search window end.
    fn next_candidate_endpoint(
        &self,
        suffix: &AnchoredSuffix,
        haystack: &[u8],
        window_start: usize,
        maximum_endpoint: usize,
        from_endpoint: usize,
        primary_hits: &mut usize,
    ) -> NfaMandatorySuffixScan {
        let Some(minimum_endpoint) = window_start.checked_add(usize::from(self.minimum_width))
        else {
            return NfaMandatorySuffixScan::Fallback;
        };
        let endpoint = from_endpoint.max(minimum_endpoint);
        if endpoint > maximum_endpoint {
            return NfaMandatorySuffixScan::Exhausted;
        }
        let depth = usize::from(self.primary_depth);
        let Some(primary_offset) = depth.checked_add(1) else {
            return NfaMandatorySuffixScan::Fallback;
        };
        let Some(mut scan) = endpoint.checked_sub(primary_offset) else {
            return NfaMandatorySuffixScan::Fallback;
        };
        let Some(scan_limit) = maximum_endpoint.checked_sub(depth) else {
            return NfaMandatorySuffixScan::Fallback;
        };

        while scan < scan_limit {
            let Some(bytes) = haystack.get(scan..scan_limit) else {
                return NfaMandatorySuffixScan::Fallback;
            };
            let Some(relative) = self.find_primary(bytes) else {
                return NfaMandatorySuffixScan::Exhausted;
            };
            let Some(hit) = scan.checked_add(relative) else {
                return NfaMandatorySuffixScan::Fallback;
            };
            let Some(candidate) = hit
                .checked_add(depth)
                .and_then(|endpoint| endpoint.checked_add(1))
            else {
                return NfaMandatorySuffixScan::Fallback;
            };
            let Some(next_primary_hits) = primary_hits.checked_add(1) else {
                return NfaMandatorySuffixScan::Fallback;
            };
            *primary_hits = next_primary_hits;
            let aligned = suffix
                .sets()
                .iter()
                .copied()
                .enumerate()
                .all(|(depth, set)| {
                    candidate
                        .checked_sub(depth.saturating_add(1))
                        .filter(|&position| position >= window_start)
                        .and_then(|position| haystack.get(position))
                        .is_some_and(|&byte| set.contains(byte))
                });
            if aligned {
                return NfaMandatorySuffixScan::Candidate(candidate);
            }
            if self.primary_hits_are_dense(window_start, candidate, *primary_hits) {
                return NfaMandatorySuffixScan::Fallback;
            }
            let Some(next_scan) = hit.checked_add(1) else {
                return NfaMandatorySuffixScan::Fallback;
            };
            scan = next_scan;
        }
        NfaMandatorySuffixScan::Exhausted
    }
}

/// Select exactly the reverse event required by the public output contract.
///
/// Every seeded-reverse event proves a match for `Exists`, so consuming the
/// first event is sufficient. Endpoint-sensitive contracts need the earliest
/// recognized start, which is the final event produced by the reverse trace.
fn mandatory_suffix_reverse_start(
    output: OutputContract,
    trace: &mut impl Iterator<Item = usize>,
) -> Option<usize> {
    match output {
        OutputContract::Exists => trace.next(),
        OutputContract::SelectedEnd | OutputContract::Span => trace.last(),
    }
}

/// Optional whole-window rejection filter proved by one mandatory consuming
/// dominator in the productive Thompson graph.
///
/// Every Start-to-Accept graph path visits `root_state`. Its productive
/// outgoing byte ranges therefore form a necessary set for every match. The
/// retained required-literal layer is correlated and complete, so taking the
/// first byte of every alternative reconstructs that necessary set even when
/// later paths branch or cycle. Absence of every set member from a semantic
/// search window is a complete no-match proof for every output contract. A
/// hit alone does not prove a match. The graph also records the maximum bytes
/// consumed before this root when that prefix is finite, even if the suffix is
/// unbounded. Thus a first set member at `p` and prefix bound `B` prove that no
/// match can start before `p - B`. A separate global maximum match width `M`
/// supplies the independent bound `p + 1 - M`; the tighter available bound is
/// used. The ordered NFA (or retained rows before it) can therefore continue
/// from that narrowed lower boundary without changing leftmost or priority
/// semantics. Unavailable bounds or malformed scanners fail open.
#[derive(Clone, Debug)]
struct NfaMandatoryCut {
    root_state: u32,
    cardinality: u16,
    /// Exact maximum bytes consumed before entering the mandatory root.
    /// This can remain finite even when accepting paths are unbounded after
    /// the root, and therefore bounds how far a match start can precede the
    /// first byte consumed there.
    maximum_start_backtrack: Option<u32>,
    scanner: NfaMandatoryCutScanner,
}

#[derive(Clone, Debug)]
enum NfaMandatoryCutScanner {
    Small {
        bytes: [u8; 3],
        count: u8,
    },
    Ascii {
        set: AsciiByteSet,
        classifier: AsciiByteSetClassifier,
    },
    Full {
        set: ByteSet256,
        classifier: ByteSetClassifier,
    },
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum NfaMandatoryCutScan {
    Member(usize),
    Exhausted,
    Fallback,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum NfaMandatoryCutOutcome {
    Complete(MatchResult),
    Continue(SearchWindow),
}

impl NfaMandatoryCutScanner {
    #[cfg(test)]
    fn find_exact_product_primary(&self, haystack: &[u8]) -> Option<usize> {
        match self {
            Self::Small { bytes, count: 1 } => memchr(bytes[0], haystack),
            Self::Small { bytes, count: 2 } => memchr2(bytes[0], bytes[1], haystack),
            Self::Small { bytes, count: 3 } => {
                memchr3(bytes[0], bytes[1], bytes[2], haystack)
            }
            Self::Small { .. } | Self::Ascii { .. } => None,
            Self::Full { set, classifier } => {
                find_full_byte_set_member(*set, classifier, haystack)
            }
        }
    }
}

impl NfaMandatoryCut {
    fn from_exact_product(plan: NfaExactProductPlan) -> Self {
        Self {
            root_state: NFA_EXACT_PRODUCT_ROOT_SENTINEL,
            cardinality: u16::from_le_bytes([
                plan.product.width,
                plan.product.primary_offset,
            ]),
            maximum_start_backtrack: None,
            scanner: plan.scanner,
        }
    }

    const fn exact_product(&self) -> Option<NfaExactProduct> {
        if self.root_state != NFA_EXACT_PRODUCT_ROOT_SENTINEL {
            return None;
        }
        let [width, primary_offset] = self.cardinality.to_le_bytes();
        match &self.scanner {
            NfaMandatoryCutScanner::Small { count, .. } => {
                if *count == 0 || *count > 3 {
                    return None;
                }
            }
            NfaMandatoryCutScanner::Full { .. } => {}
            NfaMandatoryCutScanner::Ascii { .. } => return None,
        }
        if width == 0 || primary_offset >= width {
            return None;
        }
        Some(NfaExactProduct {
            primary_offset,
            width,
        })
    }

    fn from_candidate(candidate: &required_literals::RequiredInteriorCandidate) -> Option<Self> {
        if candidate.depth() == 0 || candidate.literals().is_empty() {
            return None;
        }
        let mut words = [0_u64; 4];
        for literal in candidate.literals() {
            let &byte = literal.as_bytes().first()?;
            let index = usize::from(byte);
            words[index / 64] |= 1_u64 << (index % 64);
        }
        let cardinality = words.iter().try_fold(0_u16, |total, word| {
            total.checked_add(u16::try_from(word.count_ones()).ok()?)
        })?;
        if cardinality == 0 || cardinality > MAX_NFA_MANDATORY_CUT_CARDINALITY {
            return None;
        }

        let scanner = if cardinality <= 3 {
            let mut bytes = [0_u8; 3];
            let mut count = 0usize;
            for byte in 0_u16..=u16::from(u8::MAX) {
                let byte = u8::try_from(byte).ok()?;
                let index = usize::from(byte);
                if words[index / 64] & (1_u64 << (index % 64)) == 0 {
                    continue;
                }
                *bytes.get_mut(count)? = byte;
                count = count.checked_add(1)?;
            }
            if count != usize::from(cardinality) {
                return None;
            }
            NfaMandatoryCutScanner::Small {
                bytes,
                count: u8::try_from(count).ok()?,
            }
        } else if words[2] == 0 && words[3] == 0 {
            let set = AsciiByteSet::from_words([words[0], words[1]]);
            NfaMandatoryCutScanner::Ascii {
                set,
                classifier: AsciiByteSetClassifier::new(set),
            }
        } else {
            let set = ByteSet256::from_words(words);
            NfaMandatoryCutScanner::Full {
                set,
                classifier: ByteSetClassifier::new(set),
            }
        };
        let root_state = candidate.root_state();
        if root_state == NFA_EXACT_PRODUCT_ROOT_SENTINEL {
            return None;
        }
        let maximum_start_backtrack = match candidate.max_before_root() {
            required_literals::MaximumConsumedDistance::Finite(distance) => Some(distance),
            required_literals::MaximumConsumedDistance::Unbounded => None,
        };
        Some(Self {
            root_state,
            cardinality,
            maximum_start_backtrack,
            scanner,
        })
    }

    /// Stable target-neutral cost order. Smaller necessary sets dominate;
    /// equal-cardinality sets prefer the lower-overhead scanner, then a finite
    /// and tighter start-backtrack proof, then the canonical state number and
    /// bitmap. No observed haystack or pattern identity participates.
    fn cost_key(&self) -> (u16, u8, u8, u32, u32, [u64; 4]) {
        let (tier, words) = match &self.scanner {
            NfaMandatoryCutScanner::Small { bytes, count } => {
                let mut words = [0_u64; 4];
                for &byte in &bytes[..usize::from(*count)] {
                    let index = usize::from(byte);
                    words[index / 64] |= 1_u64 << (index % 64);
                }
                (0, words)
            }
            NfaMandatoryCutScanner::Ascii { set, .. } => {
                let ascii = set.words();
                (1, [ascii[0], ascii[1], 0, 0])
            }
            NfaMandatoryCutScanner::Full { set, .. } => (2, set.words()),
        };
        let (unbounded, backtrack) = self
            .maximum_start_backtrack
            .map_or((1, u32::MAX), |backtrack| (0, backtrack));
        (
            self.cardinality,
            tier,
            unbounded,
            backtrack,
            self.root_state,
            words,
        )
    }

    fn first_member(&self, haystack: &[u8]) -> NfaMandatoryCutScan {
        match &self.scanner {
            NfaMandatoryCutScanner::Small { bytes, count: 1 } => memchr(bytes[0], haystack)
                .map_or(NfaMandatoryCutScan::Exhausted, NfaMandatoryCutScan::Member),
            NfaMandatoryCutScanner::Small { bytes, count: 2 } => {
                memchr2(bytes[0], bytes[1], haystack)
                    .map_or(NfaMandatoryCutScan::Exhausted, NfaMandatoryCutScan::Member)
            }
            NfaMandatoryCutScanner::Small { bytes, count: 3 } => {
                memchr3(bytes[0], bytes[1], bytes[2], haystack)
                    .map_or(NfaMandatoryCutScan::Exhausted, NfaMandatoryCutScan::Member)
            }
            // A malformed internal count must fail open to the ordered NFA.
            NfaMandatoryCutScanner::Small { .. } => NfaMandatoryCutScan::Fallback,
            NfaMandatoryCutScanner::Ascii { set, classifier } => {
                find_ascii_cut(*set, classifier, haystack)
                    .map_or(NfaMandatoryCutScan::Exhausted, NfaMandatoryCutScan::Member)
            }
            NfaMandatoryCutScanner::Full { set, classifier } => {
                find_full_cut(*set, classifier, haystack)
                    .map_or(NfaMandatoryCutScan::Exhausted, NfaMandatoryCutScan::Member)
            }
        }
    }

    #[cfg(test)]
    fn has_member(&self, haystack: &[u8]) -> bool {
        !matches!(self.first_member(haystack), NfaMandatoryCutScan::Exhausted)
    }
}

fn find_ascii_cut(
    set: AsciiByteSet,
    classifier: &AsciiByteSetClassifier,
    haystack: &[u8],
) -> Option<usize> {
    let prefix_end = haystack.len().min(NFA_MANDATORY_CUT_SCALAR_PREFIX_BYTES);
    if let Some(position) = haystack[..prefix_end]
        .iter()
        .copied()
        .position(|byte| set.contains(byte))
    {
        return Some(position);
    }
    let mut position = prefix_end;
    while haystack.len().saturating_sub(position) >= ASCII_WIDE_BYTES {
        let end = position
            .checked_add(ASCII_WIDE_BYTES)
            .expect("remaining source proves the wide ASCII cut extent");
        let block: &[u8; ASCII_WIDE_BYTES] = haystack[position..end]
            .try_into()
            .expect("checked ASCII cut block width");
        let mask = classifier.classify_32(block).member_mask();
        if mask != 0 {
            return position.checked_add(usize::try_from(mask.trailing_zeros()).ok()?);
        }
        position = end;
    }
    if haystack.len().saturating_sub(position) >= ASCII_NARROW_BYTES {
        let end = position
            .checked_add(ASCII_NARROW_BYTES)
            .expect("remaining source proves the narrow ASCII cut extent");
        let block: &[u8; ASCII_NARROW_BYTES] = haystack[position..end]
            .try_into()
            .expect("checked narrow ASCII cut block width");
        let mask = classifier.classify_16(block).member_mask();
        if mask != 0 {
            return position.checked_add(usize::try_from(mask.trailing_zeros()).ok()?);
        }
        position = end;
    }
    haystack[position..]
        .iter()
        .copied()
        .position(|byte| set.contains(byte))
        .and_then(|offset| position.checked_add(offset))
}

fn find_full_cut(
    set: ByteSet256,
    classifier: &ByteSetClassifier,
    haystack: &[u8],
) -> Option<usize> {
    let prefix_end = haystack.len().min(NFA_MANDATORY_CUT_SCALAR_PREFIX_BYTES);
    if let Some(position) = haystack[..prefix_end]
        .iter()
        .copied()
        .position(|byte| set.contains(byte))
    {
        return Some(position);
    }
    let mut position = prefix_end;
    while haystack.len().saturating_sub(position) >= BYTE_SET_WIDE_BLOCK_BYTES {
        let end = position
            .checked_add(BYTE_SET_WIDE_BLOCK_BYTES)
            .expect("remaining source proves the wide full-byte cut extent");
        let block: &[u8; BYTE_SET_WIDE_BLOCK_BYTES] = haystack[position..end]
            .try_into()
            .expect("checked full-byte cut block width");
        let mask = classifier.classify_32(block).member_mask();
        if mask != 0 {
            return position.checked_add(usize::try_from(mask.trailing_zeros()).ok()?);
        }
        position = end;
    }
    if haystack.len().saturating_sub(position) >= BYTE_SET_BLOCK_BYTES {
        let end = position
            .checked_add(BYTE_SET_BLOCK_BYTES)
            .expect("remaining source proves the narrow full-byte cut extent");
        let block: &[u8; BYTE_SET_BLOCK_BYTES] = haystack[position..end]
            .try_into()
            .expect("checked narrow full-byte cut block width");
        let mask = classifier.classify_16(block).member_mask();
        if mask != 0 {
            return position.checked_add(usize::try_from(mask.trailing_zeros()).ok()?);
        }
        position = end;
    }
    haystack[position..]
        .iter()
        .copied()
        .position(|byte| set.contains(byte))
        .and_then(|offset| position.checked_add(offset))
}

#[derive(Clone, Debug)]
#[allow(
    clippy::large_enum_variant,
    reason = "keeping the graph inline avoids an infallible allocation while constructing a program"
)]
enum ProgramEngine {
    OrderedNfa,
    OrderedDfa(OrderedDfa),
}

impl ProgramEngine {
    const fn is_ordered_nfa(&self) -> bool {
        matches!(self, Self::OrderedNfa)
    }

    const fn ordered_dfa(&self) -> Option<&OrderedDfa> {
        match self {
            Self::OrderedDfa(machine) => Some(machine),
            Self::OrderedNfa => None,
        }
    }

    const fn replay_order(&self) -> Option<DfaReplayOrder> {
        match self {
            Self::OrderedDfa(machine) => Some(machine.replay_order()),
            Self::OrderedNfa => None,
        }
    }
}

fn derive_nfa_suffix(
    raw: &RawPlan,
    prefix: &AnchoredPrefix,
    suffix: &AnchoredSuffix,
    maximum_width: MaxMatchWidthStats,
    engine: &ProgramEngine,
    enabled: bool,
) -> Option<NfaMandatorySuffix> {
    if !enabled
        || !engine.is_ordered_nfa()
        || raw
            .edge_kinds
            .iter()
            .any(|kind| !matches!(kind, EdgeKind::Epsilon | EdgeKind::ByteRange))
    {
        return None;
    }
    NfaMandatorySuffix::derive(
        raw,
        prefix,
        suffix,
        maximum_width.width,
        maximum_width.unbounded,
    )
}

fn derive_nfa_mandatory_cut(
    prefix: &AnchoredPrefix,
    required_literals: &RequiredLiterals,
    engine: &ProgramEngine,
    mandatory_suffix_present: bool,
    enabled: bool,
) -> Option<NfaMandatoryCut> {
    if !enabled || mandatory_suffix_present || !engine.is_ordered_nfa() {
        return None;
    }

    // K0 already scans its strongest graph-proved forward column. The
    // whole-window cut is admitted only when it is strictly more selective,
    // so positive/dense sources do not pay for a redundant pre-pass. A
    // mandatory suffix is an effective existing reverse filter and excludes
    // this sidecar above; an unmaterialized suffix is not treated as free.
    let best_forward_cardinality = prefix
        .sets()
        .iter()
        .copied()
        .map(AnchoredByteSet::cardinality)
        .min()
        .unwrap_or(256);

    required_literals
        .interior()
        .candidates()
        .iter()
        .filter_map(NfaMandatoryCut::from_candidate)
        .filter(|candidate| {
            candidate
                .cardinality
                .saturating_mul(NFA_MANDATORY_CUT_MIN_SELECTIVITY_GAIN)
                <= best_forward_cardinality
        })
        .min_by_key(NfaMandatoryCut::cost_key)
}

/// General capture-free AOT semantic program.
///
/// The validated automaton is deliberately retained for every route. In fast
/// mode and when complete determinization is declined, it is the executable
/// universal representation. In optimizing mode, no source-pattern identity
/// participates in selecting the DFA.
#[derive(Clone, Debug)]
pub struct CompiledProgram {
    raw: RawPlan,
    automaton: Automaton,
    identity: ProgramIdentity,
    line_terminator: u8,
    output: OutputContract,
    engine: ProgramEngine,
    engine_selection_reason: Option<EngineSelectionReason>,
    determinization_report: Option<DeterminizationReport>,
    /// Source-authenticated complete finite-language IR for future native
    /// lowering. Stable serialization deliberately omits this transient
    /// optimizing sidecar.
    native_finite_language: Option<Box<NativeFiniteLanguageProgram>>,
    /// Optional in-memory assertion optimizer. Stable serialization keeps
    /// the universal ordered-NFA engine and deliberately omits this sidecar.
    context_dfa: Option<ContextDfa>,
    /// Cold optimizing artifacts. Contextual provenance and assertion-free
    /// fallback artifacts cannot coexist; retained rows and their exact
    /// bit-parallel continuation share one boxed variant when both apply.
    /// Combining them keeps this field exactly the size and alignment of the
    /// former contextual provenance option, so ordinary `CompiledProgram`
    /// layout is unchanged.
    optimization_sidecar: ProgramOptimizationSidecar,
    anchored_prefix: AnchoredPrefix,
    anchored_suffix: AnchoredSuffix,
    required_literals: RequiredLiterals,
    exact_match_width: Option<usize>,
    max_match_width: MaxMatchWidthStats,
    nfa_mandatory_suffix: Option<NfaMandatorySuffix>,
    nfa_mandatory_cut: Option<NfaMandatoryCut>,
}

/// A fresh contextual attempt and assertion-free fallback artifacts are
/// mutually exclusive compiler outcomes. The large contextual report has
/// enough enum niches to retain their owner without growing `CompiledProgram`.
#[allow(
    clippy::large_enum_variant,
    reason = "the mutually exclusive sidecar preserves the baseline contextual-report layout"
)]
#[derive(Clone, Debug)]
enum ProgramOptimizationSidecar {
    None,
    /// Optimizing ordered-NFA fallback without a retained DFA payload.
    OptimizingFallback,
    Context(ContextDeterminizationReport),
    /// Retained rows paired with the replay identity authenticated by their
    /// enclosing stable program version.
    Partial(Box<ReplayPartialDfa>),
    /// Exact bounded assertion-free existence machine without retained rows.
    BitParallelExists(Box<BitParallelExists>),
    /// Ranked retained rows and their exact bit-parallel existence machine.
    PartialBitParallelExists(Box<PartialBitParallelExists>),
    /// Compile-time-only correlated-prefix receipt paired with the exact
    /// pre-existing optimizing sidecar. Boxing this composite preserves the
    /// historical `CompiledProgram` layout while making runtime view access a
    /// pointer read instead of a fresh allocating derivation.
    CorrelatedPrefix(Box<CorrelatedPrefixOptimizationSidecar>),
}

#[derive(Clone, Debug)]
struct CorrelatedPrefixOptimizationSidecar {
    requirement: NativeDynamicCorrelatedPrefixRequirement,
    inner: ProgramOptimizationSidecar,
}

#[derive(Clone, Debug)]
struct PartialBitParallelExists {
    partial: PartialDfa,
    bit_parallel: BitParallelExists,
    replay_order: DfaReplayOrder,
}

#[derive(Clone, Debug)]
struct ReplayPartialDfa {
    partial: PartialDfa,
    replay_order: DfaReplayOrder,
}

const _: () = assert!(
    core::mem::size_of::<ProgramOptimizationSidecar>()
        == core::mem::size_of::<Option<ContextDeterminizationReport>>()
);
const _: () = assert!(
    core::mem::align_of::<ProgramOptimizationSidecar>()
        == core::mem::align_of::<Option<ContextDeterminizationReport>>()
);

impl ProgramOptimizationSidecar {
    const fn context_report(&self) -> Option<&ContextDeterminizationReport> {
        match self {
            Self::Context(report) => Some(report),
            Self::None
            | Self::OptimizingFallback
            | Self::Partial(_)
            | Self::BitParallelExists(_)
            | Self::PartialBitParallelExists(_) => None,
            Self::CorrelatedPrefix(sidecar) => sidecar.inner.context_report(),
        }
    }

    const fn partial_dfa(&self) -> Option<&PartialDfa> {
        match self {
            Self::Partial(partial) => Some(&partial.partial),
            Self::PartialBitParallelExists(sidecars) => Some(&sidecars.partial),
            Self::None
            | Self::OptimizingFallback
            | Self::Context(_)
            | Self::BitParallelExists(_) => None,
            Self::CorrelatedPrefix(sidecar) => sidecar.inner.partial_dfa(),
        }
    }

    const fn has_partial_dfa(&self) -> bool {
        match self {
            Self::Partial(_) | Self::PartialBitParallelExists(_) => true,
            Self::CorrelatedPrefix(sidecar) => sidecar.inner.has_partial_dfa(),
            Self::None
            | Self::OptimizingFallback
            | Self::Context(_)
            | Self::BitParallelExists(_) => false,
        }
    }

    const fn is_optimizing_fallback_without_dfa(&self) -> bool {
        match self {
            Self::OptimizingFallback | Self::BitParallelExists(_) => true,
            Self::CorrelatedPrefix(sidecar) => {
                sidecar.inner.is_optimizing_fallback_without_dfa()
            }
            Self::None
            | Self::Context(_)
            | Self::Partial(_)
            | Self::PartialBitParallelExists(_) => false,
        }
    }

    const fn partial_replay_order(&self) -> Option<DfaReplayOrder> {
        match self {
            Self::Partial(partial) => Some(partial.replay_order),
            Self::PartialBitParallelExists(sidecars) => Some(sidecars.replay_order),
            Self::None
            | Self::OptimizingFallback
            | Self::Context(_)
            | Self::BitParallelExists(_) => None,
            Self::CorrelatedPrefix(sidecar) => sidecar.inner.partial_replay_order(),
        }
    }

    fn bit_parallel_exists(&self) -> Option<&BitParallelExists> {
        match self {
            Self::BitParallelExists(bit_parallel) => Some(bit_parallel),
            Self::PartialBitParallelExists(sidecars) => Some(&sidecars.bit_parallel),
            Self::None
            | Self::OptimizingFallback
            | Self::Context(_)
            | Self::Partial(_) => None,
            Self::CorrelatedPrefix(sidecar) => sidecar.inner.bit_parallel_exists(),
        }
    }

    const fn correlated_prefix_requirement(
        &self,
    ) -> Option<&NativeDynamicCorrelatedPrefixRequirement> {
        match self {
            Self::CorrelatedPrefix(sidecar) => Some(&sidecar.requirement),
            Self::None
            | Self::OptimizingFallback
            | Self::Context(_)
            | Self::Partial(_)
            | Self::BitParallelExists(_)
            | Self::PartialBitParallelExists(_) => None,
        }
    }

    fn with_correlated_prefix(
        self,
        requirement: NativeDynamicCorrelatedPrefixRequirement,
    ) -> Self {
        debug_assert!(!matches!(self, Self::CorrelatedPrefix(_)));
        Self::CorrelatedPrefix(Box::new(CorrelatedPrefixOptimizationSidecar {
            requirement,
            inner: self,
        }))
    }
}

fn partial_dfa_has_frontier(partial: &PartialDfa) -> bool {
    let (complete_rows, discovered_states) = partial.retained_dimensions();
    complete_rows < discovered_states
}

/// Reusable, allocation-free execution storage for one semantic program.
///
/// Construct this with [`CompiledProgram::prepare_workspace`] and pass it to
/// [`CompiledProgram::search_with_workspace`] or
/// [`CompiledProgram::search_optimized_with_workspace`]. A semantic identity
/// check prevents accidentally pairing storage with another program. An
/// exact serialized clone remains semantically compatible, but immutable
/// instance-bound cache hints conservatively fall back to the universal
/// executor instead of being reused across instances.
#[derive(Debug)]
pub struct ProgramWorkspace {
    identity: ProgramIdentity,
    nfa: Option<K0Workspace>,
    partial: Option<Box<PartialDfaWorkspace>>,
    static_prefix_resume: Option<Box<StaticPrefixResumeWorkspace>>,
    dynamic_native_rows: Option<Box<DynamicNativeRowsWorkspace>>,
    endpoint_oracle_backoff: EndpointOracleBackoff,
    endpoint_oracle_evidence: EndpointOracleEvidence,
}

/// Test-only evidence for whole-window endpoint-oracle route selection.
///
/// The production form is zero-sized. Keeping this separate from adaptive
/// backoff makes it possible to prove that an exact positive completion used
/// boundary tracking, while variable-width probes retained the boolean fast
/// path, without mutating positive-replay admission state.
#[derive(Debug, Default)]
struct EndpointOracleEvidence {
    #[cfg(test)]
    exact_whole_completions: usize,
    #[cfg(test)]
    boolean_whole_probes: usize,
}

impl EndpointOracleEvidence {
    #[inline(always)]
    fn observe_exact_whole_completion(&mut self) {
        #[cfg(test)]
        {
            self.exact_whole_completions = self.exact_whole_completions.saturating_add(1);
        }
    }

    #[inline(always)]
    fn observe_boolean_whole_probe(&mut self) {
        #[cfg(test)]
        {
            self.boolean_whole_probes = self.boolean_whole_probes.saturating_add(1);
        }
    }
}

/// Per-workspace admission state for the whole-window endpoint oracle.
///
/// A negative existence result is a complete endpoint result. A variable-width
/// positive must replay the ordered executor, so repeated such positives
/// receive the same periodic exponential backoff used by other speculative
/// fallback entries. An exact-width first-end completion never mutates this
/// state. The state belongs to the compiler-owned program workspace rather
/// than general K0 storage and is never consulted by `Exists` or retained-hole
/// continuations.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct EndpointOracleBackoff {
    positive_probe_streak: u8,
    bypass_remaining: u16,
}

impl EndpointOracleBackoff {
    const fn should_probe(self) -> bool {
        self.bypass_remaining == 0
    }

    fn observe_negative(&mut self) {
        self.positive_probe_streak = 0;
        self.bypass_remaining = 0;
    }

    fn observe_positive_replay(&mut self) {
        self.positive_probe_streak = self.positive_probe_streak.saturating_add(1);
        if self.positive_probe_streak < 2 {
            return;
        }
        let shift = u32::from(self.positive_probe_streak.saturating_sub(2))
            .saturating_add(4)
            .min(10);
        self.bypass_remaining = 1_u16 << shift;
    }

    fn observe_bypassed_result(&mut self, found: &MatchResult) {
        if match_result_has_match(found) {
            self.bypass_remaining = self.bypass_remaining.saturating_sub(1);
        } else {
            self.observe_negative();
        }
    }
}

const fn match_result_has_match(found: &MatchResult) -> bool {
    match found {
        MatchResult::Exists(found) => *found,
        MatchResult::SelectedEnd(found) => found.is_some(),
        MatchResult::Span(found) => found.is_some(),
    }
}

/// Opaque proof that one prepared program/workspace pair published every
/// reachable retained-partial fallback row transactionally.
///
/// This is retained only by the permanently owned exclusive runtime session.
/// The process-local program lineage prevents a receipt from crossing semantic
/// owners; K0 independently reauthenticates its exact cache generation,
/// direct-row shape, resume set, and selected resume hint on every use.
#[doc(hidden)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct FullyPrefilledFallbackReceipt {
    program_instance: u64,
    k0: K0FullyPrefilledResumeCacheReceipt,
}

/// Program-lineage binding for a complete root-only K0 cache transaction.
///
/// Unlike [`FullyPrefilledFallbackReceipt`], this proof carries no retained
/// continuation-set authority. Immutable dynamic-row owners retain it only
/// for reverse recovery after their separately copied forward table selected
/// an exact endpoint.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct FullyPrefilledRootFallbackReceipt {
    program_instance: u64,
    k0: K0FullyPrefilledResumeCacheReceipt,
    reverse: Option<FrozenRootReverseProjection>,
}

/// Exact live reverse-K0 geometry authenticated by a root-prefill receipt.
///
/// Compact forward rows are copied into a separately owned representation,
/// but variable-width Span recovery intentionally retains the original K0
/// reverse table. Keeping its complete geometry inside the opaque receipt
/// lets header publication reauthenticate the same workspace generation
/// immediately before exposing any address to generated code.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct FrozenRootReverseProjection {
    rows_address: usize,
    live_cells: usize,
    row_stride: u32,
    initial_row: u32,
    cache_identity: u64,
}

impl FrozenRootReverseProjection {
    fn from_projection(projection: &K0FullyPrefilledRootProjection<'_>) -> Option<Self> {
        Some(Self {
            rows_address: projection.reverse_rows_address()?.expose_provenance(),
            live_cells: projection.reverse_live_cells(),
            row_stride: projection.row_stride(),
            initial_row: projection.reverse_initial_row()?,
            cache_identity: projection.cache_identity(),
        })
    }

    fn is_valid(self) -> bool {
        let Ok(stride) = usize::try_from(self.row_stride) else {
            return false;
        };
        let Ok(initial) = usize::try_from(self.initial_row) else {
            return false;
        };
        self.rows_address != 0
            && self.rows_address.checked_rem(core::mem::align_of::<u32>()) == Some(0)
            && self.cache_identity != 0
            && stride != 0
            && stride <= 256
            && self.live_cells >= stride
            && self.live_cells
                <= usize::try_from(DYNAMIC_NATIVE_ROWS_V1_NEXT_ROW_TOKEN_MASK)
                    .unwrap_or(usize::MAX)
            && self.live_cells.checked_rem(stride) == Some(0)
            && self.initial_row != FROZEN_PREPARED_HEADER_V1_NO_REVERSE_ROW
            && initial.checked_rem(stride) == Some(0)
            && initial
                .checked_add(stride)
                .is_some_and(|end| end <= self.live_cells)
    }
}

/// Versioned, target-native header for one setup-authenticated frozen K0 root.
///
/// Prepared exclusive runtimes place this record at byte offset zero of their
/// opaque allocation. The active seal is published only after the complete
/// forward projection has been authenticated and copied into its immutable
/// owner. Any legacy or fallback runtime entry clears that seal before it may
/// mutate capability-owned state. Ordinary publication cannot restore it; a
/// prepared runtime may rearm an unchanged maximum-envelope shell only while
/// retaining its matching setup-minted owner-generation key and immutable
/// owner. A
/// variable-Span compact postflight may retain the seal while it reads the
/// separately authenticated live reverse projection; a recovery fallback may
/// mutate only disjoint K0 scratch. Both leave every header, sidecar, pointer,
/// and publication field untouched. The inline class map deliberately follows
/// every hot authentication and row-layout field.
#[doc(hidden)]
#[derive(Debug, Eq, PartialEq)]
#[repr(C)]
pub struct FrozenPreparedHeaderV1 {
    active_seal: u64,
    magic: u64,
    abi_version: u32,
    flags: u32,
    header_bytes: usize,
    artifact_identity: [u8; 32],
    forward_rows_address: usize,
    reverse_rows_address: usize,
    forward_live_cells: usize,
    reverse_live_cells: usize,
    cache_identity: u64,
    row_stride: u32,
    forward_initial_row: u32,
    reverse_initial_row: u32,
    unfilled_cell: u32,
    accept_mask: u32,
    next_row_token_mask: u32,
    class_map: [u8; 256],
}

/// Additive prepared-header storage for one immutable compact dynamic table.
///
/// The complete V1 record remains the offset-zero prefix. Existing retained-
/// partial entries therefore keep their exact ABI, while a new entry follows
/// the tail only after authenticating the additive flag and complete extent.
#[doc(hidden)]
#[derive(Debug, Eq, PartialEq)]
#[repr(C)]
pub struct FrozenPreparedHeaderV2 {
    v1: FrozenPreparedHeaderV1,
    dynamic_rows_v1: DynamicNativeRowsV1,
}

/// Additive prepared-header storage for one immutable compact table.
///
/// The complete V1 record remains the offset-zero prefix. Its distinct flag
/// and exact extent select this tail before any overlapping V2 field is read;
/// an older V2 entry therefore rejects the record and uses its authenticated
/// preflight path. The tail ready seal is published only after every mirror
/// in the V1 prefix has been initialized. After that publication all geometry,
/// mirrors, the inline class map, and the owned rows are immutable for the
/// prepared allocation's lifetime. Revocation clears the active seal before
/// clearing the ready seal. A standalone V3 value remains revoked; when this
/// prefix is retained inside a maximum prepared envelope, only the matching
/// setup-minted owner-generation key may rearm its unchanged shell.
#[doc(hidden)]
#[derive(Debug, Eq, PartialEq)]
#[repr(C)]
pub struct FrozenPreparedHeaderV3 {
    v1: FrozenPreparedHeaderV1,
    dynamic_rows_v3: FrozenDynamicRowsV3,
}

/// Additive prepared-header storage for one unary Exists summary.
///
/// V5 is a distinct capability rather than an interpretation of spare V3/V4
/// fields. Its V1 prefix remains at offset zero, while the exact V5 flag and
/// extent authenticate the larger tail before any V5-only field is read.
/// Older native entries reject the unknown flag and retain their ordinary
/// preflight/fallback route.
#[doc(hidden)]
#[derive(Debug, Eq, PartialEq)]
#[repr(C)]
pub struct FrozenPreparedHeaderV5 {
    v1: FrozenPreparedHeaderV1,
    dynamic_rows_v5: FrozenDynamicRowsV5,
}

/// Maximum prepared-header envelope for every immutable compact generation.
///
/// The complete V3 record remains an offset-zero prefix.
/// V3/V4/V8/V9/V10/V11/V12/V13 use only that 448-byte logical extent, V5 uses
/// the first two extension words through byte 456, and V6/V7 authenticate the
/// complete 664-byte envelope
/// before reading loop ownership. The V5 summary words intentionally overlay
/// the V6/V7 loop-count and reserved words; exact flags, extents, versions,
/// and seals make the interpretations mutually exclusive.
#[doc(hidden)]
#[derive(Debug, Eq, PartialEq)]
#[repr(C)]
pub struct FrozenPreparedHeaderV6 {
    v1: FrozenPreparedHeaderV1,
    dynamic_rows_v6: FrozenDynamicRowsV6,
}

/// Opaque authorization for one reverse-only variable-Span recovery after an
/// active immutable V3--V14 forward table selected the endpoint.
///
/// Only [`FrozenPreparedHeaderV6`] can mint this value, after matching the
/// active header, exact artifact/program lineage, and the pointer-stable
/// immutable sidecar owner. Legacy V1/V2 headers and mutable-row preflight
/// transactions cannot construct it.
#[doc(hidden)]
#[derive(Debug)]
pub struct FrozenDynamicRowsSpanCapability<'a> {
    header: &'a FrozenPreparedHeaderV6,
    owner: &'a FrozenDynamicRowsStorageV3,
    program_instance: u64,
    artifact_identity: [u8; 32],
}

/// Immutable compact-row descriptor stored in the additive compact tail.
///
/// Format V3 rows contain mapped, padded power-of-two arrays whose low 15 bits
/// hold a one-based destination-state ordinal. V4 rows are mapped and hold the
/// one-based destination cell-row offset directly. V8 and V9 retain those two
/// token encodings respectively but expand semantic columns into raw-byte
/// order. V10 stores those raw columns as `u8`, while V12 stores the exact
/// mapped projection in padded `u8` rows. In both byte-cell formats bit 7 is
/// acceptance and the low 7 bits hold a one-based destination-state ordinal.
/// V11 stores mapped two-transition `u32` cells followed by one odd-tail
/// acceptance bitmap per state block; V13 stores the exact dense C^2 pair
/// space and bitmap in `u16` cells. V14 stores exact C^4 plus short-tail
/// spaces and uses the same one-based block-cell-offset convention as V13.
/// Every format retains physical row or block zero as the canonical initial
/// state. Exact V1 flags, versions, seals, and geometry distinguish the
/// interpretations before generated code follows the rows pointer.
#[doc(hidden)]
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
#[repr(C)]
pub struct FrozenDynamicRowsV3 {
    ready_seal: u64,
    rows_address: usize,
    cache_identity: u64,
    state_count: u32,
    class_count: u32,
    row_shift: u32,
    initial_state: u32,
    learned_loop_state_count: u32,
    learned_loop_states: [u32; 4],
    format_version: u32,
}

/// Immutable unary-Exists descriptor stored in the additive V5 tail.
///
/// The compact geometry is repeated explicitly instead of borrowing the V4
/// type. `first_accept_step` is one based: `k` means that the kth consumed
/// byte takes the first accepting edge from canonical state zero. Zero is the
/// exact never-accept sentinel. Its complemented mirror makes every value,
/// including zero, independently authenticated before native use.
#[doc(hidden)]
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
#[repr(C)]
pub struct FrozenDynamicRowsV5 {
    ready_seal: u64,
    rows_address: usize,
    cache_identity: u64,
    state_count: u32,
    class_count: u32,
    row_shift: u32,
    initial_state: u32,
    learned_loop_state_count: u32,
    learned_loop_states: [u32; 4],
    format_version: u32,
    first_accept_step: u32,
    first_accept_step_complement: u32,
}

/// One authenticated immutable compact-loop scanner descriptor.
#[doc(hidden)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[repr(C)]
pub struct FrozenCompactLoopPlanV1 {
    canonical_state: u32,
    start_action: u32,
    members: [u64; 4],
    scanner_address: usize,
}

impl FrozenCompactLoopPlanV1 {
    const INACTIVE: Self = Self {
        canonical_state: u32::MAX,
        start_action: u32::MAX,
        members: [0; 4],
        scanner_address: 0,
    };
}

/// Common compact descriptor plus the largest generation-specific extension.
///
/// `loop_plan_count` and `reserved` occupy tail offsets 64 and 68. Under the
/// exact V5 format those same words are `first_accept_step` and its complement.
#[doc(hidden)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[repr(C)]
pub struct FrozenDynamicRowsV6 {
    compact: FrozenDynamicRowsV3,
    loop_plan_count: u32,
    reserved: u32,
    loop_index_address: usize,
    loop_index_length: usize,
    loop_plans: [FrozenCompactLoopPlanV1; 4],
}

/// Immutable independently compacted reverse supertransition descriptor.
///
/// Reverse input is consumed from high addresses toward low addresses. V13
/// therefore keys each pair as `(high_class, low_class)`, while V14 uses the
/// analogous four-class order. `source_rows_address` retains the exact K0
/// reverse projection used by the established scalar fallback; compact rows
/// and their independently coalesced byte map never replace that recovery
/// authority.
#[doc(hidden)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[repr(C)]
pub(crate) struct FrozenReverseSupertransitionV1 {
    ready_seal: u64,
    magic: u64,
    abi_version: u32,
    abi_version_complement: u32,
    descriptor_bytes: usize,
    artifact_identity: [u8; 32],
    rows_address: usize,
    source_rows_address: usize,
    cache_identity: u64,
    compact_live_cells: usize,
    source_live_cells: usize,
    state_count: u32,
    class_count: u32,
    block_cells: u32,
    initial_block: u32,
    source_initial_row: u32,
    source_row_stride: u32,
    format_version: u32,
    reserved: u32,
    class_map: [u8; 256],
}

/// Pointer-stable ownership for one optional reverse V13/V14 generation.
///
/// The descriptor is boxed separately because the surrounding forward owner
/// may move before publication. Generated code can therefore retain its
/// address for the lifetime of the immutable prepared owner.
#[derive(Debug)]
struct FrozenReverseSupertransitionStorageV1 {
    rows: Box<[u16]>,
    descriptor: Box<FrozenReverseSupertransitionV1>,
    resident_bytes: usize,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct FrozenReverseSupertransitionGenerationKey {
    descriptor_address: usize,
    ready_seal: u64,
    magic: u64,
    abi_version: u32,
    abi_version_complement: u32,
    descriptor_bytes: usize,
    artifact_identity: [u8; 32],
    rows_address: usize,
    source_rows_address: usize,
    cache_identity: u64,
    compact_live_cells: usize,
    source_live_cells: usize,
    state_count: u32,
    class_count: u32,
    block_cells: u32,
    initial_block: u32,
    source_initial_row: u32,
    source_row_stride: u32,
    format_version: u32,
    reserved: u32,
}

impl Default for FrozenDynamicRowsV6 {
    fn default() -> Self {
        Self {
            compact: FrozenDynamicRowsV3::default(),
            loop_plan_count: 0,
            reserved: 0,
            loop_index_address: 0,
            loop_index_length: 0,
            loop_plans: [FrozenCompactLoopPlanV1::INACTIVE; 4],
        }
    }
}

/// Pointer-stable host-selected scanner for one frozen compact loop.
///
/// The strategy is derived solely from the exact loop-member set. Universal
/// loops need no classifier, ASCII-only loops retain the operation-specific
/// whole-slice run scanner, and loops containing every high byte plus a small
/// ASCII exit set retain the corresponding nonmember-run scanner. Remaining
/// full-byte sets retain the exact complementary exit set in the general
/// 256-byte classifier. Finding the first exit-set member lets that classifier
/// select its whole-slice AVX2, SSSE3, SVE2, NEON, or scalar leaf once per loop
/// scan. Keeping the mutually exclusive payloads in an enum avoids retaining a
/// second copy of the member set beside any classifier. The compact-sidecar
/// budget charges the exact enum size.
#[doc(hidden)]
#[derive(Clone, Copy, Debug)]
pub struct FrozenCompactLoopScanner {
    strategy: FrozenCompactLoopScannerStrategy,
}

#[derive(Clone, Copy, Debug)]
enum FrozenCompactLoopScannerStrategy {
    All,
    Ascii(AsciiByteSetRunScanner),
    AsciiExits(AsciiByteSetNonMemberScanner),
    ExitSet(ByteSetClassifier),
}

impl FrozenCompactLoopScanner {
    fn new(members: [u64; 4]) -> Self {
        let strategy = if members == [u64::MAX; 4] {
            FrozenCompactLoopScannerStrategy::All
        } else if members[2] == u64::MAX && members[3] == u64::MAX {
            let exits = AsciiByteSet::from_words([!members[0], !members[1]]);
            let exit_words = exits.words();
            if exit_words[0].count_ones() + exit_words[1].count_ones() <= 16 {
                FrozenCompactLoopScannerStrategy::AsciiExits(
                    SimdDispatchContext::capture()
                        .ascii_byte_set_nonmember_scanner(exits, DispatchPolicy::Auto)
                        .expect(
                            "automatic ASCII nonmember dispatch always retains a scalar fallback",
                        ),
                )
            } else {
                FrozenCompactLoopScannerStrategy::ExitSet(ByteSetClassifier::new(
                    ByteSet256::from_words(members.map(|word| !word)),
                ))
            }
        } else if members[2] == 0 && members[3] == 0 {
            let set = AsciiByteSet::from_words([members[0], members[1]]);
            let scanner = SimdDispatchContext::capture()
                .ascii_byte_set_run_scanner_prefer_small_complement(
                    set,
                    DispatchPolicy::Auto,
                )
                .expect("automatic ASCII run dispatch always retains a scalar fallback");
            FrozenCompactLoopScannerStrategy::Ascii(scanner)
        } else {
            FrozenCompactLoopScannerStrategy::ExitSet(ByteSetClassifier::new(
                ByteSet256::from_words(members.map(|word| !word)),
            ))
        };
        Self { strategy }
    }

    fn words(&self) -> [u64; 4] {
        match &self.strategy {
            FrozenCompactLoopScannerStrategy::All => [u64::MAX; 4],
            FrozenCompactLoopScannerStrategy::Ascii(scanner) => {
                let words = scanner.set().words();
                [words[0], words[1], 0, 0]
            }
            FrozenCompactLoopScannerStrategy::AsciiExits(scanner) => {
                let exits = scanner.set().words();
                [!exits[0], !exits[1], u64::MAX, u64::MAX]
            }
            FrozenCompactLoopScannerStrategy::ExitSet(classifier) => {
                classifier.set().words().map(|word| !word)
            }
        }
    }

    /// Return the exact member-prefix length, never exceeding `source.len()`.
    #[doc(hidden)]
    #[must_use]
    #[inline]
    pub fn scan_prefix(&self, source: &[u8]) -> usize {
        match &self.strategy {
            FrozenCompactLoopScannerStrategy::All => return source.len(),
            FrozenCompactLoopScannerStrategy::Ascii(scanner) => {
                return scanner.scan_forward(source).member_run_len();
            }
            FrozenCompactLoopScannerStrategy::AsciiExits(scanner) => {
                return scanner.scan_forward(source).nonmember_run_len();
            }
            FrozenCompactLoopScannerStrategy::ExitSet(classifier) => classifier
                .find_first_member(source)
                .unwrap_or(source.len()),
        }
    }
}

/// Pointer-stable immutable ownership for a compact frozen dynamic table.
///
/// The descriptor addresses exactly one of the boxed payloads, whose
/// allocation remains fixed when this owner or its containing prepared
/// runtime moves. The owner is never exposed through a matching API and is
/// retained for the complete prepared-runtime lifetime whenever construction
/// succeeds.
#[doc(hidden)]
#[derive(Debug)]
pub struct FrozenDynamicRowsStorage {
    program_instance: u64,
    artifact_identity: [u8; 32],
    rows: Box<[u32]>,
    class_map: Box<[u8; 256]>,
    descriptor: DynamicNativeRowsV1,
}

/// Pointer-stable immutable ownership for a compact
/// V3/V4/V6/V7/V8/V9/V10/V11/V12/V13/V14 table.
///
/// V10 and V12 own a separately allocated byte table, while V11 owns `u32`
/// pair blocks and V13/V14 own dense `u16` supertransition blocks. No
/// generation reinterprets an allocation at a wider or differently aligned
/// type, and exactly one row owner is populated for any published generation.
/// For variable-width Span programs this owner contains only the closed
/// forward projection. Reverse postflight reads the prepared runtime's
/// independently allocated, fully prefilled reverse K0 projection; fallback
/// recovery may mutate only its disjoint scratch. Neither can alias or mutate
/// the copied forward rows or their publication fields.
#[doc(hidden)]
#[derive(Debug)]
pub struct FrozenDynamicRowsStorageV3 {
    program_instance: u64,
    artifact_identity: [u8; 32],
    root_prefill_receipt: FullyPrefilledRootFallbackReceipt,
    rows: Box<[u16]>,
    rows_u8: Option<Box<[u8]>>,
    pair_rows_v11: Option<Box<[u32]>>,
    pair_rows_v13: Option<Box<[u16]>>,
    quad_rows_v14: Option<Box<[u16]>>,
    class_map: [u8; 256],
    descriptor: FrozenDynamicRowsV3,
    unary_exists_first_accept_step: Option<u32>,
    loop_index: Box<[u8]>,
    loop_scanners: Box<[FrozenCompactLoopScanner]>,
    descriptor_v6: Option<FrozenDynamicRowsV6>,
    reverse_supertransition: Option<FrozenReverseSupertransitionStorageV1>,
}

const FROZEN_RETAINED_PARTIAL_RESUME_PENDING_MASK: u32 = 1_u32 << 31;
const FROZEN_RETAINED_PARTIAL_RESUME_STATE_MASK: u32 =
    !FROZEN_RETAINED_PARTIAL_RESUME_PENDING_MASK;

/// Setup-owned projection from every retained-hole ordinal to the immutable
/// compact owner's canonical state and pending mode.
///
/// The high bit of each entry carries the pending mode; the remaining bits
/// carry a canonical state ordinal. Construction copies only a completely
/// authenticated K0 resume map. Per-match projection can therefore remain a
/// single bounds-checked immutable load without reading K0 or its resume set.
#[derive(Debug)]
struct FrozenRetainedPartialResumeMapV1 {
    entries: Box<[u32]>,
    cache_identity: u64,
    state_count: u32,
    format_version: u32,
}

impl FrozenRetainedPartialResumeMapV1 {
    #[inline]
    fn project(
        &self,
        rows: &FrozenDynamicRowsStorageV3,
        expected_count: usize,
        resume_state: usize,
        expected_pending: bool,
    ) -> Option<usize> {
        if self.cache_identity == 0
            || self.cache_identity != rows.descriptor.cache_identity
            || self.state_count == 0
            || self.state_count != rows.descriptor.state_count
            || self.format_version != rows.effective_format_version()
            || self.entries.len() != expected_count
        {
            return None;
        }
        let packed = *self.entries.get(resume_state)?;
        let pending = packed & FROZEN_RETAINED_PARTIAL_RESUME_PENDING_MASK != 0;
        let canonical_state = packed & FROZEN_RETAINED_PARTIAL_RESUME_STATE_MASK;
        if pending != expected_pending || canonical_state >= self.state_count {
            return None;
        }
        usize::try_from(canonical_state).ok()
    }
}

/// Independently owned compact table that may be entered only from an already
/// authenticated arbitrary-state continuation.
///
/// The private newtype prevents callers outside this module from accidentally
/// supplying a root-scanner-independent compact owner to the ordinary public
/// prepared-header publisher. Compiler-private continuation projection and
/// publication APIs unwrap it only after authenticating the exact resume
/// ticket for which the owner was built. Root-only V5 summaries remain
/// excluded. V6/V7 may be retained because their nonroot loop index is an
/// optional exact accelerator over the same closed V3/V4 rows; the generated
/// local tail authenticates the current canonical state before consulting it.
/// Every closed format may additionally own a bounded dense retained-hole map
/// copied from the same fully authenticated K0 transaction. Its absence never
/// removes the established compact-v2 continuation.
#[doc(hidden)]
#[derive(Debug)]
pub struct FrozenStaticContinuationRowsStorageV1 {
    rows: FrozenDynamicRowsStorageV3,
    retained_partial_resume: Option<FrozenRetainedPartialResumeMapV1>,
}

/// Setup-minted authority for one immutable compact-owner generation.
///
/// The fields are intentionally private. A prepared runtime may retain and
/// present this value, but only this module can mint it after the full owner
/// and header authentication pass. Hot continuation publication compares its
/// fixed-size generation snapshot instead of revalidating the owned row table.
#[doc(hidden)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct FrozenPreparedHeaderOwnerGenerationKey {
    program_instance: u64,
    artifact_identity: [u8; 32],
    root_prefill_receipt: FullyPrefilledRootFallbackReceipt,
    owner_compact: FrozenDynamicRowsV3,
    published_compact: FrozenDynamicRowsV3,
    forward_live_cells: usize,
    header_flag: u32,
    header_bytes: usize,
    header_row_stride: u32,
    header_unfilled_cell: u32,
    header_accept_mask: u32,
    header_next_row_token_mask: u32,
    ready_seal: u64,
    loop_plan_count: u32,
    loop_reserved: u32,
    loop_index_address: usize,
    loop_index_length: usize,
    reverse: Option<FrozenRootReverseProjection>,
    reverse_supertransition: Option<FrozenReverseSupertransitionGenerationKey>,
}

/// Single-use result of validating an inactive cached continuation shell.
///
/// Minting precedes the linear ownership transfer. Once that final fallible
/// operation succeeds, committing this value is infallible and consists only
/// of the two ordered publication stores. Private owner fields and shell
/// geometry have no safe mutation API; retained borrows additionally prevent
/// replacing the exact immutable owner or its key between validation and
/// commit.
#[doc(hidden)]
#[derive(Debug)]
pub struct FrozenPreparedHeaderRearm<'header, 'owner, 'key> {
    header: &'header mut FrozenPreparedHeaderV6,
    _owner: &'owner FrozenDynamicRowsStorageV3,
    _key: &'key FrozenPreparedHeaderOwnerGenerationKey,
    active_seal: u64,
    ready_seal: u64,
}

impl FrozenPreparedHeaderRearm<'_, '_, '_> {
    /// Commit the already validated publication after linear ownership moved.
    /// The retained mutable borrow binds this authority to the exact shell,
    /// making cross-header activation impossible through the safe API.
    #[doc(hidden)]
    pub fn compiler_private_commit(self) {
        self.header.v1.active_seal = self.active_seal;
        self.header.dynamic_rows_v6.compact.ready_seal = self.ready_seal;
    }
}

impl FrozenStaticContinuationRowsStorageV1 {
    /// Return the exact compact generation owned by this continuation sidecar.
    #[doc(hidden)]
    #[must_use]
    pub const fn compiler_private_format_version(&self) -> u32 {
        self.rows.effective_format_version()
    }
}

#[inline]
const fn frozen_prepared_header_base_flags(flags: u32) -> u32 {
    flags & !FROZEN_PREPARED_HEADER_V1_FLAG_REVERSE_SUPERTRANSITION
}

#[inline]
const fn frozen_prepared_header_has_reverse_supertransition(flags: u32) -> bool {
    flags & FROZEN_PREPARED_HEADER_V1_FLAG_REVERSE_SUPERTRANSITION != 0
}

#[inline]
const fn frozen_prepared_header_publication_shape(
    format_version: u32,
) -> Option<(u32, usize, u64)> {
    match format_version {
        FROZEN_DYNAMIC_ROWS_V3_FORMAT_VERSION => Some((
            FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V3,
            FROZEN_PREPARED_HEADER_V3_BYTES,
            FROZEN_PREPARED_HEADER_V3_READY_SEAL,
        )),
        FROZEN_DYNAMIC_ROWS_V4_FORMAT_VERSION => Some((
            FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V4,
            FROZEN_PREPARED_HEADER_V4_BYTES,
            FROZEN_PREPARED_HEADER_V4_READY_SEAL,
        )),
        FROZEN_DYNAMIC_ROWS_V5_FORMAT_VERSION => Some((
            FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V5,
            FROZEN_PREPARED_HEADER_V5_BYTES,
            FROZEN_PREPARED_HEADER_V5_READY_SEAL,
        )),
        FROZEN_DYNAMIC_ROWS_V6_FORMAT_VERSION => Some((
            FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V6,
            FROZEN_PREPARED_HEADER_V6_BYTES,
            FROZEN_PREPARED_HEADER_V6_READY_SEAL,
        )),
        FROZEN_DYNAMIC_ROWS_V7_FORMAT_VERSION => Some((
            FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V7,
            FROZEN_PREPARED_HEADER_V7_BYTES,
            FROZEN_PREPARED_HEADER_V7_READY_SEAL,
        )),
        FROZEN_DYNAMIC_ROWS_V8_FORMAT_VERSION => Some((
            FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V8,
            FROZEN_PREPARED_HEADER_V8_BYTES,
            FROZEN_PREPARED_HEADER_V8_READY_SEAL,
        )),
        FROZEN_DYNAMIC_ROWS_V9_FORMAT_VERSION => Some((
            FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V9,
            FROZEN_PREPARED_HEADER_V9_BYTES,
            FROZEN_PREPARED_HEADER_V9_READY_SEAL,
        )),
        FROZEN_DYNAMIC_ROWS_V10_FORMAT_VERSION => Some((
            FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V10,
            FROZEN_PREPARED_HEADER_V10_BYTES,
            FROZEN_PREPARED_HEADER_V10_READY_SEAL,
        )),
        FROZEN_DYNAMIC_ROWS_V11_FORMAT_VERSION => Some((
            FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V11,
            FROZEN_PREPARED_HEADER_V11_BYTES,
            FROZEN_PREPARED_HEADER_V11_READY_SEAL,
        )),
        FROZEN_DYNAMIC_ROWS_V12_FORMAT_VERSION => Some((
            FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V12,
            FROZEN_PREPARED_HEADER_V12_BYTES,
            FROZEN_PREPARED_HEADER_V12_READY_SEAL,
        )),
        FROZEN_DYNAMIC_ROWS_V13_FORMAT_VERSION => Some((
            FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V13,
            FROZEN_PREPARED_HEADER_V13_BYTES,
            FROZEN_PREPARED_HEADER_V13_READY_SEAL,
        )),
        FROZEN_DYNAMIC_ROWS_V14_FORMAT_VERSION => Some((
            FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V14,
            FROZEN_PREPARED_HEADER_V14_BYTES,
            FROZEN_PREPARED_HEADER_V14_READY_SEAL,
        )),
        _ => None,
    }
}

#[inline]
const fn frozen_static_continuation_format_is_supported(format_version: u32) -> bool {
    matches!(
        format_version,
        FROZEN_DYNAMIC_ROWS_V3_FORMAT_VERSION
            | FROZEN_DYNAMIC_ROWS_V4_FORMAT_VERSION
            | FROZEN_DYNAMIC_ROWS_V6_FORMAT_VERSION
            | FROZEN_DYNAMIC_ROWS_V7_FORMAT_VERSION
            | FROZEN_DYNAMIC_ROWS_V8_FORMAT_VERSION
            | FROZEN_DYNAMIC_ROWS_V9_FORMAT_VERSION
            | FROZEN_DYNAMIC_ROWS_V10_FORMAT_VERSION
            | FROZEN_DYNAMIC_ROWS_V11_FORMAT_VERSION
            | FROZEN_DYNAMIC_ROWS_V12_FORMAT_VERSION
            | FROZEN_DYNAMIC_ROWS_V13_FORMAT_VERSION
            | FROZEN_DYNAMIC_ROWS_V14_FORMAT_VERSION
    )
}

/// Every closed arbitrary-state continuation format can own a retained-row
/// hole without changing its generated ABI. Root-only V5 is deliberately
/// absent from [`frozen_static_continuation_format_is_supported`]: its unary
/// summary is valid only from canonical state zero, whereas this handoff may
/// enter any authenticated canonical state.
#[inline]
const fn frozen_static_continuation_format_supports_retained_partial_handoff(
    format_version: u32,
) -> bool {
    frozen_static_continuation_format_is_supported(format_version)
}

#[inline]
const fn frozen_retained_partial_handoff_block_bytes(format_version: u32) -> Option<usize> {
    match format_version {
        FROZEN_DYNAMIC_ROWS_V11_FORMAT_VERSION | FROZEN_DYNAMIC_ROWS_V13_FORMAT_VERSION => {
            Some(2)
        }
        FROZEN_DYNAMIC_ROWS_V14_FORMAT_VERSION => Some(4),
        FROZEN_DYNAMIC_ROWS_V3_FORMAT_VERSION
        | FROZEN_DYNAMIC_ROWS_V4_FORMAT_VERSION
        | FROZEN_DYNAMIC_ROWS_V6_FORMAT_VERSION
        | FROZEN_DYNAMIC_ROWS_V7_FORMAT_VERSION
        | FROZEN_DYNAMIC_ROWS_V8_FORMAT_VERSION
        | FROZEN_DYNAMIC_ROWS_V9_FORMAT_VERSION
        | FROZEN_DYNAMIC_ROWS_V10_FORMAT_VERSION
        | FROZEN_DYNAMIC_ROWS_V12_FORMAT_VERSION => Some(1),
        _ => None,
    }
}

/// Whether a retained immutable tail can complete this output without
/// synthesizing authority absent from the native continuation ABI.
#[inline]
const fn retained_partial_native_continuation_output_is_supported(
    output: OutputContract,
    exact_match_width: Option<usize>,
    initial_pending: bool,
) -> bool {
    match output {
        OutputContract::Exists | OutputContract::SelectedEnd => true,
        OutputContract::Span => match exact_match_width {
            Some(0) => false,
            Some(_) => true,
            None => !initial_pending,
        },
    }
}

/// Version-and-address identity of one immutable compiler-owned resume
/// descriptor.
///
/// The address is part of the capability, rather than merely a place from
/// which to read equivalent bytes. Reusing an address for a different wire
/// version therefore always requires a cold binding transaction.
#[doc(hidden)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct StaticPrefixResumeDescriptorKey {
    version: u32,
    address: usize,
}

impl StaticPrefixResumeDescriptorKey {
    /// Construct a checked compiler-private descriptor identity.
    #[doc(hidden)]
    pub fn new(version: u32, address: usize) -> Result<Self, CompileError> {
        if address == 0
            || !matches!(
                version,
                STATIC_PREFIX_RESUME_DESCRIPTOR_V1_VERSION
                    | STATIC_PREFIX_RESUME_DESCRIPTOR_V2_VERSION
            )
        {
            return Err(CompileError::InternalInvariant(
                "static-prefix descriptor key rejected its address or version",
            ));
        }
        Ok(Self { version, address })
    }

    /// Wire version bound into this descriptor identity.
    #[doc(hidden)]
    #[must_use]
    pub const fn version(self) -> u32 {
        self.version
    }

    /// Immutable compiler-owned descriptor address.
    #[doc(hidden)]
    #[must_use]
    pub const fn address(self) -> usize {
        self.address
    }
}

/// Cold half of one authenticated static-prefix object.
///
/// Private fields make this capability unforgeable outside this module, and
/// deliberately omitting `Clone`/`Copy` makes the subsequent graph binding a
/// linear operation.
#[doc(hidden)]
#[derive(Debug)]
pub struct ColdStaticPrefixResumeObject {
    program_instance: u64,
    workspace_address: usize,
    artifact_identity: [u8; 32],
    haystack_address: usize,
    haystack_len: usize,
    window: SearchWindow,
    descriptor: StaticPrefixResumeDescriptorKey,
}

impl ColdStaticPrefixResumeObject {
    /// Descriptor key authenticated by the one warm/cold classification.
    #[doc(hidden)]
    #[must_use]
    pub const fn descriptor_key(&self) -> StaticPrefixResumeDescriptorKey {
        self.descriptor
    }
}

/// Single-use authority to continue one exact static-prefix invocation.
///
/// The token owns haystack, window, artifact, workspace, descriptor, and
/// sidecar-generation identity. A compact projection describes where to
/// resume, but only this non-`Copy` admission authorizes executing it.
#[doc(hidden)]
#[derive(Debug)]
pub struct StaticPrefixResumeAdmission {
    program_instance: u64,
    workspace_address: usize,
    artifact_identity: [u8; 32],
    haystack_address: usize,
    haystack_len: usize,
    window: SearchWindow,
    descriptor: StaticPrefixResumeDescriptorKey,
    admission_epoch: u64,
}

/// Result of the invocation's sole descriptor-binding classification.
///
/// `Warm` has already performed the one rearm/admit operation. `Cold` owns
/// the authority required to read, decode, prefill, and publish the descriptor
/// after its fixed header and bounded extent have been checked by the runtime.
#[doc(hidden)]
#[derive(Debug)]
pub enum StaticPrefixResumeAdmissionPlan {
    Warm(StaticPrefixResumeAdmission),
    Cold(ColdStaticPrefixResumeObject),
}

/// Single-use reverse-only authority minted by a successful variable-Span
/// native continuation handoff.
#[doc(hidden)]
#[derive(Debug)]
pub struct StaticPrefixSpanRecoveryAdmission(StaticPrefixResumeAdmission);

/// Result of trying the in-process immutable continuation before portable K0.
#[doc(hidden)]
#[derive(Debug)]
pub enum StaticPrefixResumeSearchOutcome {
    Complete(MatchResult),
    Declined(StaticPrefixResumeAdmission),
}

/// Authenticated input to one immutable compact-row continuation.
///
/// The projection is deliberately independent of any compact generation's
