/// Maximum retained K0 workspace admitted to one prepared immutable-row setup.
///
/// A complete setup transaction temporarily constructs one same-layout K0
/// workspace before atomically publishing its rows. The assertion-free wide
/// tier uses a little over 2 MiB for a full-byte forward cache and can retain
/// both directions for variable-width spans. Eight MiB admits that general
/// tier while continuing to decline unusually large graph workspaces before
/// the second allocation. The live workspace already belongs to the prepared
/// regex regardless of whether this optional setup succeeds.
#[doc(hidden)]
pub const FROZEN_DYNAMIC_SIDECAR_MAX_K0_BYTES: usize = 8 * 1024 * 1024;
/// Maximum resident size of one immutable compact-row owner.
///
/// This independent cap prevents the wider setup workspace from increasing
/// persistent compact-sidecar storage.
#[doc(hidden)]
pub const FROZEN_DYNAMIC_SIDECAR_MAX_PACKED_BYTES: usize = 512 * 1024;
const _: () = assert!(
    FROZEN_DYNAMIC_SIDECAR_MAX_PACKED_BYTES < FROZEN_DYNAMIC_SIDECAR_MAX_K0_BYTES
);
/// Smallest semantic alphabet admitted to pair-supertransition V11.
pub(crate) const FROZEN_PAIR_ROWS_V11_MIN_CLASSES: usize = 2;
/// Largest semantic alphabet admitted to the initial V11 slice.
pub(crate) const FROZEN_PAIR_ROWS_V11_MAX_CLASSES: usize = 4;
/// Independent resident allocation ceiling for the initial V11 slice.
pub(crate) const FROZEN_PAIR_ROWS_V11_MAX_BYTES: usize = 64 * 1024;
/// Smallest semantic alphabet admitted to dense pair-supertransition V13.
pub(crate) const FROZEN_PAIR_ROWS_V13_MIN_CLASSES: usize = 2;
/// Largest semantic alphabet admitted to dense pair-supertransition V13.
pub(crate) const FROZEN_PAIR_ROWS_V13_MAX_CLASSES: usize = 8;
/// Independent resident allocation ceiling for V13, including its byte map.
pub(crate) const FROZEN_PAIR_ROWS_V13_MAX_BYTES: usize = 64 * 1024;
/// Smallest semantic alphabet admitted to four-transition V14.
pub(crate) const FROZEN_QUAD_ROWS_V14_MIN_CLASSES: usize = 2;
/// Largest semantic alphabet admitted to four-transition V14.
pub(crate) const FROZEN_QUAD_ROWS_V14_MAX_CLASSES: usize = 4;
/// Independent resident allocation ceiling for V14, including its byte map.
pub(crate) const FROZEN_QUAD_ROWS_V14_MAX_BYTES: usize = 64 * 1024;
/// Closed dead transition in a mapped compact-u8 V12 row.
#[doc(hidden)]
pub const DYNAMIC_NATIVE_ROWS_V12_DEAD_CELL: u8 = DYNAMIC_NATIVE_ROWS_V10_DEAD_CELL;
/// Accepting-transition bit in a mapped compact-u8 V12 row.
#[doc(hidden)]
pub const DYNAMIC_NATIVE_ROWS_V12_ACCEPT_MASK: u8 = DYNAMIC_NATIVE_ROWS_V10_ACCEPT_MASK;
/// One-based destination-state field in a mapped compact-u8 V12 row.
#[doc(hidden)]
pub const DYNAMIC_NATIVE_ROWS_V12_NEXT_STATE_TOKEN_MASK: u8 =
    DYNAMIC_NATIVE_ROWS_V10_NEXT_STATE_TOKEN_MASK;
/// Smallest exact semantic alphabet expanded into raw-byte order.
///
/// Above 128 classes V3 already owns 256 physical cells per row, so V8 is a
/// zero-growth rewrite. V9 is separately constrained by its complete expanded
/// live-cell and byte budgets.
pub(crate) const FROZEN_COMPACT_DIRECT_BYTE_MIN_CLASSES: usize = 129;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum FrozenCompactRowsFormat {
    StateOrdinalV3,
    CellOffsetV4,
    StateOrdinalDirectV8,
    CellOffsetDirectV9,
    StateOrdinalDirectU8V10,
    PairSupertransitionV11,
    StateOrdinalMappedU8V12,
    DensePairSupertransitionV13,
    DenseQuadSupertransitionV14,
}

#[derive(Clone, Copy)]
struct FrozenCompactLoopCandidate {
    canonical_state: usize,
    start_action: u32,
    members: [u64; 4],
}

/// Sum the stable source-independent frequency model over loop exits.
fn frozen_compact_loop_exit_frequency_units(members: [u64; 4]) -> u16 {
    let mut exit_frequency_units = 0_u16;
    for byte in u8::MIN..=u8::MAX {
        let word = usize::from(byte >> 6);
        let bit = u32::from(byte & 63);
        if members[word] & (1_u64 << bit) != 0 {
            continue;
        }
        exit_frequency_units = exit_frequency_units
            .saturating_add(estimated_byte_frequency_units(byte))
            .min(BYTE_FREQUENCY_DENOMINATOR);
    }
    exit_frequency_units
}

/// Admit an out-of-line frozen loop scanner only when the stable byte model
/// predicts that one invocation reaches the existing useful-run floor.
///
/// The portable K0 scanner treats a member run shorter than
/// [`ASCII_WIDE_BYTES`] as negative evidence and backs off before trying that
/// state again. Frozen V6/V7 cannot retain invocation-local backoff state, and
/// every non-universal attempt crosses the Rust ABI after spilling its native
/// DFA cursor. Requiring the expected leading member run to cover one wide
/// block prevents that fixed call cost from shadowing the scanner-free compact
/// formats. For exit probability
/// `q = exit_units / BYTE_FREQUENCY_DENOMINATOR`, that run is geometrically
/// distributed with expectation `(1 - q) / q`. The equivalent inequality is
/// written without division so the zero-exit universal loop remains naturally
/// admissible:
///
/// `exit_units * (ASCII_WIDE_BYTES + 1) <= BYTE_FREQUENCY_DENOMINATOR`.
fn frozen_compact_loop_has_expected_wide_run(members: [u64; 4]) -> bool {
    let exit_frequency_units = frozen_compact_loop_exit_frequency_units(members);
    u32::from(exit_frequency_units)
        .saturating_mul(
            u32::try_from(
                ASCII_WIDE_BYTES
                    .checked_add(1)
                    .expect("the fixed byte-set vector width plus its exit fits usize"),
            )
            .expect("the fixed byte-set vector width plus its exit fits u32"),
        )
        <= u32::from(BYTE_FREQUENCY_DENOMINATOR)
}

impl FrozenCompactRowsFormat {
    const fn format_version(self) -> u32 {
        match self {
            Self::StateOrdinalV3 => FROZEN_DYNAMIC_ROWS_V3_FORMAT_VERSION,
            Self::CellOffsetV4 => FROZEN_DYNAMIC_ROWS_V4_FORMAT_VERSION,
            Self::StateOrdinalDirectV8 => FROZEN_DYNAMIC_ROWS_V8_FORMAT_VERSION,
            Self::CellOffsetDirectV9 => FROZEN_DYNAMIC_ROWS_V9_FORMAT_VERSION,
            Self::StateOrdinalDirectU8V10 => FROZEN_DYNAMIC_ROWS_V10_FORMAT_VERSION,
            Self::PairSupertransitionV11 => FROZEN_DYNAMIC_ROWS_V11_FORMAT_VERSION,
            Self::StateOrdinalMappedU8V12 => FROZEN_DYNAMIC_ROWS_V12_FORMAT_VERSION,
            Self::DensePairSupertransitionV13 => FROZEN_DYNAMIC_ROWS_V13_FORMAT_VERSION,
            Self::DenseQuadSupertransitionV14 => FROZEN_DYNAMIC_ROWS_V14_FORMAT_VERSION,
        }
    }

    const fn ready_seal(self) -> u64 {
        match self {
            Self::StateOrdinalV3 => FROZEN_PREPARED_HEADER_V3_READY_SEAL,
            Self::CellOffsetV4 => FROZEN_PREPARED_HEADER_V4_READY_SEAL,
            Self::StateOrdinalDirectV8 => FROZEN_PREPARED_HEADER_V8_READY_SEAL,
            Self::CellOffsetDirectV9 => FROZEN_PREPARED_HEADER_V9_READY_SEAL,
            Self::StateOrdinalDirectU8V10 => FROZEN_PREPARED_HEADER_V10_READY_SEAL,
            Self::PairSupertransitionV11 => FROZEN_PREPARED_HEADER_V11_READY_SEAL,
            Self::StateOrdinalMappedU8V12 => FROZEN_PREPARED_HEADER_V12_READY_SEAL,
            Self::DensePairSupertransitionV13 => FROZEN_PREPARED_HEADER_V13_READY_SEAL,
            Self::DenseQuadSupertransitionV14 => FROZEN_PREPARED_HEADER_V14_READY_SEAL,
        }
    }

    const fn header_flag(self) -> u32 {
        match self {
            Self::StateOrdinalV3 => FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V3,
            Self::CellOffsetV4 => FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V4,
            Self::StateOrdinalDirectV8 => FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V8,
            Self::CellOffsetDirectV9 => FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V9,
            Self::StateOrdinalDirectU8V10 => {
                FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V10
            }
            Self::PairSupertransitionV11 => {
                FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V11
            }
            Self::StateOrdinalMappedU8V12 => {
                FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V12
            }
            Self::DensePairSupertransitionV13 => {
                FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V13
            }
            Self::DenseQuadSupertransitionV14 => {
                FROZEN_PREPARED_HEADER_V1_FLAG_DYNAMIC_ROWS_V14
            }
        }
    }

    const fn is_state_ordinal(self) -> bool {
        matches!(
            self,
            Self::StateOrdinalV3
                | Self::StateOrdinalDirectV8
                | Self::StateOrdinalDirectU8V10
                | Self::StateOrdinalMappedU8V12
        )
    }

    const fn is_direct_byte(self) -> bool {
        matches!(
            self,
            Self::StateOrdinalDirectV8
                | Self::CellOffsetDirectV9
                | Self::StateOrdinalDirectU8V10
        )
    }

    const fn is_u8(self) -> bool {
        matches!(
            self,
            Self::StateOrdinalDirectU8V10 | Self::StateOrdinalMappedU8V12
        )
    }

    const fn is_pair_supertransition(self) -> bool {
        matches!(
            self,
            Self::PairSupertransitionV11 | Self::DensePairSupertransitionV13
        )
    }

    const fn is_dense_pair_supertransition(self) -> bool {
        matches!(self, Self::DensePairSupertransitionV13)
    }

    const fn is_quad_supertransition(self) -> bool {
        matches!(self, Self::DenseQuadSupertransitionV14)
    }

}

fn select_frozen_compact_rows_format(
    state_count: usize,
    class_count: usize,
) -> Option<FrozenCompactRowsFormat> {
    let live_cells = state_count.checked_mul(class_count)?;
    if state_count == 0 || class_count == 0 || class_count > 256 {
        return None;
    }
    if live_cells <= usize::from(DYNAMIC_NATIVE_ROWS_V3_NEXT_STATE_TOKEN_MASK) {
        Some(FrozenCompactRowsFormat::CellOffsetV4)
    } else if state_count <= usize::from(DYNAMIC_NATIVE_ROWS_V3_NEXT_STATE_TOKEN_MASK) {
        Some(FrozenCompactRowsFormat::StateOrdinalV3)
    } else {
        None
    }
}

/// Return `(physical_classes, pair_cells, block_words, total_words, bytes)`
/// for one bounded V11 table. The byte count includes the inline 256-byte map,
/// matching the resource accounting used by the older compact formats.
fn frozen_pair_rows_v11_geometry(
    state_count: usize,
    class_count: usize,
) -> Option<(usize, usize, usize, usize, usize)> {
    if state_count == 0
        || !(FROZEN_PAIR_ROWS_V11_MIN_CLASSES..=FROZEN_PAIR_ROWS_V11_MAX_CLASSES)
            .contains(&class_count)
    {
        return None;
    }
    let physical_classes = class_count.checked_next_power_of_two()?;
    let pair_cells = physical_classes.checked_mul(physical_classes)?;
    let block_words = pair_cells.checked_add(1)?;
    let total_words = state_count.checked_mul(block_words)?;
    if total_words > usize::try_from(DYNAMIC_NATIVE_ROWS_V11_NEXT_BLOCK_TOKEN_MASK).ok()? {
        return None;
    }
    let bytes = total_words
        .checked_mul(core::mem::size_of::<u32>())?
        .checked_add(256)?;
    Some((
        physical_classes,
        pair_cells,
        block_words,
        total_words,
        bytes,
    ))
}

/// Compose one pair cell from the canonical one-symbol semantics shared by V3
/// and V4. A dead first transition deliberately ignores `second`: although the
/// generated loop may safely fetch the second input byte, the DFA consumes
/// only the first byte and never observes a successor transition.
fn frozen_pair_cell_v11(first: u16, second: Option<u16>, block_words: usize) -> Option<u32> {
    if block_words == 0 {
        return None;
    }
    let first_accepts = first & DYNAMIC_NATIVE_ROWS_V3_ACCEPT_MASK != 0;
    let first_token = first & DYNAMIC_NATIVE_ROWS_V3_NEXT_STATE_TOKEN_MASK;
    if first_token == 0 {
        return Some(
            (if first_accepts {
                DYNAMIC_NATIVE_ROWS_V11_ANY_ACCEPT_MASK
            } else {
                0
            }) | DYNAMIC_NATIVE_ROWS_V11_FIRST_DEAD_MASK,
        );
    }

    let second = second?;
    let second_accepts = second & DYNAMIC_NATIVE_ROWS_V3_ACCEPT_MASK != 0;
    let second_token = second & DYNAMIC_NATIVE_ROWS_V3_NEXT_STATE_TOKEN_MASK;
    let mut pair = if first_accepts || second_accepts {
        DYNAMIC_NATIVE_ROWS_V11_ANY_ACCEPT_MASK
    } else {
        0
    };
    if first_accepts && !second_accepts {
        pair |= DYNAMIC_NATIVE_ROWS_V11_ACCEPT_BACK_ONE_MASK;
    }
    if second_token != 0 {
        let destination = usize::from(second_token).checked_sub(1)?;
        let token = destination.checked_mul(block_words)?.checked_add(1)?;
        let token = u32::try_from(token).ok()?;
        if token > DYNAMIC_NATIVE_ROWS_V11_NEXT_BLOCK_TOKEN_MASK {
            return None;
        }
        pair |= token;
    }
    Some(pair)
}

fn build_frozen_pair_rows_v11(
    source_rows: &[u32],
    columns: &FrozenCompactColumnProjection,
    source_class_count: usize,
    state_count: usize,
    source_initial_state: usize,
) -> Option<Box<[u32]>> {
    let class_count = columns.class_count;
    let (physical_classes, _, block_words, total_words, _) =
        frozen_pair_rows_v11_geometry(state_count, class_count)?;

    let semantic_cells = state_count.checked_mul(class_count)?;
    let mut semantics = Vec::new();
    semantics.try_reserve_exact(semantic_cells).ok()?;
    for canonical_state in 0..state_count {
        let source_state =
            canonicalize_frozen_state_ordinal(canonical_state, source_initial_state);
        let source_row = source_state.checked_mul(source_class_count)?;
        for &source_class in &columns.source_classes[..class_count] {
            let cell = *source_rows.get(source_row.checked_add(usize::from(source_class))?)?;
            semantics.push(frozen_compact_semantic_cell(
                cell,
                source_class_count,
                state_count,
                source_initial_state,
            )?);
        }
    }
    if semantics.len() != semantic_cells {
        return None;
    }

    let mut pair_rows = Vec::new();
    pair_rows.try_reserve_exact(total_words).ok()?;
    for state in 0..state_count {
        let semantic_row = state.checked_mul(class_count)?;
        for first_class in 0..physical_classes {
            for second_class in 0..physical_classes {
                if first_class >= class_count || second_class >= class_count {
                    pair_rows.push(0);
                    continue;
                }
                let first = *semantics.get(semantic_row.checked_add(first_class)?)?;
                let first_token = first & DYNAMIC_NATIVE_ROWS_V3_NEXT_STATE_TOKEN_MASK;
                let second = if first_token == 0 {
                    None
                } else {
                    let first_destination = usize::from(first_token).checked_sub(1)?;
                    let destination_row = first_destination.checked_mul(class_count)?;
                    Some(*semantics.get(destination_row.checked_add(second_class)?)?)
                };
                pair_rows.push(frozen_pair_cell_v11(first, second, block_words)?);
            }
        }
        let mut tail_accepts = 0_u32;
        for class in 0..class_count {
            let cell = *semantics.get(semantic_row.checked_add(class)?)?;
            if cell & DYNAMIC_NATIVE_ROWS_V3_ACCEPT_MASK != 0 {
                tail_accepts |= 1_u32.checked_shl(u32::try_from(class).ok()?)?;
            }
        }
        pair_rows.push(tail_accepts);
    }
    (pair_rows.len() == total_words).then(|| pair_rows.into_boxed_slice())
}

/// Return `(pair_cells, block_cells, total_cells, bytes)` for one exact dense
/// V13 table. Unlike V11, the pair key is `first_class * C + second_class`, so
/// non-power-of-two semantic alphabets do not allocate unreachable padding.
/// The byte count includes the inline class map just as every compact format's
/// setup accounting does.
fn frozen_pair_rows_v13_geometry(
    state_count: usize,
    class_count: usize,
) -> Option<(usize, usize, usize, usize)> {
    frozen_pair_rows_v13_geometry_with_minimum_classes(
        state_count,
        class_count,
        FROZEN_PAIR_ROWS_V13_MIN_CLASSES,
    )
}

/// Reverse recovery also benefits from the degenerate one-class V13 orbit.
/// Forward V13 dispatch remains restricted to C=2..=8 because its ordinary
/// owner arbitration has separate unary formats. The reverse owner needs V13
/// as the smaller exact fallback when a unary V14 table exceeds its authority.
fn frozen_reverse_pair_rows_v13_geometry(
    state_count: usize,
    class_count: usize,
) -> Option<(usize, usize, usize, usize)> {
    frozen_pair_rows_v13_geometry_with_minimum_classes(state_count, class_count, 1)
}

fn frozen_pair_rows_v13_geometry_with_minimum_classes(
    state_count: usize,
    class_count: usize,
    minimum_classes: usize,
) -> Option<(usize, usize, usize, usize)> {
    if state_count == 0
        || !(minimum_classes..=FROZEN_PAIR_ROWS_V13_MAX_CLASSES).contains(&class_count)
    {
        return None;
    }
    let pair_cells = class_count.checked_mul(class_count)?;
    let block_cells = pair_cells.checked_add(1)?;
    let total_cells = state_count.checked_mul(block_cells)?;
    let last_block_token = state_count
        .checked_sub(1)?
        .checked_mul(block_cells)?
        .checked_add(1)?;
    if last_block_token > usize::from(DYNAMIC_NATIVE_ROWS_V13_NEXT_BLOCK_TOKEN_MASK) {
        return None;
    }
    let bytes = total_cells
        .checked_mul(core::mem::size_of::<u16>())?
        .checked_add(256)?;
    (bytes <= FROZEN_PAIR_ROWS_V13_MAX_BYTES)
        .then_some((pair_cells, block_cells, total_cells, bytes))
}

/// Compose one dense V13 pair from the same canonical single-transition
/// semantics used by V3/V4/V11. A dead first edge makes the second byte
/// semantically unobservable. V13 therefore encodes a zero destination and,
/// when that edge accepts, the back-one endpoint bit; consuming the already
/// bounds-checked second byte cannot change the terminal result.
fn frozen_pair_cell_v13(first: u16, second: Option<u16>, block_cells: usize) -> Option<u16> {
    if block_cells == 0 {
        return None;
    }
    let first_accepts = first & DYNAMIC_NATIVE_ROWS_V3_ACCEPT_MASK != 0;
    let first_token = first & DYNAMIC_NATIVE_ROWS_V3_NEXT_STATE_TOKEN_MASK;
    if first_token == 0 {
        return Some(if first_accepts {
            DYNAMIC_NATIVE_ROWS_V13_ANY_ACCEPT_MASK
                | DYNAMIC_NATIVE_ROWS_V13_ACCEPT_BACK_ONE_MASK
        } else {
            0
        });
    }

    let second = second?;
    let second_accepts = second & DYNAMIC_NATIVE_ROWS_V3_ACCEPT_MASK != 0;
    let second_token = second & DYNAMIC_NATIVE_ROWS_V3_NEXT_STATE_TOKEN_MASK;
    let mut pair = if first_accepts || second_accepts {
        DYNAMIC_NATIVE_ROWS_V13_ANY_ACCEPT_MASK
    } else {
        0
    };
    if first_accepts && !second_accepts {
        pair |= DYNAMIC_NATIVE_ROWS_V13_ACCEPT_BACK_ONE_MASK;
    }
    if second_token != 0 {
        let destination = usize::from(second_token).checked_sub(1)?;
        let token = destination.checked_mul(block_cells)?.checked_add(1)?;
        let token = u16::try_from(token).ok()?;
        if token > DYNAMIC_NATIVE_ROWS_V13_NEXT_BLOCK_TOKEN_MASK {
            return None;
        }
        pair |= token;
    }
    Some(pair)
}

fn build_frozen_pair_rows_v13(
    source_rows: &[u32],
    columns: &FrozenCompactColumnProjection,
    source_class_count: usize,
    state_count: usize,
    source_initial_state: usize,
) -> Option<Box<[u16]>> {
    let class_count = columns.class_count;
    let (_, block_cells, total_cells, _) =
        frozen_pair_rows_v13_geometry(state_count, class_count)?;
    build_frozen_pair_rows_v13_with_geometry(
        source_rows,
        columns,
        source_class_count,
        state_count,
        source_initial_state,
        block_cells,
        total_cells,
    )
}

#[allow(
    clippy::too_many_arguments,
    reason = "the shared builder receives the already authenticated forward or reverse geometry"
)]
fn build_frozen_pair_rows_v13_with_geometry(
    source_rows: &[u32],
    columns: &FrozenCompactColumnProjection,
    source_class_count: usize,
    state_count: usize,
    source_initial_state: usize,
    block_cells: usize,
    total_cells: usize,
) -> Option<Box<[u16]>> {
    let class_count = columns.class_count;
    let semantic_cells = state_count.checked_mul(class_count)?;
    let mut semantics = Vec::new();
    semantics.try_reserve_exact(semantic_cells).ok()?;
    for canonical_state in 0..state_count {
        let source_state =
            canonicalize_frozen_state_ordinal(canonical_state, source_initial_state);
        let source_row = source_state.checked_mul(source_class_count)?;
        for &source_class in &columns.source_classes[..class_count] {
            let cell = *source_rows.get(source_row.checked_add(usize::from(source_class))?)?;
            semantics.push(frozen_compact_semantic_cell(
                cell,
                source_class_count,
                state_count,
                source_initial_state,
            )?);
        }
    }
    if semantics.len() != semantic_cells {
        return None;
    }

    let mut pair_rows = Vec::new();
    pair_rows.try_reserve_exact(total_cells).ok()?;
    for state in 0..state_count {
        let semantic_row = state.checked_mul(class_count)?;
        for first_class in 0..class_count {
            let first = *semantics.get(semantic_row.checked_add(first_class)?)?;
            let first_token = first & DYNAMIC_NATIVE_ROWS_V3_NEXT_STATE_TOKEN_MASK;
            for second_class in 0..class_count {
                let second = if first_token == 0 {
                    None
                } else {
                    let first_destination = usize::from(first_token).checked_sub(1)?;
                    let destination_row = first_destination.checked_mul(class_count)?;
                    Some(*semantics.get(destination_row.checked_add(second_class)?)?)
                };
                pair_rows.push(frozen_pair_cell_v13(first, second, block_cells)?);
            }
        }
        let mut tail_accepts = 0_u16;
        for class in 0..class_count {
            let cell = *semantics.get(semantic_row.checked_add(class)?)?;
            if cell & DYNAMIC_NATIVE_ROWS_V3_ACCEPT_MASK != 0 {
                tail_accepts |= 1_u16.checked_shl(u32::try_from(class).ok()?)?;
            }
        }
        pair_rows.push(tail_accepts);
    }
    if pair_rows.len() != total_cells {
        return None;
    }
    Some(pair_rows.into_boxed_slice())
}

/// Return `(quad, tail3, tail2, tail1, block, total, bytes)` for V14.
///
/// V14 deliberately uses exact, unpadded base-C rows and cell-offset
/// destinations. Padding these blocks to powers of two would inflate their
/// exact sizes by 6.67%, 6.67%, and 50.59% for C=2,3,4 respectively, reducing
/// coverage under the resident cap. Each nonzero token points directly at an
/// aligned destination-block start, so target-native loops need no row-size
/// multiply on their serial four-byte backedge.
fn frozen_quad_rows_v14_geometry(
    state_count: usize,
    class_count: usize,
) -> Option<(usize, usize, usize, usize, usize, usize, usize)> {
    frozen_quad_rows_v14_geometry_with_minimum_classes(
        state_count,
        class_count,
        FROZEN_QUAD_ROWS_V14_MIN_CLASSES,
    )
}

/// Reverse recovery also benefits from the degenerate one-class V14 orbit.
/// Forward V14 dispatch deliberately remains restricted to C=2..=4 because
/// its target loops are statically specialized for those three radices.
fn frozen_reverse_quad_rows_v14_geometry(
    state_count: usize,
    class_count: usize,
) -> Option<(usize, usize, usize, usize, usize, usize, usize)> {
    frozen_quad_rows_v14_geometry_with_minimum_classes(state_count, class_count, 1)
}

fn frozen_quad_rows_v14_geometry_with_minimum_classes(
    state_count: usize,
    class_count: usize,
    minimum_classes: usize,
) -> Option<(usize, usize, usize, usize, usize, usize, usize)> {
    if state_count == 0
        || !(minimum_classes..=FROZEN_QUAD_ROWS_V14_MAX_CLASSES).contains(&class_count)
    {
        return None;
    }
    let tail1_cells = class_count;
    let tail2_cells = class_count.checked_pow(2)?;
    let tail3_cells = class_count.checked_pow(3)?;
    let quad_cells = class_count.checked_pow(4)?;
    let block_cells = quad_cells
        .checked_add(tail3_cells)?
        .checked_add(tail2_cells)?
        .checked_add(tail1_cells)?;
    let total_cells = state_count.checked_mul(block_cells)?;
    let last_block_token = state_count
        .checked_sub(1)?
        .checked_mul(block_cells)?
        .checked_add(1)?;
    if last_block_token > usize::from(DYNAMIC_NATIVE_ROWS_V14_NEXT_BLOCK_TOKEN_MASK) {
        return None;
    }
    let bytes = total_cells
        .checked_mul(core::mem::size_of::<u16>())?
        .checked_add(256)?;
    (bytes <= FROZEN_QUAD_ROWS_V14_MAX_BYTES).then_some((
        quad_cells,
        tail3_cells,
        tail2_cells,
        tail1_cells,
        block_cells,
        total_cells,
        bytes,
    ))
}

fn frozen_quad_classes_v14(
    mut key: usize,
    length: usize,
    class_count: usize,
) -> Option<[usize; 4]> {
    if length == 0 || length > 4 || class_count == 0 {
        return None;
    }
    let mut classes = [0_usize; 4];
    for index in (0..length).rev() {
        classes[index] = key.checked_rem(class_count)?;
        key = key.checked_div(class_count)?;
    }
    (key == 0).then_some(classes)
}

/// Summarize one one-to-four-byte trace. Semantic traversal stops at the first
/// dead edge even though generated code may load the remainder after proving
/// the full input bound. Distance is measured from the final loaded byte, so a
/// byte-one acceptance in a four-byte cell has distance three. Tail summaries
/// use the same field relative to their actual final byte and carry no token.
fn frozen_quad_cell_v14(
    semantics: &[u16],
    state: usize,
    classes: &[usize],
    class_count: usize,
    block_cells: usize,
    include_destination: bool,
) -> Option<u16> {
    if block_cells == 0
        || classes.is_empty()
        || classes.len() > 4
        || state.checked_mul(class_count)? >= semantics.len()
    {
        return None;
    }
    let mut state = state;
    let mut last_accept = None;
    let mut live_after_all = true;
    for (index, &class) in classes.iter().enumerate() {
        if class >= class_count {
            return None;
        }
        let cell = *semantics.get(state.checked_mul(class_count)?.checked_add(class)?)?;
        if cell & DYNAMIC_NATIVE_ROWS_V3_ACCEPT_MASK != 0 {
            last_accept = Some(index);
        }
        let token = cell & DYNAMIC_NATIVE_ROWS_V3_NEXT_STATE_TOKEN_MASK;
        if token == 0 {
            live_after_all = false;
            break;
        }
        state = usize::from(token).checked_sub(1)?;
        if state.checked_mul(class_count)? >= semantics.len() {
            return None;
        }
    }

    let mut summary = 0_u16;
    if let Some(last_accept) = last_accept {
        let distance = classes.len().checked_sub(1)?.checked_sub(last_accept)?;
        let distance = u16::try_from(distance).ok()?;
        summary |= DYNAMIC_NATIVE_ROWS_V14_ANY_ACCEPT_MASK | (distance << 13);
    }
    if include_destination && live_after_all {
        let token = state.checked_mul(block_cells)?.checked_add(1)?;
        let token = u16::try_from(token).ok()?;
        if token > DYNAMIC_NATIVE_ROWS_V14_NEXT_BLOCK_TOKEN_MASK {
            return None;
        }
        summary |= token;
    }
    Some(summary)
}

fn build_frozen_quad_rows_v14(
    source_rows: &[u32],
    columns: &FrozenCompactColumnProjection,
    source_class_count: usize,
    state_count: usize,
    source_initial_state: usize,
) -> Option<Box<[u16]>> {
    let class_count = columns.class_count;
    let (_, _, _, _, block_cells, total_cells, _) =
        frozen_quad_rows_v14_geometry(state_count, class_count)?;
    build_frozen_quad_rows_v14_with_geometry(
        source_rows,
        columns,
        source_class_count,
        state_count,
        source_initial_state,
        block_cells,
        total_cells,
    )
}

#[allow(
    clippy::too_many_arguments,
    reason = "the shared builder receives the already authenticated forward or reverse geometry"
)]
fn build_frozen_quad_rows_v14_with_geometry(
    source_rows: &[u32],
    columns: &FrozenCompactColumnProjection,
    source_class_count: usize,
    state_count: usize,
    source_initial_state: usize,
    block_cells: usize,
    total_cells: usize,
) -> Option<Box<[u16]>> {
    let class_count = columns.class_count;
    let semantic_cells = state_count.checked_mul(class_count)?;
    let mut semantics = Vec::new();
    semantics.try_reserve_exact(semantic_cells).ok()?;
    for canonical_state in 0..state_count {
        let source_state =
            canonicalize_frozen_state_ordinal(canonical_state, source_initial_state);
        let source_row = source_state.checked_mul(source_class_count)?;
        for &source_class in &columns.source_classes[..class_count] {
            let cell = *source_rows.get(source_row.checked_add(usize::from(source_class))?)?;
            semantics.push(frozen_compact_semantic_cell(
                cell,
                source_class_count,
                state_count,
                source_initial_state,
            )?);
        }
    }
    if semantics.len() != semantic_cells {
        return None;
    }

    let mut rows = Vec::new();
    rows.try_reserve_exact(total_cells).ok()?;
    for state in 0..state_count {
        for length in [4_usize, 3, 2, 1] {
            let key_count = class_count.checked_pow(u32::try_from(length).ok()?)?;
            for key in 0..key_count {
                let classes = frozen_quad_classes_v14(key, length, class_count)?;
                rows.push(frozen_quad_cell_v14(
                    &semantics,
                    state,
                    &classes[..length],
                    class_count,
                    block_cells,
                    length == 4,
                )?);
            }
        }
        if rows.len().checked_rem(block_cells) != Some(0) {
            return None;
        }
    }
    if rows.len() != total_cells {
        return None;
    }
    Some(rows.into_boxed_slice())
}

fn build_frozen_reverse_supertransition_v1(
    source_rows: &[u32],
    source_class_map: &[u8],
    source_class_count: usize,
    source_initial_row: u32,
    cache_identity: u64,
    artifact_identity: [u8; 32],
    max_resident_bytes: usize,
) -> Option<FrozenReverseSupertransitionStorageV1> {
    if cache_identity == 0
        || source_class_count == 0
        || source_class_count > 256
        || source_rows.is_empty()
        || source_rows.len().checked_rem(source_class_count) != Some(0)
        || !frozen_dynamic_source_rows_are_normalizable(source_rows, source_class_count)
    {
        return None;
    }
    let state_count = source_rows.len().checked_div(source_class_count)?;
    let source_initial_row_usize = usize::try_from(source_initial_row).ok()?;
    if source_initial_row_usize.checked_rem(source_class_count) != Some(0) {
        return None;
    }
    let source_initial_state = source_initial_row_usize.checked_div(source_class_count)?;
    if source_initial_state >= state_count {
        return None;
    }
    let columns = coalesce_frozen_compact_columns(
        source_rows,
        source_class_map,
        source_class_count,
        state_count,
        source_initial_state,
    )?;
    let class_count = columns.class_count;

    let quad = frozen_reverse_quad_rows_v14_geometry(state_count, class_count).and_then(
        |(_, _, _, _, block_cells, total_cells, _)| {
            let resident_bytes = total_cells
                .checked_mul(core::mem::size_of::<u16>())?
                .checked_add(FROZEN_REVERSE_SUPERTRANSITION_V1_BYTES)?;
            if resident_bytes > max_resident_bytes
                || resident_bytes > FROZEN_QUAD_ROWS_V14_MAX_BYTES
            {
                return None;
            }
            let rows = build_frozen_quad_rows_v14_with_geometry(
                source_rows,
                &columns,
                source_class_count,
                state_count,
                source_initial_state,
                block_cells,
                total_cells,
            )?;
            (rows.len() == total_cells).then_some((
                rows,
                block_cells,
                FROZEN_DYNAMIC_ROWS_V14_FORMAT_VERSION,
                FROZEN_QUAD_ROWS_V14_MAX_BYTES,
            ))
        },
    );
    let (rows, block_cells, format_version, resident_cap) = if let Some(quad) = quad {
        quad
    } else {
        let (_, block_cells, total_cells, _) =
            frozen_reverse_pair_rows_v13_geometry(state_count, class_count)?;
        let resident_bytes = total_cells
            .checked_mul(core::mem::size_of::<u16>())?
            .checked_add(FROZEN_REVERSE_SUPERTRANSITION_V1_BYTES)?;
        if resident_bytes > max_resident_bytes
            || resident_bytes > FROZEN_PAIR_ROWS_V13_MAX_BYTES
        {
            return None;
        }
        let rows = build_frozen_pair_rows_v13_with_geometry(
            source_rows,
            &columns,
            source_class_count,
            state_count,
            source_initial_state,
            block_cells,
            total_cells,
        )?;
        if rows.len() != total_cells {
            return None;
        }
        (
            rows,
            block_cells,
            FROZEN_DYNAMIC_ROWS_V13_FORMAT_VERSION,
            FROZEN_PAIR_ROWS_V13_MAX_BYTES,
        )
    };
    let resident_bytes = rows
        .len()
        .checked_mul(core::mem::size_of::<u16>())?
        .checked_add(FROZEN_REVERSE_SUPERTRANSITION_V1_BYTES)?;
    if resident_bytes > resident_cap {
        return None;
    }
    let descriptor = Box::new(FrozenReverseSupertransitionV1 {
        ready_seal: FROZEN_REVERSE_SUPERTRANSITION_V1_READY_SEAL,
        magic: FROZEN_REVERSE_SUPERTRANSITION_V1_MAGIC,
        abi_version: FROZEN_REVERSE_SUPERTRANSITION_V1_ABI_VERSION,
        abi_version_complement: !FROZEN_REVERSE_SUPERTRANSITION_V1_ABI_VERSION,
        descriptor_bytes: FROZEN_REVERSE_SUPERTRANSITION_V1_BYTES,
        artifact_identity,
        rows_address: rows.as_ptr().expose_provenance(),
        source_rows_address: source_rows.as_ptr().expose_provenance(),
        cache_identity,
        compact_live_cells: rows.len(),
        source_live_cells: source_rows.len(),
        state_count: u32::try_from(state_count).ok()?,
        class_count: u32::try_from(class_count).ok()?,
        block_cells: u32::try_from(block_cells).ok()?,
        initial_block: 0,
        source_initial_row,
        source_row_stride: u32::try_from(source_class_count).ok()?,
        format_version,
        reserved: 0,
        class_map: columns.class_map,
    });
    let storage = FrozenReverseSupertransitionStorageV1 {
        rows,
        descriptor,
        resident_bytes,
    };
    storage.is_valid().then_some(storage)
}

fn retain_frozen_reverse_supertransition_v1(
    candidate: Option<FrozenReverseSupertransitionStorageV1>,
    forward_resident_bytes: usize,
    retained_map_reserve_bytes: usize,
    retained_bytes: usize,
    max_packed_bytes: usize,
) -> Option<FrozenReverseSupertransitionStorageV1> {
    let candidate = candidate?;
    let combined = forward_resident_bytes
        .checked_add(retained_map_reserve_bytes)?
        .checked_add(candidate.resident_bytes)?;
    (combined <= retained_bytes && combined <= max_packed_bytes).then_some(candidate)
}

impl FrozenReverseSupertransitionStorageV1 {
    fn is_valid(&self) -> bool {
        let rows = *self.descriptor;
        let Ok(state_count) = usize::try_from(rows.state_count) else {
            return false;
        };
        let Ok(class_count) = usize::try_from(rows.class_count) else {
            return false;
        };
        let Ok(block_cells) = usize::try_from(rows.block_cells) else {
            return false;
        };
        let Ok(source_row_stride) = usize::try_from(rows.source_row_stride) else {
            return false;
        };
        let Ok(source_initial_row) = usize::try_from(rows.source_initial_row) else {
            return false;
        };
        let geometry = match rows.format_version {
            FROZEN_DYNAMIC_ROWS_V13_FORMAT_VERSION => {
                frozen_reverse_pair_rows_v13_geometry(state_count, class_count)
                    .map(|(pair, block, total, bytes)| (pair, 0, 0, block, total, bytes))
            }
            FROZEN_DYNAMIC_ROWS_V14_FORMAT_VERSION => {
                frozen_reverse_quad_rows_v14_geometry(state_count, class_count).map(
                    |(quad, tail3, tail2, _, block, total, bytes)| {
                        (quad, tail3, tail2, block, total, bytes)
                    },
                )
            }
            _ => None,
        };
        let Some((first_section, second_section, third_section, expected_block, total, _)) =
            geometry
        else {
            return false;
        };
        if rows.ready_seal != FROZEN_REVERSE_SUPERTRANSITION_V1_READY_SEAL
            || rows.magic != FROZEN_REVERSE_SUPERTRANSITION_V1_MAGIC
            || rows.abi_version != FROZEN_REVERSE_SUPERTRANSITION_V1_ABI_VERSION
            || rows.abi_version_complement != !rows.abi_version
            || rows.descriptor_bytes != FROZEN_REVERSE_SUPERTRANSITION_V1_BYTES
            || rows.rows_address == 0
            || rows.rows_address.checked_rem(core::mem::align_of::<u16>()) != Some(0)
            || rows.rows_address != self.rows.as_ptr().expose_provenance()
            || rows.source_rows_address == 0
            || rows.source_rows_address.checked_rem(core::mem::align_of::<u32>()) != Some(0)
            || rows.cache_identity == 0
            || rows.compact_live_cells != self.rows.len()
            || rows.compact_live_cells != total
            || rows.source_live_cells == 0
            || rows.source_live_cells
                > usize::try_from(DYNAMIC_NATIVE_ROWS_V1_NEXT_ROW_TOKEN_MASK)
                    .unwrap_or(usize::MAX)
            || rows.initial_block != 0
            || rows.source_initial_row == FROZEN_PREPARED_HEADER_V1_NO_REVERSE_ROW
            || source_row_stride == 0
            || source_row_stride > 256
            || rows.source_live_cells.checked_rem(source_row_stride) != Some(0)
            || rows.source_live_cells.checked_div(source_row_stride) != Some(state_count)
            || source_initial_row.checked_rem(source_row_stride) != Some(0)
            || source_initial_row
                .checked_add(source_row_stride)
                .is_none_or(|end| end > rows.source_live_cells)
            || block_cells != expected_block
            || self.resident_bytes
                != total
                    .checked_mul(core::mem::size_of::<u16>())
                    .and_then(|bytes| {
                        bytes.checked_add(FROZEN_REVERSE_SUPERTRANSITION_V1_BYTES)
                    })
                    .unwrap_or(usize::MAX)
            || self.resident_bytes
                > if rows.format_version == FROZEN_DYNAMIC_ROWS_V14_FORMAT_VERSION {
                    FROZEN_QUAD_ROWS_V14_MAX_BYTES
                } else {
                    FROZEN_PAIR_ROWS_V13_MAX_BYTES
                }
            || rows.reserved != 0
        {
            return false;
        }

        let mut represented = [false; 256];
        for &class in &rows.class_map {
            let class = usize::from(class);
            if class >= class_count {
                return false;
            }
            represented[class] = true;
        }
        if represented[..class_count].iter().any(|&present| !present) {
            return false;
        }

        if rows.format_version == FROZEN_DYNAMIC_ROWS_V13_FORMAT_VERSION {
            let live_class_mask = (1_u16 << class_count) - 1;
            for block in self.rows.chunks_exact(block_cells) {
                let tail_accepts = block[first_section];
                if tail_accepts & !live_class_mask != 0 {
                    return false;
                }
                for first_class in 0..class_count {
                    for second_class in 0..class_count {
                        let cell = block[first_class * class_count + second_class];
                        let accepts = cell & DYNAMIC_NATIVE_ROWS_V13_ANY_ACCEPT_MASK != 0;
                        let back_one =
                            cell & DYNAMIC_NATIVE_ROWS_V13_ACCEPT_BACK_ONE_MASK != 0;
                        let first_accepts = tail_accepts & (1_u16 << first_class) != 0;
                        let token = cell & DYNAMIC_NATIVE_ROWS_V13_NEXT_BLOCK_TOKEN_MASK;
                        if (back_one && (!accepts || !first_accepts))
                            || (first_accepts && !accepts)
                            || (token != 0
                                && usize::from(token)
                                    .checked_sub(1)
                                    .is_none_or(|destination| {
                                        destination >= total
                                            || destination.checked_rem(block_cells) != Some(0)
                                    }))
                        {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        let sections = [
            (0_usize, first_section, 4_u16, true),
            (first_section, second_section, 3, false),
            (first_section + second_section, third_section, 2, false),
            (
                first_section + second_section + third_section,
                class_count,
                1,
                false,
            ),
        ];
        for block in self.rows.chunks_exact(block_cells) {
            for (start, count, length, permits_token) in sections {
                for &cell in &block[start..start + count] {
                    let accepts = cell & DYNAMIC_NATIVE_ROWS_V14_ANY_ACCEPT_MASK != 0;
                    let distance = (cell & DYNAMIC_NATIVE_ROWS_V14_ACCEPT_DISTANCE_MASK) >> 13;
                    let token = cell & DYNAMIC_NATIVE_ROWS_V14_NEXT_BLOCK_TOKEN_MASK;
                    if (!accepts && distance != 0)
                        || distance >= length
                        || (!permits_token && token != 0)
                        || (token != 0
                            && usize::from(token)
                                .checked_sub(1)
                                .is_none_or(|destination| {
                                    destination >= total
                                        || destination.checked_rem(block_cells) != Some(0)
                                }))
                    {
                        return false;
                    }
                }
            }
        }
        true
    }

    fn generation_key(&self) -> FrozenReverseSupertransitionGenerationKey {
        let rows = *self.descriptor;
        // The descriptor Box and row Box have no mutable safe API and remain
        // owned by the borrowed forward owner. Pointer identity therefore
        // binds the inline map and row contents without copying or scanning
        // them on every cached-header rearm. Setup validation above remains
        // the sole full semantic/map authentication pass.
        FrozenReverseSupertransitionGenerationKey {
            descriptor_address: (self.descriptor.as_ref()
                as *const FrozenReverseSupertransitionV1)
                .expose_provenance(),
            ready_seal: rows.ready_seal,
            magic: rows.magic,
            abi_version: rows.abi_version,
            abi_version_complement: rows.abi_version_complement,
            descriptor_bytes: rows.descriptor_bytes,
            artifact_identity: rows.artifact_identity,
            rows_address: rows.rows_address,
            source_rows_address: rows.source_rows_address,
            cache_identity: rows.cache_identity,
            compact_live_cells: rows.compact_live_cells,
            source_live_cells: rows.source_live_cells,
            state_count: rows.state_count,
            class_count: rows.class_count,
            block_cells: rows.block_cells,
            initial_block: rows.initial_block,
            source_initial_row: rows.source_initial_row,
            source_row_stride: rows.source_row_stride,
            format_version: rows.format_version,
            reserved: rows.reserved,
        }
    }
}

#[cfg(test)]
fn frozen_reverse_supertransition_span_start(
    storage: &FrozenReverseSupertransitionStorageV1,
    haystack: &[u8],
    window_start: usize,
    selected_end: usize,
) -> Option<usize> {
    if !storage.is_valid() || window_start > selected_end || selected_end > haystack.len() {
        return None;
    }
    let descriptor = *storage.descriptor;
    let class_count = usize::try_from(descriptor.class_count).ok()?;
    let block_cells = usize::try_from(descriptor.block_cells).ok()?;
    let mut block = usize::try_from(descriptor.initial_block).ok()?;
    let mut cursor = selected_end;
    let mut candidate = None;

    if descriptor.format_version == FROZEN_DYNAMIC_ROWS_V14_FORMAT_VERSION {
        let (quad, tail3, tail2, tail1, _, total, _) =
            frozen_reverse_quad_rows_v14_geometry(
                usize::try_from(descriptor.state_count).ok()?,
                class_count,
            )?;
        while cursor.checked_sub(window_start)? >= 4 {
            let block_low = cursor.checked_sub(4)?;
            let mut key = 0usize;
            for &byte in haystack.get(block_low..cursor)?.iter().rev() {
                let class = usize::from(*descriptor.class_map.get(usize::from(byte))?);
                key = key.checked_mul(class_count)?.checked_add(class)?;
            }
            let cell = *storage.rows.get(block.checked_add(key)?)?;
            cursor = block_low;
            if cell & DYNAMIC_NATIVE_ROWS_V14_ANY_ACCEPT_MASK != 0 {
                let distance = usize::from(
                    (cell & DYNAMIC_NATIVE_ROWS_V14_ACCEPT_DISTANCE_MASK) >> 13,
                );
                candidate = cursor.checked_add(distance);
            }
            let token = cell & DYNAMIC_NATIVE_ROWS_V14_NEXT_BLOCK_TOKEN_MASK;
            if token == 0 {
                return candidate;
            }
            block = usize::from(token).checked_sub(1)?;
            if block >= total || !block.is_multiple_of(block_cells) {
                return None;
            }
        }
        let remaining = cursor.checked_sub(window_start)?;
        if remaining != 0 {
            let (section_offset, section_cells) = match remaining {
                1 => (quad.checked_add(tail3)?.checked_add(tail2)?, tail1),
                2 => (quad.checked_add(tail3)?, tail2),
                3 => (quad, tail3),
                _ => return None,
            };
            let block_low = cursor.checked_sub(remaining)?;
            let mut key = 0usize;
            for &byte in haystack.get(block_low..cursor)?.iter().rev() {
                let class = usize::from(*descriptor.class_map.get(usize::from(byte))?);
                key = key.checked_mul(class_count)?.checked_add(class)?;
            }
            if key >= section_cells {
                return None;
            }
            let cell = *storage
                .rows
                .get(block.checked_add(section_offset)?.checked_add(key)?)?;
            cursor = block_low;
            if cell & DYNAMIC_NATIVE_ROWS_V14_ANY_ACCEPT_MASK != 0 {
                let distance = usize::from(
                    (cell & DYNAMIC_NATIVE_ROWS_V14_ACCEPT_DISTANCE_MASK) >> 13,
                );
                candidate = cursor.checked_add(distance);
            }
        }
        return candidate;
    }

    let (pair_cells, _, total, _) = frozen_reverse_pair_rows_v13_geometry(
        usize::try_from(descriptor.state_count).ok()?,
        class_count,
    )?;
    while cursor.checked_sub(window_start)? >= 2 {
        let block_low = cursor.checked_sub(2)?;
        let high = usize::from(*haystack.get(block_low.checked_add(1)?)?);
        let low = usize::from(*haystack.get(block_low)?);
        let high_class = usize::from(*descriptor.class_map.get(high)?);
        let low_class = usize::from(*descriptor.class_map.get(low)?);
        let key = high_class
            .checked_mul(class_count)?
            .checked_add(low_class)?;
        let cell = *storage.rows.get(block.checked_add(key)?)?;
        cursor = block_low;
        if cell & DYNAMIC_NATIVE_ROWS_V13_ANY_ACCEPT_MASK != 0 {
            candidate = cursor.checked_add(usize::from(
                cell & DYNAMIC_NATIVE_ROWS_V13_ACCEPT_BACK_ONE_MASK != 0,
            ));
        }
        let token = cell & DYNAMIC_NATIVE_ROWS_V13_NEXT_BLOCK_TOKEN_MASK;
        if token == 0 {
            return candidate;
        }
        block = usize::from(token).checked_sub(1)?;
        if block >= total || !block.is_multiple_of(block_cells) {
            return None;
        }
    }
    if cursor > window_start {
        cursor = cursor.checked_sub(1)?;
        let byte = usize::from(*haystack.get(cursor)?);
        let class = usize::from(*descriptor.class_map.get(byte)?);
        let accepts = *storage.rows.get(block.checked_add(pair_cells)?)?;
        if accepts & (1_u16.checked_shl(u32::try_from(class).ok()?)?) != 0 {
            candidate = Some(cursor);
        }
    }
    candidate
}

#[cfg(test)]
fn frozen_reverse_scalar_span_start(
    source_rows: &[u32],
    source_class_map: &[u8],
    source_class_count: usize,
    source_initial_row: usize,
    haystack: &[u8],
    window_start: usize,
    selected_end: usize,
) -> Option<usize> {
    if source_class_map.len() != 256
        || source_class_count == 0
        || source_initial_row.checked_rem(source_class_count) != Some(0)
        || source_rows.len().checked_rem(source_class_count) != Some(0)
        || source_initial_row
            .checked_add(source_class_count)
            .is_none_or(|end| end > source_rows.len())
        || window_start > selected_end
        || selected_end > haystack.len()
    {
        return None;
    }
    let mut row = source_initial_row;
    let mut cursor = selected_end;
    let mut candidate = None;
    while cursor > window_start {
        cursor = cursor.checked_sub(1)?;
        let class = usize::from(*source_class_map.get(usize::from(*haystack.get(cursor)?))?);
        if class >= source_class_count {
            return None;
        }
        let cell = *source_rows.get(row.checked_add(class)?)?;
        if cell & DYNAMIC_NATIVE_ROWS_V1_ACCEPT_MASK != 0 {
            candidate = Some(cursor);
        }
        let token = cell & DYNAMIC_NATIVE_ROWS_V1_NEXT_ROW_TOKEN_MASK;
        if token == 0 {
            break;
        }
        row = usize::try_from(token.checked_sub(1)?).ok()?;
        if row >= source_rows.len() || !row.is_multiple_of(source_class_count) {
            return None;
        }
    }
    candidate
}

