    #[test]
    fn dynamic_native_rows_single_settlement_is_workspace_local_under_concurrency() {
        let compiled = program(
            "(?:ab|ac)+z",
            OutputContract::Exists,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        let mut haystack = vec![b'a'; 64];
        for pair in haystack[..62].chunks_exact_mut(2) {
            pair.copy_from_slice(b"ab");
        }
        haystack[62] = b'z';
        haystack[63] = b'!';
        let window = SearchWindow::full(&haystack);
        let identity = compiled.artifact_identity();

        std::thread::scope(|scope| {
            let mut workers = Vec::new();
            for _ in 0..4 {
                let compiled = &compiled;
                let haystack = &haystack;
                workers.push(scope.spawn(move || {
                    let mut workspace = compiled
                        .prepare_workspace()
                        .expect("independent prepared K0 workspace");
                    let (cold, _, _) = compiled
                        .preflight_dynamic_native_rows_with_workspace(
                            haystack,
                            window,
                            &mut workspace,
                            identity,
                        )
                        .expect("concurrent cold preflight");
                    assert_eq!(
                        cold,
                        RetainedPartialPreflight::Complete(MatchResult::Exists(true))
                    );
                    for context in ["concurrent admission", "concurrent local readmission"] {
                        let (entered, address, cache_identity) = compiled
                            .preflight_dynamic_native_rows_with_workspace(
                                haystack,
                                window,
                                &mut workspace,
                                identity,
                            )
                            .unwrap_or_else(|error| panic!("{context}: {error}"));
                        assert_eq!(entered, RetainedPartialPreflight::Enter(window));
                        assert_ne!((address, cache_identity), (0, 0));
                    }
                    let dynamic = dynamic_rows(&workspace);
                    assert_eq!(dynamic.preflight_admission_settlements, 3);
                    assert_eq!(dynamic.preflight_admission_replacements, 1);
                    assert_eq!(dynamic.state.native_entry_window(), Some(window));
                }));
            }
            for worker in workers {
                worker.join().expect("independent dynamic-row worker");
            }
        });
    }

    #[test]
    fn trusted_v3_window_subtraction_matches_checked_exact_windows() {
        let compiled = program(
            "(?:ab|ac)+z",
            OutputContract::Exists,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        let mut haystack = vec![b'!'; 80];
        for pair in haystack[8..70].chunks_exact_mut(2) {
            pair.copy_from_slice(b"ab");
        }
        haystack[70] = b'z';
        let identity = compiled.artifact_identity();

        for window in [
            SearchWindow::new(0, 0),
            SearchWindow::new(8, 8),
            SearchWindow::new(haystack.len(), haystack.len()),
            SearchWindow::new(8, 72),
            SearchWindow::full(&haystack),
        ] {
            let mut checked = compiled
                .prepare_workspace()
                .expect("checked exact-window workspace");
            let mut trusted = compiled
                .prepare_workspace()
                .expect("trusted exact-window workspace");
            for round in 0..3 {
                let (checked_outcome, checked_address, checked_cache_identity) = compiled
                    .preflight_dynamic_native_rows_with_workspace(
                        &haystack,
                        window,
                        &mut checked,
                        identity,
                    )
                    .expect("checked exact-window preflight");
                let (trusted_outcome, trusted_address, trusted_cache_identity) = compiled
                    .compiler_private_preflight_dynamic_native_rows_v3_with_workspace(
                        &haystack,
                        window,
                        &mut trusted,
                        identity,
                    )
                    .expect("trusted exact-window preflight");
                assert_eq!(trusted_outcome, checked_outcome, "{window:?}/round {round}");
                assert_eq!(
                    trusted_address != 0,
                    checked_address != 0,
                    "{window:?}/round {round} descriptor"
                );
                assert_eq!(
                    trusted_cache_identity != 0,
                    checked_cache_identity != 0,
                    "{window:?}/round {round} cache"
                );

                for workspace in [&checked, &trusted] {
                    let state = &dynamic_rows(workspace).state;
                    if matches!(checked_outcome, RetainedPartialPreflight::Enter(_)) {
                        assert_eq!(checked_outcome, RetainedPartialPreflight::Enter(window));
                        assert_eq!(
                            state
                                .native_entry_admission
                                .map(|admission| admission.original_input_bytes),
                            Some(window.end.saturating_sub(window.start)),
                            "{window:?}/round {round} admitted length"
                        );
                    } else {
                        assert!(state.native_entry_window().is_none());
                    }
                }
            }
        }
    }

    fn authentic_partial_resume(
        program: &CompiledProgram,
        haystack: &[u8],
        window: SearchWindow,
    ) -> Option<PartialDfaResume> {
        let partial = program.partial_dfa()?;
        let (prefix_plan, supported) =
            PartialDfaPrefixPlan::derive(program.anchored_prefix.sets());
        assert!(supported, "test fixture has no retained-prefix scanner");
        match program.output {
            OutputContract::Exists => match partial
                .exists(
                    haystack,
                    window.start,
                    window.end,
                    program.anchored_prefix.sets(),
                    prefix_plan,
                )
                .ok()?
            {
                PartialDfaResult::Resume(resume) => Some(resume),
                PartialDfaResult::Complete(_) => None,
            },
            OutputContract::SelectedEnd => match partial
                .selected_end(
                    haystack,
                    window.start,
                    window.end,
                    program.anchored_prefix.sets(),
                    prefix_plan,
                )
                .ok()?
            {
                PartialDfaResult::Resume(resume) => Some(resume),
                PartialDfaResult::Complete(_) => None,
            },
            OutputContract::Span => match partial
                .selected_span_end(
                    haystack,
                    window.start,
                    window.end,
                    program.anchored_prefix.sets(),
                    prefix_plan,
                )
                .ok()?
            {
                PartialDfaResult::Resume(resume) => Some(resume),
                PartialDfaResult::Complete(_) => None,
            },
        }
    }

    fn retained_handoff_fixture(
        pattern: &str,
        output: OutputContract,
        haystack: &[u8],
        window: SearchWindow,
        require_pending: bool,
    ) -> (CompiledProgram, PartialDfaResume) {
        (2..=32)
            .find_map(|max_states| {
                let compiled = program(
                    pattern,
                    output,
                    CompileMode::Optimizing,
                    DeterminizeLimits {
                        max_states,
                        ..DeterminizeLimits::default()
                    },
                );
                let resume = authentic_partial_resume(&compiled, haystack, window)?;
                (resume.position > window.start
                    && resume.position < window.end
                    && (!require_pending || resume.pending_end.is_some()))
                .then_some((compiled, resume))
            })
            .unwrap_or_else(|| panic!("no retained handoff fixture for {pattern}/{output:?}"))
    }

    fn endpoint_oracle_first_slice_fixture(
        pattern: &str,
        output: OutputContract,
        haystack: &[u8],
        expected_oracle_result: bool,
    ) -> (CompiledProgram, PartialDfaResume) {
        let window = SearchWindow::full(haystack);
        (2..=128)
            .find_map(|max_states| {
                let compiled = program(
                    pattern,
                    output,
                    CompileMode::Optimizing,
                    DeterminizeLimits {
                        max_states,
                        ..DeterminizeLimits::default()
                    },
                );
                let resume = authentic_partial_resume(&compiled, haystack, window)?;
                if resume.pending_end.is_some()
                    || window.end.saturating_sub(resume.position) < PARTIAL_DFA_MIN_INPUT_BYTES
                {
                    return None;
                }
                let (frontier, pending) = compiled
                    .partial_dfa()?
                    .resume_frontier(resume.state)?;
                if pending {
                    return None;
                }
                let found = compiled
                    .bit_parallel_exists()?
                    .search_from_raw_frontier(
                        haystack,
                        resume.position,
                        window.end,
                        frontier,
                    )
                    .ok()?;
                (found == expected_oracle_result).then_some((compiled, resume))
            })
            .unwrap_or_else(|| {
                panic!(
                    "no endpoint first-slice oracle fixture for {pattern}/{output:?}/{expected_oracle_result}"
                )
            })
    }

    fn fixed_endpoint_oracle_hole_fixture(
        pattern: &str,
        output: OutputContract,
        haystack: &[u8],
        window: SearchWindow,
        expected_end: usize,
    ) -> (CompiledProgram, PartialDfaResume) {
        (1..=64)
            .find_map(|max_states| {
                let compiled = program(
                    pattern,
                    output,
                    CompileMode::Optimizing,
                    DeterminizeLimits {
                        max_states,
                        ..DeterminizeLimits::default()
                    },
                );
                let width = compiled.exact_match_width?;
                let expected_start = expected_end.checked_sub(width)?;
                let resume = authentic_partial_resume(&compiled, haystack, window)?;
                if resume.pending_end.is_some()
                    || resume.position <= expected_start
                    || resume.position >= expected_end
                    || window.end.saturating_sub(resume.position)
                        < PARTIAL_DFA_MIN_INPUT_BYTES
                {
                    return None;
                }
                let (frontier, pending) = compiled
                    .partial_dfa()?
                    .resume_frontier(resume.state)?;
                if pending {
                    return None;
                }
                let first_end = compiled
                    .bit_parallel_exists()?
                    .search_first_accepting_end_from_raw_frontier(
                        haystack,
                        resume.position,
                        window.end,
                        frontier,
                    )
                    .ok()?;
                (first_end == Some(expected_end)).then_some((compiled, resume))
            })
            .unwrap_or_else(|| {
                panic!(
                    "no fixed-width endpoint hole fixture for {pattern}/{output:?}/{expected_end}"
                )
            })
    }

    fn retained_runtime_observation(
        workspace: &ProgramWorkspace,
    ) -> (u8, u16, bool, Option<SearchWindow>, usize) {
        let state = &workspace.partial.as_deref().unwrap().state;
        (
            state.consecutive_fallbacks,
            state.bypass_remaining,
            state.native_entry_in_flight,
            state.native_entry_window,
            state.frozen_resumed,
        )
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one exhaustive differential owns selection, every window, wire, and structural declines"
    )]
    fn bit_parallel_exists_is_general_exact_bounded_and_round_trips() {
        let cases: [(&str, &[u8]); 6] = [
            (r"(?:ab|c)*z", b"xxabczxx"),
            (r"(?:ab|c)*?z", b"xxabczxx"),
            (r"(?:a|aa|b)+c", b"xxaaaacx"),
            (r"(?:[a-c]{0,3}d)?", b"xxabcdxx"),
            (r"(?:a(?:bc)?|b+d)e", b"xxbbbde"),
            (r"(?:a{2,4}|ba+)c", b"xxbaaacx"),
        ];
        let mut haystacks = generated_byte_strings(b"abcx", 4);
        haystacks.extend(cases.iter().map(|(_, witness)| witness.to_vec()));
        haystacks.extend([b"zzzzzz".to_vec(), b"xxxxabczxxxx".to_vec()]);

        for (pattern, _) in cases {
            let compiled = program(
                pattern,
                OutputContract::Exists,
                CompileMode::Optimizing,
                DeterminizeLimits {
                    max_states: 0,
                    ..DeterminizeLimits::default()
                },
            );
            assert_eq!(compiled.engine_kind(), EngineKind::OrderedNfa, "{pattern}");
            assert_eq!(
                compiled.engine_selection_reason(),
                Some(EngineSelectionReason::DeterminizationResourceLimit),
                "{pattern}"
            );
            assert!(
                compiled
                    .determinization_report()
                    .is_some_and(|report| report.decline.is_some()),
                "{pattern}"
            );
            let stats = compiled
                .bit_parallel_exists_stats()
                .unwrap_or_else(|| panic!("bounded graph did not select bit execution: {pattern}"));
            assert!(compiled.native_dfa_view().is_none());
            assert!(stats.thompson_states <= MAX_BIT_PARALLEL_EXISTS_STATES);
            assert!(stats.derivation_work <= MAX_BIT_PARALLEL_EXISTS_WORK);
            assert!(stats.peak_build_bytes <= MAX_BIT_PARALLEL_EXISTS_MEMORY_BYTES);
            assert!(stats.transition_entries > 0);

            let bytes = compiled.serialize().expect("serialize bit executor");
            assert_eq!(
                u32::from_le_bytes(bytes[8..12].try_into().unwrap()),
                PROGRAM_FORMAT_VERSION_V7
            );
            assert_ne!(bytes[15] & PROGRAM_FLAG_NFA_OPTIMIZING_FALLBACK, 0);
            let restored = CompiledProgram::deserialize(&bytes).expect("restore bit executor");
            assert_eq!(restored.serialize().unwrap(), bytes);
            assert_eq!(restored.bit_parallel_exists_stats(), Some(stats));
            let reference = program(
                pattern,
                OutputContract::Exists,
                CompileMode::Fast,
                DeterminizeLimits::default(),
            );
            assert_eq!(reference.bit_parallel_exists_stats(), None);

            let mut compiled_workspace = compiled.prepare_workspace().unwrap();
            let mut restored_workspace = restored.prepare_workspace().unwrap();
            let mut reference_workspace = reference.prepare_workspace().unwrap();
            assert!(matches!(
                compiled.search_with_workspace(
                    b"abc",
                    SearchWindow::new(2, 1),
                    &mut compiled_workspace,
                ),
                Err(CompileError::InvalidWindow {
                    start: 2,
                    end: 1,
                    haystack_len: 3,
                })
            ));
            assert!(matches!(
                restored.search_optimized_with_workspace(
                    b"abc",
                    SearchWindow::new(0, usize::MAX),
                    &mut restored_workspace,
                ),
                Err(CompileError::InvalidWindow {
                    start: 0,
                    end: usize::MAX,
                    haystack_len: 3,
                })
            ));

            for haystack in &haystacks {
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        let expected = reference
                            .search_with_workspace(
                                haystack,
                                window,
                                &mut reference_workspace,
                            )
                            .unwrap();
                        assert_eq!(
                            compiled
                                .search_with_workspace(
                                    haystack,
                                    window,
                                    &mut compiled_workspace,
                                )
                                .unwrap(),
                            expected,
                            "ordinary mismatch: {pattern}/{haystack:?}/{start}..{end}"
                        );
                        assert_eq!(
                            compiled
                                .search_optimized_with_workspace(
                                    haystack,
                                    window,
                                    &mut compiled_workspace,
                                )
                                .unwrap(),
                            expected,
                            "optimized mismatch: {pattern}/{haystack:?}/{start}..{end}"
                        );
                        assert_eq!(
                            restored
                                .search_optimized_with_workspace(
                                    haystack,
                                    window,
                                    &mut restored_workspace,
                                )
                                .unwrap(),
                            expected,
                            "restored mismatch: {pattern}/{haystack:?}/{start}..{end}"
                        );
                    }
                }
            }
        }

        let complete = program(
            r"(?:ab|c)*z",
            OutputContract::Exists,
            CompileMode::Optimizing,
            DeterminizeLimits::default(),
        );
        assert_eq!(complete.engine_kind(), EngineKind::OrderedDfa);
        assert_eq!(complete.bit_parallel_exists_stats(), None);

        for (pattern, output, mode) in [
            (r"(?:ab|c)*z", OutputContract::Exists, CompileMode::Fast),
            (
                r"(?m:^a$)",
                OutputContract::Exists,
                CompileMode::Optimizing,
            ),
        ] {
            let declined = program(
                pattern,
                output,
                mode,
                DeterminizeLimits {
                    max_states: 0,
                    ..DeterminizeLimits::default()
                },
            );
            assert_eq!(declined.bit_parallel_exists_stats(), None, "{pattern}");
        }

        let wide_pattern = format!("{}z", "a".repeat(MAX_BIT_PARALLEL_EXISTS_STATES));
        let wide = program(
            &wide_pattern,
            OutputContract::Exists,
            CompileMode::Optimizing,
            DeterminizeLimits {
                max_states: 0,
                ..DeterminizeLimits::default()
            },
        );
        assert!(wide.raw.roles.len() > MAX_BIT_PARALLEL_EXISTS_STATES);
        assert_eq!(wide.bit_parallel_exists_stats(), None);

        let multiword_pattern = format!("{}z", "a".repeat(64));
        let multiword = program(
            &multiword_pattern,
            OutputContract::Exists,
            CompileMode::Optimizing,
            DeterminizeLimits {
                max_states: 0,
                ..DeterminizeLimits::default()
            },
        );
        let multiword_stats = multiword
            .bit_parallel_exists_stats()
            .expect("two-word graph-derived fallback");
        assert_eq!(multiword_stats.words, 2);
        assert!(multiword_stats.consuming_states >= 64);
        assert_eq!(multiword_stats.source_nibbles, 0);
        assert_eq!(multiword_stats.root_transition_entries, 2 * 256);
        let multiword_bytes = multiword.serialize().unwrap();
        let restored_multiword = CompiledProgram::deserialize(&multiword_bytes).unwrap();
        assert_eq!(restored_multiword.serialize().unwrap(), multiword_bytes);
        assert_eq!(
            restored_multiword.bit_parallel_exists_stats(),
            Some(multiword_stats)
        );
        let reference = program(
            &multiword_pattern,
            OutputContract::Exists,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        let endpoint_reference = program(
            &multiword_pattern,
            OutputContract::SelectedEnd,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        for haystack in [
            b"".as_slice(),
            b"z".as_slice(),
            b"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaz"
                .as_slice(),
            b"xaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaax"
                .as_slice(),
        ] {
            for start in 0..=haystack.len() {
                for end in start..=haystack.len() {
                    let window = SearchWindow::new(start, end);
                    assert_eq!(
                        multiword.search(haystack, window).unwrap(),
                        reference.search(haystack, window).unwrap(),
                        "multiword mismatch: {haystack:?}/{start}..{end}"
                    );
                    assert_eq!(
                        restored_multiword.search(haystack, window).unwrap(),
                        reference.search(haystack, window).unwrap(),
                        "restored multiword mismatch: {haystack:?}/{start}..{end}"
                    );
                    let expected_end = match endpoint_reference.search(haystack, window).unwrap() {
                        MatchResult::SelectedEnd(end) => end,
                        other => panic!("unexpected endpoint reference result: {other:?}"),
                    };
                    for candidate in [&multiword, &restored_multiword] {
                        assert_eq!(
                            candidate
                                .bit_parallel_exists()
                                .unwrap()
                                .search_first_accepting_end(haystack, start, end)
                                .unwrap(),
                            expected_end,
                            "multiword first-end mismatch: {haystack:?}/{start}..{end}"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn bit_parallel_endpoint_negative_oracle_is_exact_and_round_trips() {
        let cases: [(&str, &[u8]); 5] = [
            (r"(?:ab|c)*z", b"xxabczxx"),
            (r"(?:ab|c)*?z", b"xxabczxx"),
            (r"(?:a|aa|b)+c", b"xxaaaacx"),
            (r"(?:a(?:bc)?|b+d)e", b"xxbbbde"),
            (r"(?:a{2,4}|ba+)c", b"xxbaaacx"),
        ];
        let mut short_haystacks = generated_byte_strings(b"abcxz", 3);
        short_haystacks.extend(cases.iter().map(|(_, witness)| witness.to_vec()));
        let limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };

        for output in [OutputContract::SelectedEnd, OutputContract::Span] {
            for (pattern, witness) in cases {
                let compiled = program(pattern, output, CompileMode::Optimizing, limits);
                assert_eq!(compiled.engine_kind(), EngineKind::OrderedNfa, "{pattern}");
                let stats = compiled.bit_parallel_exists_stats().unwrap_or_else(|| {
                    panic!("missing endpoint existence oracle: {pattern}/{output:?}")
                });
                assert!(compiled.native_bit_parallel_exists_view().is_none());

                let bytes = compiled.serialize().expect("serialize endpoint oracle");
                assert_eq!(
                    u32::from_le_bytes(bytes[8..12].try_into().unwrap()),
                    PROGRAM_FORMAT_VERSION_V7
                );
                assert_ne!(bytes[15] & PROGRAM_FLAG_NFA_OPTIMIZING_FALLBACK, 0);
                let restored = CompiledProgram::deserialize(&bytes)
                    .expect("restore endpoint existence oracle");
                assert_eq!(restored.serialize().unwrap(), bytes);
                assert_eq!(restored.bit_parallel_exists_stats(), Some(stats));
                assert!(restored.native_bit_parallel_exists_view().is_none());

                let reference = program(
                    pattern,
                    output,
                    CompileMode::Fast,
                    DeterminizeLimits::default(),
                );
                let mut compiled_workspace = compiled.prepare_workspace().unwrap();
                let mut restored_workspace = restored.prepare_workspace().unwrap();
                let mut reference_workspace = reference.prepare_workspace().unwrap();

                let long_negative = vec![b'x'; PARTIAL_DFA_MIN_INPUT_BYTES];
                let mut long_positive = long_negative.clone();
                long_positive.extend_from_slice(witness);
                for (label, haystack) in [
                    ("negative", long_negative.as_slice()),
                    ("positive", long_positive.as_slice()),
                ] {
                    let window = SearchWindow::full(haystack);
                    let expected = reference
                        .search_with_workspace(haystack, window, &mut reference_workspace)
                        .unwrap();
                    assert_eq!(
                        compiled
                            .search_with_workspace(haystack, window, &mut compiled_workspace)
                            .unwrap(),
                        expected,
                        "long {label}: {pattern}/{output:?}"
                    );
                    assert_eq!(
                        restored
                            .search_with_workspace(haystack, window, &mut restored_workspace)
                            .unwrap(),
                        expected,
                        "restored long {label}: {pattern}/{output:?}"
                    );
                }

                for haystack in &short_haystacks {
                    for start in 0..=haystack.len() {
                        for end in start..=haystack.len() {
                            let window = SearchWindow::new(start, end);
                            let expected = reference
                                .search_with_workspace(
                                    haystack,
                                    window,
                                    &mut reference_workspace,
                                )
                                .unwrap();
                            assert_eq!(
                                compiled
                                    .search_with_workspace(
                                        haystack,
                                        window,
                                        &mut compiled_workspace,
                                    )
                                    .unwrap(),
                                expected,
                                "short {pattern}/{output:?}/{haystack:?}/{start}..{end}"
                            );
                            assert_eq!(
                                restored
                                    .search_with_workspace(
                                        haystack,
                                        window,
                                        &mut restored_workspace,
                                    )
                                    .unwrap(),
                                expected,
                                "restored short {pattern}/{output:?}/{haystack:?}/{start}..{end}"
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "one generated differential covers first-end promotion, windows, wire reconstruction, and path evidence"
    )]
    fn bit_parallel_exact_width_first_end_completes_endpoint_outputs() {
        // Both columns cover the complete byte alphabet, but the accepted
        // pairs remain correlated. No Cartesian product, mandatory cut, or
        // spelling-specific rule can decide this exact-width language.
        let pattern = r"(?-u:(?:[\x00-\x54][\x55-\xaa]|[\x55-\xaa][\xab-\xff]|[\xab-\xff][\x00-\x54]))";
        let limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let mut generated = generated_byte_strings(&[0, 0x55, 0xab, 0xff], 3);
        generated.extend([
            vec![0, 0x55, 0xab],
            vec![0x55, 0xab, 0],
            vec![0xab, 0, 0x55],
        ]);

        for output in [OutputContract::SelectedEnd, OutputContract::Span] {
            let compiled = program(pattern, output, CompileMode::Optimizing, limits);
            assert_eq!(compiled.exact_match_width(), Some(2), "{output:?}");
            assert!(!compiled.has_nfa_exact_product(), "{output:?}");
            assert!(compiled.nfa_mandatory_cut.is_none(), "{output:?}");
            assert!(compiled.partial_dfa().is_none(), "{output:?}");
            let stats = compiled
                .bit_parallel_exists_stats()
                .unwrap_or_else(|| panic!("missing exact-width endpoint oracle: {output:?}"));
            assert_eq!(stats.words, 1, "{output:?}");
            assert!(compiled.native_bit_parallel_exists_view().is_none());

            let serialized = compiled.serialize().expect("serialize first-end oracle");
            assert_eq!(
                u32::from_le_bytes(serialized[8..12].try_into().unwrap()),
                PROGRAM_FORMAT_VERSION_V7
            );
            assert_ne!(
                serialized[15] & PROGRAM_FLAG_NFA_OPTIMIZING_FALLBACK,
                0
            );
            let restored = CompiledProgram::deserialize(&serialized)
                .expect("rederive first-end oracle from wire graph");
            assert_eq!(restored.serialize().unwrap(), serialized);
            assert_eq!(restored.exact_match_width(), Some(2));
            assert_eq!(restored.bit_parallel_exists_stats(), Some(stats));
            assert!(restored.native_bit_parallel_exists_view().is_none());

            let reference = program(
                pattern,
                output,
                CompileMode::Fast,
                DeterminizeLimits::default(),
            );
            let machine = compiled.bit_parallel_exists().unwrap();
            for haystack in &generated {
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        let expected = reference.search(haystack, window).unwrap();
                        let first_end = machine
                            .search_first_accepting_end(haystack, start, end)
                            .unwrap();
                        let promoted = match first_end {
                            Some(first_end) => compiled
                                .exact_endpoint_result_from_first_accepting_end(
                                    window, first_end, 2,
                                )
                                .unwrap(),
                            None => match output {
                                OutputContract::SelectedEnd => MatchResult::SelectedEnd(None),
                                OutputContract::Span => MatchResult::Span(None),
                                OutputContract::Exists => unreachable!(),
                            },
                        };
                        assert_eq!(
                            promoted, expected,
                            "first-end mismatch: {output:?}/{haystack:?}/{start}..{end}"
                        );
                    }
                }
            }

            let window_start = 5usize;
            let mut haystack = vec![0xff; window_start];
            haystack.extend(std::iter::repeat_n(0x55, PARTIAL_DFA_MIN_INPUT_BYTES));
            haystack.extend_from_slice(&[0, 0x55]);
            let window = SearchWindow::new(window_start, haystack.len());
            let expected = reference.search(&haystack, window).unwrap();

            for candidate in [&compiled, &restored] {
                let mut workspace = candidate.prepare_workspace().unwrap();
                let before = workspace.endpoint_oracle_observation();
                assert_eq!(before, (EndpointOracleBackoff::default(), 0, 0));
                assert_eq!(workspace.endpoint_oracle_boolean_observation(), (0, 0));
                assert_eq!(
                    candidate
                        .search_with_workspace(&haystack, window, &mut workspace)
                        .unwrap(),
                    expected,
                    "direct first-end completion changed {output:?}"
                );
                let after = workspace.endpoint_oracle_observation();
                assert_eq!(
                    after.0, before.0,
                    "exact completion mutated positive-replay backoff: {output:?}"
                );
                assert_eq!(after.1, 1, "missing exact-path evidence: {output:?}");
                assert_eq!(after.2, 0, "whole-window search used a retained hole");
                assert_eq!(
                    workspace.endpoint_oracle_boolean_observation(),
                    (0, 0),
                    "exact whole-window completion used the boolean route: {output:?}"
                );
            }
        }
    }

    #[test]
    fn bit_parallel_zero_width_first_end_uses_nonzero_window_boundary() {
        let limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let haystack = vec![b'x'; PARTIAL_DFA_MIN_INPUT_BYTES + 32];
        let window = SearchWindow::new(7, 7 + PARTIAL_DFA_MIN_INPUT_BYTES);

        for output in [OutputContract::SelectedEnd, OutputContract::Span] {
            let compiled = program(r"a{0}", output, CompileMode::Optimizing, limits);
            assert_eq!(compiled.exact_match_width(), Some(0), "{output:?}");
            let stats = compiled
                .bit_parallel_exists_stats()
                .unwrap_or_else(|| panic!("missing zero-width endpoint oracle: {output:?}"));
            assert_eq!(
                compiled
                    .bit_parallel_exists()
                    .unwrap()
                    .search_first_accepting_end(&haystack, window.start, window.end)
                    .unwrap(),
                Some(window.start)
            );
            let bytes = compiled.serialize().unwrap();
            let restored = CompiledProgram::deserialize(&bytes).unwrap();
            assert_eq!(restored.bit_parallel_exists_stats(), Some(stats));
            let expected = match output {
                OutputContract::SelectedEnd => MatchResult::SelectedEnd(Some(window.start)),
                OutputContract::Span => MatchResult::Span(Some((window.start, window.start))),
                OutputContract::Exists => unreachable!(),
            };
            for candidate in [&compiled, &restored] {
                let mut workspace = candidate.prepare_workspace().unwrap();
                let before = workspace.endpoint_oracle_observation();
                assert_eq!(workspace.endpoint_oracle_boolean_observation(), (0, 0));
                assert_eq!(
                    candidate
                        .search_with_workspace(&haystack, window, &mut workspace)
                        .unwrap(),
                    expected
                );
                let after = workspace.endpoint_oracle_observation();
                assert_eq!(after.0, before.0, "zero-width completion changed backoff");
                assert_eq!(after.1, 1, "zero-width oracle path was not used");
                assert_eq!(workspace.endpoint_oracle_boolean_observation(), (0, 0));
            }
        }
    }

    #[test]
    fn endpoint_oracle_positive_backoff_is_periodic_bounded_and_resettable() {
        let mut state = EndpointOracleBackoff::default();
        assert!(state.should_probe());

        state.observe_positive_replay();
        assert_eq!(state.positive_probe_streak, 1);
        assert_eq!(state.bypass_remaining, 0);
        state.observe_positive_replay();
        assert_eq!(state.positive_probe_streak, 2);
        assert_eq!(state.bypass_remaining, 16);

        for remaining in (0..16).rev() {
            assert!(!state.should_probe());
            state.observe_bypassed_result(&MatchResult::SelectedEnd(Some(1)));
            assert_eq!(state.bypass_remaining, remaining);
        }
        assert!(state.should_probe());
        state.observe_positive_replay();
        assert_eq!(state.bypass_remaining, 32);

        for _ in 0..u8::MAX {
            state.bypass_remaining = 0;
            state.observe_positive_replay();
        }
        assert_eq!(state.positive_probe_streak, u8::MAX);
        assert_eq!(state.bypass_remaining, 1_024);

        state.observe_bypassed_result(&MatchResult::Span(None));
        assert_eq!(state, EndpointOracleBackoff::default());
        state.observe_positive_replay();
        state.observe_negative();
        assert_eq!(state, EndpointOracleBackoff::default());
    }

    #[test]
    fn endpoint_oracle_backoff_avoids_repeated_positive_replay_and_recovers_negative_wins() {
        // Each first-byte and second-byte union covers the complete alphabet,
        // but the accepted pairs remain correlated. There is consequently no
        // selective mandatory cut, suffix, or exact Cartesian product to
        // decide the search ahead of the bounded existence oracle.
        let pattern = r"(?-u:(?:(?:[\x00-\x54][\x55-\xaa]|[\x55-\xaa][\xab-\xff]|[\xab-\xff][\x00-\x54])(?:[\x00-\xff])?))";
        let negative = vec![0_u8; PARTIAL_DFA_MIN_INPUT_BYTES + 64];
        let mut positive = negative.clone();
        positive.extend_from_slice(&[0, 0x55, 0xab]);

        for output in [OutputContract::SelectedEnd, OutputContract::Span] {
            let compiled = program(
                pattern,
                output,
                CompileMode::Optimizing,
                DeterminizeLimits {
                    max_states: 0,
                    ..DeterminizeLimits::default()
                },
            );
            assert!(compiled.bit_parallel_exists_stats().is_some(), "{output:?}");
            assert_eq!(compiled.exact_match_width(), None, "{output:?}");
            assert!(compiled.partial_dfa().is_none(), "{output:?}");
            assert!(compiled.nfa_mandatory_suffix.is_none(), "{output:?}");
            assert!(compiled.nfa_mandatory_cut.is_none(), "{output:?}");
            let reference = program(
                pattern,
                output,
                CompileMode::Fast,
                DeterminizeLimits::default(),
            );
            let mut workspace = compiled.prepare_workspace().unwrap();
            let mut reference_workspace = reference.prepare_workspace().unwrap();

            for expected_streak in [1, 2] {
                assert_eq!(
                    compiled
                        .search_with_workspace(
                            &positive,
                            SearchWindow::full(&positive),
                            &mut workspace,
                        )
                        .unwrap(),
                    reference
                        .search_with_workspace(
                            &positive,
                            SearchWindow::full(&positive),
                            &mut reference_workspace,
                        )
                        .unwrap(),
                    "initial positive replay changed {output:?}"
                );
                assert_eq!(
                    workspace.endpoint_oracle_backoff.positive_probe_streak,
                    expected_streak,
                    "positive probe streak changed for {output:?}"
                );
                assert_eq!(
                    workspace.endpoint_oracle_observation().1,
                    0,
                    "variable-width positive used exact first-end completion: {output:?}"
                );
                assert_eq!(
                    workspace.endpoint_oracle_boolean_observation().0,
                    usize::from(expected_streak),
                    "variable-width whole search did not use the boolean oracle: {output:?}"
                );
            }
            assert_eq!(workspace.endpoint_oracle_backoff.bypass_remaining, 16);

            for remaining in (0..16).rev() {
                assert_eq!(
                    compiled
                        .search_with_workspace(
                            &positive,
                            SearchWindow::full(&positive),
                            &mut workspace,
                        )
                        .unwrap(),
                    reference
                        .search_with_workspace(
                            &positive,
                            SearchWindow::full(&positive),
                            &mut reference_workspace,
                        )
                        .unwrap(),
                    "bypassed positive replay changed {output:?}"
                );
                assert_eq!(
                    workspace.endpoint_oracle_backoff.bypass_remaining,
                    remaining,
                    "positive bypass countdown changed for {output:?}"
                );
            }
            assert_eq!(workspace.endpoint_oracle_backoff.positive_probe_streak, 2);
            assert_eq!(workspace.endpoint_oracle_boolean_observation().0, 2);

            compiled
                .search_with_workspace(
                    &positive,
                    SearchWindow::full(&positive),
                    &mut workspace,
                )
                .unwrap();
            assert_eq!(workspace.endpoint_oracle_backoff.positive_probe_streak, 3);
            assert_eq!(workspace.endpoint_oracle_backoff.bypass_remaining, 32);
            assert_eq!(workspace.endpoint_oracle_boolean_observation().0, 3);

            assert_eq!(
                compiled
                    .search_with_workspace(
                        &negative,
                        SearchWindow::full(&negative),
                        &mut workspace,
                    )
                    .unwrap(),
                reference
                    .search_with_workspace(
                        &negative,
                        SearchWindow::full(&negative),
                        &mut reference_workspace,
                    )
                    .unwrap(),
                "bypassed negative changed {output:?}"
            );
            assert_eq!(
                workspace.endpoint_oracle_backoff,
                EndpointOracleBackoff::default(),
                "a bypassed negative did not re-enable the oracle for {output:?}"
            );
            assert_eq!(
                compiled
                    .search_with_workspace(
                        &negative,
                        SearchWindow::full(&negative),
                        &mut workspace,
                    )
                    .unwrap(),
                reference
                    .search_with_workspace(
                        &negative,
                        SearchWindow::full(&negative),
                        &mut reference_workspace,
                    )
                    .unwrap(),
                "re-enabled negative oracle changed {output:?}"
            );
            assert_eq!(
                workspace.endpoint_oracle_backoff,
                EndpointOracleBackoff::default(),
                "a proved negative changed backoff for {output:?}"
            );
        }
    }

    #[test]
    fn endpoint_oracle_runtime_bypass_does_not_repeat_the_portable_probe() {
        let pattern = r"(?:[\x00-\x54][\x55-\xaa]|[\x55-\xaa][\xab-\xff]|[\xab-\xff][\x00-\x54])";
        let mut positive = vec![0_u8; PARTIAL_DFA_MIN_INPUT_BYTES + 64];
        positive.extend_from_slice(&[0, 0x55]);

        for output in [OutputContract::SelectedEnd, OutputContract::Span] {
            let compiled = program(
                pattern,
                output,
                CompileMode::Optimizing,
                DeterminizeLimits {
                    max_states: 0,
                    ..DeterminizeLimits::default()
                },
            );
            assert!(compiled.bit_parallel_exists_stats().is_some(), "{output:?}");
            assert!(compiled.partial_dfa().is_none(), "{output:?}");
            let reference = program(
                pattern,
                output,
                CompileMode::Fast,
                DeterminizeLimits::default(),
            );
            let window = SearchWindow::full(&positive);
            let expected = reference.search(&positive, window).unwrap();

            let mut bypass_workspace = compiled.prepare_workspace().unwrap();
            assert_eq!(
                compiled
                    .search_without_endpoint_oracle_with_workspace(
                        &positive,
                        window,
                        &mut bypass_workspace,
                    )
                    .unwrap(),
                expected,
            );
            assert_eq!(
                bypass_workspace.endpoint_oracle_backoff,
                EndpointOracleBackoff::default(),
                "the runtime replay boundary re-entered the portable endpoint oracle for {output:?}",
            );

            let mut ordinary_workspace = compiled.prepare_workspace().unwrap();
            assert_eq!(
                compiled
                    .search_with_workspace(&positive, window, &mut ordinary_workspace)
                    .unwrap(),
                expected,
            );
            assert_eq!(
                ordinary_workspace
                    .endpoint_oracle_backoff
                    .positive_probe_streak,
                1,
                "the control search did not observe its positive portable probe for {output:?}",
            );
        }
    }

    fn assert_exact_product_matches_fast_for_every_window(
        pattern: &str,
        alphabet: &[u8],
        max_len: usize,
        expected_primary_offset: Option<u8>,
    ) {
        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let haystacks = generated_byte_strings(alphabet, max_len);
        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let accelerated = program(pattern, output, CompileMode::Optimizing, fallback_limits);
            let product = accelerated
                .nfa_mandatory_cut
                .as_ref()
                .and_then(NfaMandatoryCut::exact_product)
                .unwrap_or_else(|| panic!("expected exact product for {pattern}/{output:?}"));
            if let Some(expected) = expected_primary_offset {
                assert_eq!(product.primary_offset, expected, "{pattern}/{output:?}");
            }
            let serialized = accelerated.serialize().expect("serialize exact product");
            let epsilon_flag = if accelerated.automaton.has_epsilon_closure_dispatch() {
                PROGRAM_FLAG_NFA_EPSILON_CLOSURE_DISPATCH
            } else {
                0
            };
            assert_eq!(
                serialized[15],
                PROGRAM_FLAG_NFA_EXACT_PRODUCT | epsilon_flag
            );
            let restored = CompiledProgram::deserialize(&serialized)
                .expect("deserialize frontier exact product");
            assert_eq!(restored.serialize().unwrap(), serialized);
            assert!(
                restored
                    .nfa_mandatory_cut
                    .as_ref()
                    .and_then(NfaMandatoryCut::exact_product)
                    .is_some()
            );
            let reference = program(
                pattern,
                output,
                CompileMode::Fast,
                DeterminizeLimits::default(),
            );
            let mut accelerated_workspace = accelerated.prepare_workspace().unwrap();
            let mut restored_workspace = restored.prepare_workspace().unwrap();
            let mut reference_workspace = reference.prepare_workspace().unwrap();
            assert!(accelerated_workspace.nfa.is_none());
            assert!(restored_workspace.nfa.is_none());
            for haystack in &haystacks {
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        let expected = reference
                            .search_with_workspace(haystack, window, &mut reference_workspace)
                            .unwrap();
                        assert_eq!(
                            accelerated
                                .search_with_workspace(
                                    haystack,
                                    window,
                                    &mut accelerated_workspace,
                                )
                                .unwrap(),
                            expected,
                            "fresh {pattern}/{output:?}/{haystack:?}/{start}..{end}"
                        );
                        assert_eq!(
                            restored
                                .search_with_workspace(haystack, window, &mut restored_workspace)
                                .unwrap(),
                            expected,
                            "wire {pattern}/{output:?}/{haystack:?}/{start}..{end}"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn resource_fallback_exact_product_is_graph_proved_complete_and_round_trips() {
        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let haystacks = generated_byte_strings(b"aZ012x", 4);
        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let accelerated = program("a[0-2]Z", output, CompileMode::Optimizing, fallback_limits);
            assert!(
                accelerated
                    .nfa_mandatory_cut
                    .as_ref()
                    .and_then(NfaMandatoryCut::exact_product)
                    .is_some()
            );
            assert!(accelerated.nfa_mandatory_suffix.is_none());
            assert!(accelerated.native_dynamic_rows_view().is_none());
            let serialized = accelerated
                .serialize()
                .expect("serialize exact-product sidecar");
            assert_eq!(serialized[15], PROGRAM_FLAG_NFA_EXACT_PRODUCT);
            let mut contradictory = serialized.clone();
            contradictory[15] |= PROGRAM_FLAG_NFA_PARTIAL_DFA;
            assert!(CompiledProgram::deserialize(&contradictory).is_err());
            let mut legacy_v3 = serialized.clone();
            legacy_v3[8..12].copy_from_slice(&PROGRAM_FORMAT_VERSION_V3.to_le_bytes());
            assert!(CompiledProgram::deserialize(&legacy_v3).is_ok());
            let restored =
                CompiledProgram::deserialize(&serialized).expect("restore exact-product sidecar");
            assert!(
                restored
                    .nfa_mandatory_cut
                    .as_ref()
                    .and_then(NfaMandatoryCut::exact_product)
                    .is_some()
            );
            assert!(restored.native_dynamic_rows_view().is_none());

            let reference = program(
                "a[0-2]Z",
                output,
                CompileMode::Fast,
                DeterminizeLimits::default(),
            );
            assert!(
                reference
                    .nfa_mandatory_cut
                    .as_ref()
                    .and_then(NfaMandatoryCut::exact_product)
                    .is_none()
            );
            let mut accelerated_workspace = accelerated.prepare_workspace().unwrap();
            assert!(accelerated_workspace.nfa.is_none());
            assert!(accelerated_workspace.dynamic_native_rows.is_none());
            let mut restored_workspace = restored.prepare_workspace().unwrap();
            assert!(restored_workspace.nfa.is_none());
            assert!(restored_workspace.dynamic_native_rows.is_none());
            let mut reference_workspace = reference.prepare_workspace().unwrap();
            for haystack in &haystacks {
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        let expected = reference
                            .search_with_workspace(haystack, window, &mut reference_workspace)
                            .unwrap();
                        assert_eq!(
                            accelerated
                                .search_with_workspace(
                                    haystack,
                                    window,
                                    &mut accelerated_workspace,
                                )
                                .unwrap(),
                            expected,
                            "accelerated {output:?}/{haystack:?}/{start}..{end}"
                        );
                        assert_eq!(
                            restored
                                .search_with_workspace(haystack, window, &mut restored_workspace)
                                .unwrap(),
                            expected,
                            "restored {output:?}/{haystack:?}/{start}..{end}"
                        );
                    }
                }
            }
        }

        // Exercise selective columns after the first byte. Candidate starts
        // must remain ordered and window-relative when the primary hit is
        // translated back by a nonzero offset.
        for (pattern, alphabet, max_len, primary_offset) in [
            ("[ab]x", b"abxy".as_slice(), 3, 1_u8),
            ("[ab][01]Z", b"ab01Zx".as_slice(), 3, 2_u8),
        ] {
            let haystacks = generated_byte_strings(alphabet, max_len);
            for output in [
                OutputContract::Exists,
                OutputContract::SelectedEnd,
                OutputContract::Span,
            ] {
                let accelerated =
                    program(pattern, output, CompileMode::Optimizing, fallback_limits);
                assert_eq!(
                    accelerated
                        .nfa_mandatory_cut
                        .as_ref()
                        .and_then(NfaMandatoryCut::exact_product)
                        .expect("nonzero-offset exact product")
                        .primary_offset,
                    primary_offset
                );
                let reference = program(
                    pattern,
                    output,
                    CompileMode::Fast,
                    DeterminizeLimits::default(),
                );
                let mut accelerated_workspace = accelerated.prepare_workspace().unwrap();
                let mut reference_workspace = reference.prepare_workspace().unwrap();
                for haystack in &haystacks {
                    for start in 0..=haystack.len() {
                        for end in start..=haystack.len() {
                            let window = SearchWindow::new(start, end);
                            assert_eq!(
                                accelerated
                                    .search_with_workspace(
                                        haystack,
                                        window,
                                        &mut accelerated_workspace,
                                    )
                                    .unwrap(),
                                reference
                                    .search_with_workspace(
                                        haystack,
                                        window,
                                        &mut reference_workspace,
                                    )
                                    .unwrap(),
                                "{pattern}/{output:?}/{haystack:?}/{start}..{end}"
                            );
                        }
                    }
                }
            }
        }

        for (pattern, eligible) in [
            ("a", true),
            ("abcdefghijklmnop", true),
            ("abcdefghijklmnopq", false),
            (r"(?-u:[\x00-\xFF])", false),
        ] {
            let compiled = program(
                pattern,
                OutputContract::Span,
                CompileMode::Optimizing,
                fallback_limits,
            );
            assert_eq!(
                compiled
                    .nfa_mandatory_cut
                    .as_ref()
                    .and_then(NfaMandatoryCut::exact_product)
                    .is_some(),
                eligible,
                "{pattern}"
            );
        }

        let correlated = program(
            "(?:ab|cd)",
            OutputContract::Span,
            CompileMode::Optimizing,
            fallback_limits,
        );
        assert!(
            correlated
                .nfa_mandatory_cut
                .as_ref()
                .and_then(NfaMandatoryCut::exact_product)
                .is_none()
        );
        let variable = program(
            "a[0-2]+Z",
            OutputContract::Span,
            CompileMode::Optimizing,
            fallback_limits,
        );
        assert!(
            variable
                .nfa_mandatory_cut
                .as_ref()
                .and_then(NfaMandatoryCut::exact_product)
                .is_none()
        );
    }

    #[test]
    fn frontier_exact_products_admit_equivalent_branches_and_preserve_every_contract() {
        for (pattern, alphabet, maximum, primary_offset) in [
            ("(?:ab|cb)", b"abcx".as_slice(), 4, Some(1_u8)),
            ("(?:ab|ac)", b"abcx".as_slice(), 4, Some(0_u8)),
            ("(?:ab|cb)(?:d|e)", b"abcde".as_slice(), 4, Some(1_u8)),
            ("[ab]x", b"abxy".as_slice(), 3, Some(1_u8)),
            ("[ab][01]Z", b"ab01Zx".as_slice(), 3, Some(2_u8)),
            ("[a-h][0-9]", b"ah09x".as_slice(), 3, Some(0_u8)),
            ("[a-z][0-9A-F]", b"az09AFx".as_slice(), 3, Some(1_u8)),
            (
                r"(?-u:[\x00-\xFE])",
                b"\x00\x01\xfe\xff".as_slice(),
                2,
                Some(0_u8),
            ),
        ] {
            assert_exact_product_matches_fast_for_every_window(
                pattern,
                alphabet,
                maximum,
                primary_offset,
            );
        }

        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        for pattern in ["(?:ab|cd)", "a|ab", "a[0-2]+Z"] {
            let compiled = program(
                pattern,
                OutputContract::Span,
                CompileMode::Optimizing,
                fallback_limits,
            );
            assert!(
                compiled
                    .nfa_mandatory_cut
                    .as_ref()
                    .and_then(NfaMandatoryCut::exact_product)
                    .is_none(),
                "correlated, early-accepting, or variable graph must decline: {pattern}"
            );
        }
    }

    #[test]
    fn exact_product_primary_scanner_matches_scalar_for_every_selective_cardinality() {
        let source = (0usize..384)
            .map(|index| u8::try_from((index * 73 + 19) & 255).unwrap())
            .collect::<Vec<_>>();
        for cardinality in 4usize..=255 {
            let mut words = [0_u64; 4];
            for ordinal in 0..cardinality {
                let byte = u8::try_from((ordinal * 197 + cardinality * 29) & 255).unwrap();
                words[usize::from(byte) / 64] |= 1_u64 << (usize::from(byte) % 64);
            }
            let set = ByteSet256::from_words(words);
            let scanner = NfaMandatoryCutScanner::Full {
                set,
                classifier: ByteSetClassifier::new(set),
            };
            for start in 0..32 {
                for length in 0..=64 {
                    let bytes = &source[start..start + length];
                    assert_eq!(
                        scanner.find_exact_product_primary(bytes),
                        bytes.iter().position(|&byte| set.contains(byte)),
                        "cardinality={cardinality}, start={start}, length={length}"
                    );
                }
            }
        }
    }

    #[test]
    fn exact_product_full_scanner_batches_dense_candidates_across_block_boundaries() {
        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let mut cardinality_four = vec![b'a'; 96];
        let mut cardinality_255 = vec![1_u8; 96];
        for offset in [15usize, 32, 63, 88] {
            cardinality_four[offset.saturating_sub(3)..offset].fill(b'z');
            cardinality_four[offset..offset + 4].copy_from_slice(b"aeim");
            cardinality_255[offset.saturating_sub(3)..offset].fill(u8::MAX);
            cardinality_255[offset..offset + 4].fill(0);
        }
        for (pattern, haystack) in [
            ("[a-d][e-h][i-l][m-p]", cardinality_four.as_slice()),
            (
                r"(?-u:[\x00-\xFE][^\x01][^\x02][^\x03])",
                cardinality_255.as_slice(),
            ),
        ] {
            for output in [
                OutputContract::Exists,
                OutputContract::SelectedEnd,
                OutputContract::Span,
            ] {
                let accelerated =
                    program(pattern, output, CompileMode::Optimizing, fallback_limits);
                assert!(matches!(
                    accelerated
                        .nfa_mandatory_cut
                        .as_ref()
                        .expect("dense exact product")
                        .scanner,
                    NfaMandatoryCutScanner::Full { .. }
                ));
                let reference = program(
                    pattern,
                    output,
                    CompileMode::Fast,
                    DeterminizeLimits::default(),
                );
                let mut accelerated_workspace = accelerated.prepare_workspace().unwrap();
                let mut reference_workspace = reference.prepare_workspace().unwrap();
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        assert_eq!(
                            accelerated
                                .search_with_workspace(
                                    haystack,
                                    window,
                                    &mut accelerated_workspace,
                                )
                                .unwrap(),
                            reference
                                .search_with_workspace(
                                    haystack,
                                    window,
                                    &mut reference_workspace,
                                )
                                .unwrap(),
                            "{pattern}/{output:?}/{start}..{end}"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn exact_product_admits_every_structurally_selective_primary_cardinality() {
        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let one_column_graph = |end: u8| RawPlan {
            start: 0,
            roles: vec![StateRole::Consume, StateRole::Accept],
            edge_offsets: vec![0, 1, 1],
            edge_targets: vec![1],
            edge_kinds: vec![EdgeKind::ByteRange],
            byte_starts: vec![0],
            byte_ends: vec![end],
        };

        for cardinality in 1usize..=255 {
            let end = u8::try_from(cardinality - 1).unwrap();
            let compiled = raw_program(
                &one_column_graph(end),
                OutputContract::Span,
                CompileMode::Optimizing,
                fallback_limits,
            );
            let accelerator = compiled
                .nfa_mandatory_cut
                .as_ref()
                .unwrap_or_else(|| panic!("selective cardinality {cardinality} was declined"));
            let product = accelerator
                .exact_product()
                .unwrap_or_else(|| panic!("selective cardinality {cardinality} was declined"));
            assert_eq!(product.primary_offset, 0);
            assert_eq!(product.width, 1);
            match &accelerator.scanner {
                NfaMandatoryCutScanner::Small { count, .. } => {
                    assert!(cardinality <= 3);
                    assert_eq!(usize::from(*count), cardinality);
                }
                NfaMandatoryCutScanner::Full { set, classifier } => {
                    assert!(cardinality > 3);
                    assert_eq!(classifier.set(), *set);
                    assert_eq!(
                        set.words().iter().map(|word| word.count_ones()).sum::<u32>(),
                        u32::try_from(cardinality).unwrap()
                    );
                }
                NfaMandatoryCutScanner::Ascii { .. } => {
                    panic!("exact products use the full-byte classifier for larger sets")
                }
            }
        }

        let unselective = raw_program(
            &one_column_graph(u8::MAX),
            OutputContract::Span,
            CompileMode::Optimizing,
            fallback_limits,
        );
        assert!(
            unselective
                .nfa_mandatory_cut
                .as_ref()
                .and_then(NfaMandatoryCut::exact_product)
                .is_none()
        );
    }

    #[test]
    fn frontier_exact_product_proof_resource_ceilings_are_exact_and_transactional() {
        let compiled = program(
            "(?:ab|cb)",
            OutputContract::Span,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        assert_eq!(compiled.exact_match_width, Some(2));
        let sets = compiled.anchored_prefix.sets();
        let stats =
            nfa_prefix_exact_product_proof(&compiled.raw, sets, NfaExactProductLimits::default())
                .expect("equivalent duplicated branches form a complete product");
        assert!(stats.state_work > 0);
        assert!(stats.edge_work > 0);
        assert!(stats.byte_work > 0);
        assert!(stats.frontier_work > 0);
        assert!(stats.frontiers > 1);
        assert!(stats.memory_bytes > 0);

        let exact = NfaExactProductLimits {
            max_state_work: stats.state_work,
            max_edge_work: stats.edge_work,
            max_byte_work: stats.byte_work,
            max_frontier_work: stats.frontier_work,
            max_frontiers: stats.frontiers,
            max_memory_bytes: stats.memory_bytes,
        };
        assert_eq!(
            nfa_prefix_exact_product_proof(&compiled.raw, sets, exact),
            Some(stats),
            "every exact ceiling must admit the identical receipt"
        );

        let one_below_state = NfaExactProductLimits {
            max_state_work: stats.state_work - 1,
            ..exact
        };
        let one_below_edge = NfaExactProductLimits {
            max_edge_work: stats.edge_work - 1,
            ..exact
        };
        let one_below_byte = NfaExactProductLimits {
            max_byte_work: stats.byte_work - 1,
            ..exact
        };
        let one_below_frontier_work = NfaExactProductLimits {
            max_frontier_work: stats.frontier_work - 1,
            ..exact
        };
        let one_below_frontiers = NfaExactProductLimits {
            max_frontiers: stats.frontiers - 1,
            ..exact
        };
        let one_below_memory = NfaExactProductLimits {
            max_memory_bytes: stats.memory_bytes - 1,
            ..exact
        };
        for (name, limits) in [
            ("state work", one_below_state),
            ("edge work", one_below_edge),
            ("byte work", one_below_byte),
            ("frontier work", one_below_frontier_work),
            ("frontiers", one_below_frontiers),
            ("memory", one_below_memory),
        ] {
            assert_eq!(
                nfa_prefix_exact_product_proof(&compiled.raw, sets, limits),
                None,
                "one-below {name} must decline without a partial proof"
            );
        }
    }

