    #[test]
    fn generated_accepting_paths_never_escape_the_anchored_prefix_sets() {
        let patterns = [
            "abcd",
            "ab|ac",
            "a?bc",
            "a+b",
            "ab(?:|c)d",
            "(?:ab|a)c",
            "a{2,4}b",
            "(?:ab|cd){1,3}d",
            r"\Aab\z",
            r"(?m:^ab$)",
            r"(?-u:\bab\b)",
            r"\bab\b",
        ];
        let alphabet = [b'a', b'b', b'c', b'd', b'X'];
        let mut haystacks = vec![Vec::new()];
        let mut frontier = vec![Vec::new()];
        for _ in 0..5 {
            let mut next = Vec::new();
            for prefix in &frontier {
                for &byte in &alphabet {
                    let mut haystack = prefix.clone();
                    haystack.push(byte);
                    next.push(haystack.clone());
                    haystacks.push(haystack);
                }
            }
            frontier = next;
        }

        for pattern in patterns {
            let compiled = program(
                pattern,
                OutputContract::Span,
                CompileMode::Optimizing,
                DeterminizeLimits::default(),
            );
            for haystack in &haystacks {
                let MatchResult::Span(found) = compiled
                    .search(haystack, SearchWindow::full(haystack))
                    .unwrap()
                else {
                    panic!("span contract changed");
                };
                let Some((0, end)) = found else {
                    continue;
                };
                assert!(
                    compiled.anchored_prefix.sets().len() <= end,
                    "{pattern:?} {haystack:?}"
                );
                for (position, set) in compiled.anchored_prefix.sets().iter().enumerate() {
                    assert!(
                        set.contains(haystack[position]),
                        "{pattern:?} {haystack:?} at {position}"
                    );
                }
            }
        }
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "suffix membership, width bounds, NFA differential, and every search window form one exhaustive proof"
    )]
    fn generated_matches_obey_suffix_sets_and_maximum_width_for_every_window() {
        let patterns = [
            "",
            "ab",
            "a|bc",
            "a?bc",
            "a{2,3}b",
            "(?:ab|c){1,2}",
            "a*",
            r"\Aab\z",
            r"(?m:^ab$)",
            r"(?mR:^ab$)",
            r"(?-u:\bab\b)",
            r"\bab\b",
        ];
        let alphabet = [b'a', b'b', b'c', b'X', b'-', b'\r', b'\n'];
        let mut haystacks = vec![Vec::new()];
        let mut frontier = vec![Vec::new()];
        for _ in 0..3 {
            let mut next = Vec::new();
            for prefix in &frontier {
                for &byte in &alphabet {
                    let mut haystack = prefix.clone();
                    haystack.push(byte);
                    next.push(haystack.clone());
                    haystacks.push(haystack);
                }
            }
            frontier = next;
        }

        for pattern in patterns {
            let compiled = program(
                pattern,
                OutputContract::Span,
                CompileMode::Optimizing,
                DeterminizeLimits::default(),
            );
            let reference = program(
                pattern,
                OutputContract::Span,
                CompileMode::Fast,
                DeterminizeLimits::default(),
            );
            let suffix = compiled.anchored_suffix.sets();
            let maximum = compiled.max_match_width();
            for haystack in &haystacks {
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        let actual = compiled.search(haystack, window).unwrap();
                        let expected = reference.search(haystack, window).unwrap();
                        assert_eq!(
                            actual, expected,
                            "differential {pattern:?}/{haystack:?}/{start}..{end}"
                        );
                        let MatchResult::Span(found) = actual else {
                            panic!("span contract changed");
                        };
                        let Some((match_start, match_end)) = found else {
                            continue;
                        };
                        let width = match_end.checked_sub(match_start).expect("ordered span");
                        if let Some(maximum) = maximum {
                            assert!(
                                width <= maximum,
                                "maximum {pattern:?}/{haystack:?}/{start}..{end}: {width}>{maximum}"
                            );
                        }
                        assert!(
                            suffix.len() <= width,
                            "suffix depth {pattern:?}/{haystack:?}/{start}..{end}"
                        );
                        for (depth, set) in suffix.iter().enumerate() {
                            let position = match_end
                                .checked_sub(depth.saturating_add(1))
                                .expect("proved suffix byte");
                            assert!(
                                set.contains(haystack[position]),
                                "suffix {pattern:?}/{haystack:?}/{start}..{end} at reverse depth {depth}"
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn all_contracts_and_windows_agree_with_universal_nfa() {
        let patterns = [
            "",
            "a",
            "a|ab",
            "ab|a",
            "a*",
            "a*?",
            "(?:ab|ba){1,3}",
            "[^x]+x",
        ];
        let haystacks: &[&[u8]] = &[b"", b"a", b"zab", b"baaa", b"xxabax", b"nomatch"];
        for pattern in patterns {
            for output in [
                OutputContract::Exists,
                OutputContract::SelectedEnd,
                OutputContract::Span,
            ] {
                let dfa = program(
                    pattern,
                    output,
                    CompileMode::Optimizing,
                    DeterminizeLimits::default(),
                );
                let nfa = program(
                    pattern,
                    output,
                    CompileMode::Fast,
                    DeterminizeLimits::default(),
                );
                for &haystack in haystacks {
                    for start in 0..=haystack.len() {
                        for end in start..=haystack.len() {
                            let window = SearchWindow::new(start, end);
                            assert_eq!(
                                dfa.search(haystack, window).unwrap(),
                                nfa.search(haystack, window).unwrap(),
                                "{pattern:?} {output:?} {haystack:?} {start}..{end}"
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn assertions_use_context_dfa_while_ordinary_limits_fall_back_to_general_nfa() {
        let asserted = program(
            "(?m:^a)",
            OutputContract::Span,
            CompileMode::Optimizing,
            DeterminizeLimits::default(),
        );
        assert_eq!(asserted.engine_kind(), EngineKind::OrderedContextDfa);
        assert_eq!(
            asserted.engine_selection_reason(),
            Some(EngineSelectionReason::CompleteContextDfa)
        );
        assert!(asserted.context_dfa_stats().is_some());
        let contextual = asserted
            .context_determinization_report()
            .expect("fresh contextual receipt");
        assert_eq!(contextual.stats, asserted.context_dfa_stats());
        assert_eq!(contextual.decline, None);
        assert_eq!(
            asserted.search(b"\na", SearchWindow::new(1, 2)).unwrap(),
            MatchResult::Span(Some((1, 2)))
        );

        let limited = program(
            "(?:ab|ac|ad)+z",
            OutputContract::Span,
            CompileMode::Optimizing,
            DeterminizeLimits {
                max_states: 0,
                ..DeterminizeLimits::default()
            },
        );
        assert_eq!(limited.engine_kind(), EngineKind::OrderedNfa);
        assert_eq!(
            limited
                .search(b"xxabacadz", SearchWindow::full(b"xxabacadz"))
                .unwrap(),
            MatchResult::Span(Some((2, 9)))
        );
    }

    #[test]
    fn ordered_nfa_contextual_span_reuses_one_prepared_workspace() {
        let compiled = program(
            "(?m:(?:^a|x+)(?:b|c+|))",
            OutputContract::Span,
            CompileMode::Optimizing,
            DeterminizeLimits {
                max_states: 0,
                ..DeterminizeLimits::default()
            },
        );
        assert_eq!(compiled.engine_kind(), EngineKind::OrderedNfa);
        assert_eq!(
            compiled.engine_selection_reason(),
            Some(EngineSelectionReason::ContextAssertions),
        );
        assert!(compiled.exact_match_width.is_none());

        let mut source = vec![b'!'; 4_096];
        source[..4].copy_from_slice(b"accc");
        let window = SearchWindow::full(&source);
        let expected = MatchResult::Span(Some((0, 4)));
        let mut workspace = compiled.prepare_workspace().expect("prepare NFA workspace");
        for attempt in 0..4 {
            assert_eq!(
                compiled
                    .search_with_workspace(&source, window, &mut workspace)
                    .unwrap(),
                expected,
                "prepared contextual Span attempt {attempt}",
            );
        }
    }

    #[test]
    fn resource_fallback_mandatory_suffix_is_structural_and_round_trips() {
        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let compiled = program(
                "(?:a|bb)q[xz]",
                output,
                CompileMode::Optimizing,
                fallback_limits,
            );
            assert_eq!(compiled.engine_kind(), EngineKind::OrderedNfa);
            assert_eq!(
                compiled.engine_selection_reason(),
                Some(EngineSelectionReason::DeterminizationResourceLimit)
            );
            let accelerator = compiled
                .nfa_mandatory_suffix
                .as_ref()
                .expect("finite selective suffix should construct the sidecar");
            assert_eq!(accelerator.primary_depth, 1);
            assert_eq!(accelerator.primary_bytes[0], b'q');
            assert_eq!(accelerator.maximum_width, Some(4));

            let bytes = compiled.serialize().expect("serialize fallback");
            assert_eq!(
                u32::from_le_bytes(bytes[8..12].try_into().unwrap()),
                PROGRAM_FORMAT_VERSION_V7
            );
            assert!(compiled.automaton.has_epsilon_closure_dispatch());
            assert_eq!(
                bytes[15],
                PROGRAM_FLAG_NFA_MANDATORY_SUFFIX
                    | PROGRAM_FLAG_NFA_EPSILON_CLOSURE_DISPATCH
                    | PROGRAM_FLAG_NFA_OPTIMIZING_FALLBACK
            );
            let restored = CompiledProgram::deserialize(&bytes).expect("restore fallback");
            assert_eq!(restored.engine_kind(), EngineKind::OrderedNfa);
            assert!(restored.nfa_mandatory_suffix.is_some());
            assert_eq!(
                restored.bit_parallel_exists_stats(),
                compiled.bit_parallel_exists_stats()
            );
            assert_eq!(restored.serialize().unwrap(), bytes);

            let fast = program(
                "(?:a|bb)q[xz]",
                output,
                CompileMode::Fast,
                DeterminizeLimits::default(),
            );
            assert_eq!(fast.engine_kind(), EngineKind::OrderedNfa);
            assert!(fast.nfa_mandatory_suffix.is_none());
            let fast_bytes = fast.serialize().expect("serialize fast fallback");
            assert_eq!(fast_bytes[15], 0);
            let restored_fast =
                CompiledProgram::deserialize(&fast_bytes).expect("restore fast fallback");
            assert!(restored_fast.nfa_mandatory_suffix.is_none());
            assert_eq!(restored_fast.serialize().unwrap(), fast_bytes);
        }

        let ineligible = [
            ("", CompileMode::Fast),
            ("a*z", CompileMode::Fast),
            (".{1,64}z", CompileMode::Fast),
            ("[a-z]{1,2}", CompileMode::Fast),
            ("ab", CompileMode::Fast),
            (r"a\bz", CompileMode::Fast),
        ];
        for (pattern, mode) in ineligible {
            let compiled = program(
                pattern,
                OutputContract::Span,
                mode,
                DeterminizeLimits::default(),
            );
            assert_eq!(
                compiled.engine_kind(),
                EngineKind::OrderedNfa,
                "{pattern:?}"
            );
            assert!(
                compiled.nfa_mandatory_suffix.is_none(),
                "ineligible graph unexpectedly admitted: {pattern:?}"
            );
        }

        let dense = program(
            "[^z]{1,7}z",
            OutputContract::Span,
            CompileMode::Optimizing,
            fallback_limits,
        );
        let accelerator = dense.nfa_mandatory_suffix.as_ref().unwrap();
        let haystack = vec![b'z'; 64];
        let mut primary_hits = 0;
        assert_eq!(
            accelerator.next_candidate_endpoint(
                &dense.anchored_suffix,
                &haystack,
                0,
                haystack.len(),
                usize::from(accelerator.minimum_width),
                &mut primary_hits,
            ),
            NfaMandatorySuffixScan::Fallback
        );
        assert!(primary_hits > NFA_SUFFIX_PRIMARY_HIT_CREDIT);
        let mut reference = dense.clone();
        reference.nfa_mandatory_suffix = None;
        assert_eq!(
            dense
                .search(&haystack, SearchWindow::full(&haystack))
                .unwrap(),
            reference
                .search(&haystack, SearchWindow::full(&haystack))
                .unwrap()
        );
    }

    #[test]
    fn bounded_mandatory_suffix_exists_stops_after_first_reverse_event() {
        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let compiled = program(
            "[a-y]{1,63}z",
            OutputContract::Exists,
            CompileMode::Optimizing,
            fallback_limits,
        );
        let accelerator = compiled
            .nfa_mandatory_suffix
            .as_ref()
            .expect("bounded selective suffix should construct the sidecar");
        assert_eq!(accelerator.maximum_width, Some(64));

        let mut haystack = vec![b'x'; 63];
        haystack.push(b'z');
        let mut exists_trace = accelerator
            .reverse
            .trace(&haystack, 0, haystack.len())
            .expect("long bounded reverse trace");
        assert_eq!(
            mandatory_suffix_reverse_start(OutputContract::Exists, &mut exists_trace),
            Some(62)
        );
        assert_eq!(
            exists_trace.next(),
            Some(61),
            "Exists must leave later exact reverse events unconsumed"
        );

        for output in [OutputContract::SelectedEnd, OutputContract::Span] {
            let mut trace = accelerator
                .reverse
                .trace(&haystack, 0, haystack.len())
                .expect("endpoint-sensitive reverse trace");
            assert_eq!(
                mandatory_suffix_reverse_start(output, &mut trace),
                Some(0),
                "{output:?} must retain earliest-start selection"
            );
            assert_eq!(
                trace.next(),
                None,
                "{output:?} must exhaust the reverse trace"
            );
        }

        // Stopping one trace cannot mutate the immutable seeded-reverse table
        // or any terminal fact used by a later trace.
        let mut repeated = accelerator
            .reverse
            .trace(&haystack, 0, haystack.len())
            .expect("repeated reverse trace");
        assert_eq!(
            mandatory_suffix_reverse_start(OutputContract::Exists, &mut repeated),
            Some(62)
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the terminal-barrier theorem is checked across graph shapes, contracts, windows, and wire reconstruction"
    )]
    fn unbounded_terminal_suffix_barrier_replays_from_the_proved_start() {
        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let cases: &[(&str, &[u8])] = &[
            ("(?:a|b)+Q", b"abQx"),
            ("(?:ab)?(?:a|b)*Q", b"abQx"),
            ("(?:ab|x)+?Q", b"abxQ"),
            ("(?:a|b|c)+(?:Q|Z)", b"abcQZ"),
        ];

        for &(pattern, alphabet) in cases {
            let haystacks = generated_byte_strings(alphabet, 3);
            for output in [
                OutputContract::Exists,
                OutputContract::SelectedEnd,
                OutputContract::Span,
            ] {
                let accelerated =
                    program(pattern, output, CompileMode::Optimizing, fallback_limits);
                let suffix = accelerated
                    .nfa_mandatory_suffix
                    .as_ref()
                    .unwrap_or_else(|| panic!("missing suffix sidecar for {pattern:?}"));
                assert_eq!(suffix.maximum_width, None, "{pattern:?}");
                assert_eq!(suffix.primary_depth, 0, "{pattern:?}");
                assert!(suffix.terminal_barrier, "{pattern:?}");

                let restored = CompiledProgram::deserialize(
                    &accelerated.serialize().expect("serialize barrier program"),
                )
                .expect("restore barrier program");
                assert!(
                    restored
                        .nfa_mandatory_suffix
                        .as_ref()
                        .is_some_and(|suffix| suffix.terminal_barrier),
                    "restored {pattern:?}"
                );

                let mut ordinary = accelerated.clone();
                ordinary.nfa_mandatory_suffix = None;
                for haystack in &haystacks {
                    for start in 0..=haystack.len() {
                        for end in start..=haystack.len() {
                            let window = SearchWindow::new(start, end);
                            let expected = ordinary.search(haystack, window).unwrap();
                            assert_eq!(
                                accelerated.search(haystack, window).unwrap(),
                                expected,
                                "fresh {pattern:?}/{output:?}/{haystack:?}/{start}..{end}"
                            );
                            assert_eq!(
                                restored.search(haystack, window).unwrap(),
                                expected,
                                "restored {pattern:?}/{output:?}/{haystack:?}/{start}..{end}"
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn terminal_suffix_barrier_declines_body_overlap_and_nonterminal_primary() {
        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let overlap = program(
                "(?:xQ|aQ*B)Q",
                output,
                CompileMode::Optimizing,
                fallback_limits,
            );
            let suffix = overlap
                .nfa_mandatory_suffix
                .as_ref()
                .expect("overlap graph still owns the ordinary suffix sidecar");
            assert_eq!(suffix.maximum_width, None);
            assert_eq!(suffix.primary_depth, 0);
            assert!(!suffix.terminal_barrier);

            let nonterminal_primary = program(
                "(?:ab|c)+q[xz]",
                output,
                CompileMode::Optimizing,
                fallback_limits,
            );
            let suffix = nonterminal_primary
                .nfa_mandatory_suffix
                .as_ref()
                .expect("the selective preceding suffix column owns the sidecar");
            assert_eq!(suffix.primary_depth, 1);
            assert!(!suffix.terminal_barrier);

            let terminal_continuation = program(
                "(?:a|b)+Q+",
                output,
                CompileMode::Optimizing,
                fallback_limits,
            );
            let suffix = terminal_continuation
                .nfa_mandatory_suffix
                .as_ref()
                .expect("the repeated terminal still owns the ordinary suffix sidecar");
            assert_eq!(suffix.primary_depth, 0);
            assert!(!suffix.terminal_barrier);
        }
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "equal-selectivity admission, wire reconstruction, every contract, and every small window form one route-selection proof"
    )]
    fn unbounded_equal_selectivity_terminal_barrier_owns_the_suffix_first_route() {
        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let haystacks = generated_byte_strings(b"abcdzx", 3);

        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let accelerated = program(
                "(?:ab|ac|ad)+z",
                output,
                CompileMode::Optimizing,
                fallback_limits,
            );
            assert_eq!(accelerated.engine_kind(), EngineKind::OrderedNfa);
            let suffix = accelerated
                .nfa_mandatory_suffix
                .as_ref()
                .expect("equal-selectivity terminal barrier");
            assert_eq!(suffix.primary_count, 1);
            assert_eq!(suffix.primary_bytes[0], b'z');
            assert_eq!(suffix.primary_depth, 0);
            assert_eq!(suffix.maximum_width, None);
            assert!(suffix.terminal_barrier);
            assert!(
                accelerated.native_dynamic_rows_view().is_none(),
                "prepared dynamic rows would enter before the complete suffix for {output:?}"
            );
            assert!(
                accelerated
                    .prepare_workspace()
                    .expect("suffix-first workspace")
                    .dynamic_native_rows
                    .is_none(),
                "the declined dynamic route must not allocate hidden admission state"
            );

            let bytes = accelerated.serialize().expect("serialize terminal barrier");
            let restored = CompiledProgram::deserialize(&bytes).expect("restore terminal barrier");
            assert_eq!(restored.serialize().unwrap(), bytes);
            assert!(
                restored
                    .nfa_mandatory_suffix
                    .as_ref()
                    .is_some_and(|suffix| suffix.terminal_barrier)
            );
            assert!(restored.native_dynamic_rows_view().is_none());

            let mut ordinary = accelerated.clone();
            ordinary.nfa_mandatory_suffix = None;
            assert!(ordinary.native_dynamic_rows_view().is_some());
            for haystack in &haystacks {
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        let expected = ordinary.search(haystack, window).unwrap();
                        assert_eq!(
                            accelerated.search(haystack, window).unwrap(),
                            expected,
                            "fresh {output:?}/{haystack:?}/{start}..{end}"
                        );
                        assert_eq!(
                            restored.search(haystack, window).unwrap(),
                            expected,
                            "restored {output:?}/{haystack:?}/{start}..{end}"
                        );
                    }
                }
            }
        }

        for pattern in [
            "(?:ab|ac|ad)+a",
            "(?:ab|ac|ad)+q[xz]",
            "(?:ab|ac|ad){1,3}z",
        ] {
            let compiled = program(
                pattern,
                OutputContract::Span,
                CompileMode::Optimizing,
                fallback_limits,
            );
            assert!(
                compiled.nfa_mandatory_suffix.is_none(),
                "equal selectivity must require both an unbounded graph and a depth-zero terminal barrier: {pattern:?}"
            );
        }
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "simple and strict-suffix witnesses plus every output and wire reconstruction form one graph-receipt proof"
    )]
    fn dynamic_rows_publish_a_correlated_prefix_gate_receipt() {
        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            for (pattern, expected_depth, expected_literals, has_suffix) in [
                (
                    "(?:ant|bee|cat|dog)[a-z]{0,300}",
                    3_usize,
                    4_usize,
                    false,
                ),
                ("(?:foo|bar|baz){2,4}Q", 7, 27, true),
            ] {
                let compiled = program(
                    pattern,
                    output,
                    CompileMode::Optimizing,
                    fallback_limits,
                );
                assert_eq!(compiled.engine_kind(), EngineKind::OrderedNfa);
                assert!(!compiled.has_nfa_exact_product());
                assert_eq!(compiled.nfa_mandatory_suffix.is_some(), has_suffix);
                let prefix = compiled.required_literals.prefix();
                assert_eq!(prefix.depth(), expected_depth, "{output:?}/{pattern:?}");
                assert_eq!(
                    prefix.literals().len(),
                    expected_literals,
                    "{output:?}/{pattern:?}"
                );
                let view = compiled.native_dynamic_rows_view().expect("dynamic rows");
                let requirement = view
                    .correlated_prefix_requirement
                    .expect("correlated prefix receipt");
                let repeated_requirement = compiled
                    .native_dynamic_rows_view()
                    .and_then(|view| view.correlated_prefix_requirement)
                    .expect("cached correlated prefix receipt");
                assert!(
                    core::ptr::eq(requirement, repeated_requirement),
                    "runtime views must borrow one compile-time cache: {output:?}/{pattern:?}"
                );
                assert_eq!(
                    usize::from(requirement.minimum_width),
                    prefix.depth(),
                    "{output:?}/{pattern:?}"
                );
                let plan = requirement.teddy_plan;
                assert_eq!(plan.bank_count(), 1, "{output:?}/{pattern:?}");
                assert!((3..=4).contains(&plan.columns()), "{output:?}/{pattern:?}");
                assert!(plan.columns() <= requirement.minimum_width);
                assert!(usize::from(plan.literal_count()) <= prefix.literals().len());
                for literal in prefix.literals() {
                    assert!(
                        plan.candidate_buckets(literal.as_bytes()) != 0,
                        "{output:?}/{pattern:?}/{:?}",
                        literal.as_bytes()
                    );
                }

                let bytes = compiled.serialize().expect("serialize correlated prefix");
                let restored =
                    CompiledProgram::deserialize(&bytes).expect("restore correlated prefix");
                assert_eq!(restored.serialize().unwrap(), bytes);
                assert_eq!(
                    restored
                        .native_dynamic_rows_view()
                        .and_then(|view| view.correlated_prefix_requirement),
                    Some(requirement),
                    "{output:?}/{pattern:?}"
                );
            }
        }

        for (pattern, mode) in [
            ("(?:ant|bee|cat|dog)[a-z]{0,300}", CompileMode::Fast),
            ("(?:an|be|ca|do)[a-z]{0,300}", CompileMode::Optimizing),
            ("(?:ant|bee)[a-z]{0,300}", CompileMode::Optimizing),
        ] {
            let compiled = program(pattern, OutputContract::Span, mode, fallback_limits);
            let view = compiled.native_dynamic_rows_view().expect("dynamic control");
            assert!(
                view.correlated_prefix_requirement.is_none(),
                "unsupported correlated-prefix shape: {pattern:?}/{mode:?}"
            );
        }
    }

    #[test]
    fn resource_fallback_mandatory_cut_is_structural_and_round_trips() {
        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let pattern = "(?:x|yz)7[A-Za-z]+";
        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let compiled = program(pattern, output, CompileMode::Optimizing, fallback_limits);
            assert_eq!(compiled.engine_kind(), EngineKind::OrderedNfa);
            assert!(compiled.nfa_mandatory_suffix.is_none());
            let cut = compiled
                .nfa_mandatory_cut
                .as_ref()
                .expect("selective mandatory interior root should construct a cut");
            assert_eq!(cut.cardinality, 1);
            assert!(cut.has_member(b"no 7 here"));
            assert!(!cut.has_member(b"cut-free window"));
            assert_eq!(
                compiled.bit_parallel_exists_stats().is_some(),
                output == OutputContract::Exists,
                "only the complete Exists proof should compose with the cut"
            );

            let bytes = compiled.serialize().expect("serialize cut fallback");
            assert!(compiled.automaton.has_epsilon_closure_dispatch());
            let expected_flags = PROGRAM_FLAG_NFA_MANDATORY_CUT
                | PROGRAM_FLAG_NFA_EPSILON_CLOSURE_DISPATCH
                | if output == OutputContract::Exists {
                    PROGRAM_FLAG_NFA_OPTIMIZING_FALLBACK
                } else {
                    0
                };
            assert_eq!(bytes[15], expected_flags);
            let restored = CompiledProgram::deserialize(&bytes).expect("restore cut fallback");
            assert!(restored.nfa_mandatory_suffix.is_none());
            assert!(restored.nfa_mandatory_cut.is_some());
            assert_eq!(
                restored.bit_parallel_exists_stats(),
                compiled.bit_parallel_exists_stats()
            );
            assert_eq!(restored.serialize().unwrap(), bytes);

            let fast = program(
                pattern,
                output,
                CompileMode::Fast,
                DeterminizeLimits::default(),
            );
            assert!(fast.nfa_mandatory_cut.is_none());
            assert_eq!(fast.serialize().unwrap()[15], 0);
        }

        let nullable = program(
            "(?:|(?:x|yz)7[A-Za-z]+)",
            OutputContract::Span,
            CompileMode::Optimizing,
            fallback_limits,
        );
        assert!(nullable.nfa_mandatory_cut.is_none());

        let marginal = program(
            "[ABC]+[QR][0-9]+",
            OutputContract::Span,
            CompileMode::Optimizing,
            fallback_limits,
        );
        assert!(
            marginal.nfa_mandatory_cut.is_none(),
            "an extra pass requires at least a twofold selectivity gain"
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "small generated sources, every window, all contracts, wire reconstruction, cycles, assertions, and scanner tiers form one differential proof"
    )]
    fn mandatory_cut_matches_ordered_nfa_for_every_generated_window() {
        let ordinary_fallback = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let context_fallback = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let cases: &[(&str, &[u8], DeterminizeLimits, u16)] = &[
            ("[A-Za-z]+7[0-9]+", b"Aa70!", ordinary_fallback, 1),
            ("[A-Za-z]+[QWER][0-9]+", b"AaQW0!", ordinary_fallback, 4),
            (
                r"(?-u:[A-Za-z]+[\x80-\x83][0-9]+)",
                &[b'A', b'a', 0x80, 0x83, b'0', b'!'],
                ordinary_fallback,
                4,
            ),
            ("(?:x|yz)7[A-Za-z]+", b"xyz7A!", ordinary_fallback, 1),
            ("[ab]*(?:x|yz)7[A-Za-z]+", b"abxyz7A", ordinary_fallback, 1),
            (
                "(?:[A-Z]|[a-z][0-9])[QWER][0-9]+",
                b"Aa0QW9!",
                ordinary_fallback,
                4,
            ),
            (
                r"(?-u:(?:[A-Z]|[a-z][0-9])[\x80-\x83][0-9]+)",
                &[b'A', b'a', b'0', 0x80, 0x83, b'9', 0xff],
                ordinary_fallback,
                4,
            ),
            (
                r"(?m:(?:^[A-Z]|[a-z][0-9]))7[A-Za-z]+",
                b"Aa07Z\n!",
                context_fallback,
                1,
            ),
        ];

        for &(pattern, alphabet, limits, expected_cardinality) in cases {
            let haystacks = generated_byte_strings(alphabet, 3);
            for output in [
                OutputContract::Exists,
                OutputContract::SelectedEnd,
                OutputContract::Span,
            ] {
                let accelerated = program(pattern, output, CompileMode::Optimizing, limits);
                assert_eq!(
                    accelerated.engine_kind(),
                    EngineKind::OrderedNfa,
                    "{pattern:?}"
                );
                assert!(accelerated.nfa_mandatory_suffix.is_none(), "{pattern:?}");
                assert_eq!(
                    accelerated
                        .nfa_mandatory_cut
                        .as_ref()
                        .unwrap_or_else(|| panic!("missing cut for {pattern:?}"))
                        .cardinality,
                    expected_cardinality,
                    "{pattern:?}"
                );
                let restored = CompiledProgram::deserialize(
                    &accelerated.serialize().expect("serialize generated cut"),
                )
                .expect("restore generated cut");
                let mut reference = accelerated.clone();
                reference.nfa_mandatory_cut = None;
                let mut accelerated_workspace = accelerated.prepare_workspace().unwrap();
                let mut restored_workspace = restored.prepare_workspace().unwrap();
                let mut reference_workspace = reference.prepare_workspace().unwrap();

                for haystack in &haystacks {
                    for start in 0..=haystack.len() {
                        for end in start..=haystack.len() {
                            let window = SearchWindow::new(start, end);
                            let expected = reference
                                .search_with_workspace(haystack, window, &mut reference_workspace)
                                .unwrap();
                            assert_eq!(
                                accelerated
                                    .search_with_workspace(
                                        haystack,
                                        window,
                                        &mut accelerated_workspace,
                                    )
                                    .unwrap(),
                                expected,
                                "fresh {pattern:?}/{output:?}/{haystack:?}/{start}..{end}"
                            );
                            assert_eq!(
                                restored
                                    .search_with_workspace(
                                        haystack,
                                        window,
                                        &mut restored_workspace,
                                    )
                                    .unwrap(),
                                expected,
                                "wire {pattern:?}/{output:?}/{haystack:?}/{start}..{end}"
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the explicit adversarial graph and every-window differential form one proof"
    )]
    fn mandatory_cut_handles_consuming_cycles_and_multiple_accepts() {
        type TestEdge = (u32, EdgeKind, u8, u8);
        let epsilon = |target| (target, EdgeKind::Epsilon, 0, 0);
        let byte = |target, start, end| (target, EdgeKind::ByteRange, start, end);
        let rows: Vec<Vec<TestEdge>> = vec![
            vec![epsilon(1), epsilon(2), epsilon(7)],
            vec![byte(4, b'x', b'x')],
            vec![byte(3, b'y', b'y')],
            vec![byte(4, b'z', b'z')],
            vec![byte(5, b'7', b'7')],
            vec![
                byte(5, b'A', b'Z'),
                byte(6, b'A', b'Z'),
                byte(5, b'a', b'z'),
                byte(8, b'a', b'z'),
            ],
            vec![],
            vec![byte(0, b'p', b'p')],
            vec![],
        ];
        let roles = vec![
            StateRole::Split,
            StateRole::Consume,
            StateRole::Consume,
            StateRole::Consume,
            StateRole::Consume,
            StateRole::Consume,
            StateRole::Accept,
            StateRole::Consume,
            StateRole::Accept,
        ];
        let mut edge_offsets = Vec::with_capacity(rows.len().saturating_add(1));
        let mut edge_targets = Vec::new();
        let mut edge_kinds = Vec::new();
        let mut byte_starts = Vec::new();
        let mut byte_ends = Vec::new();
        edge_offsets.push(0);
        for row in rows {
            for (target, kind, start, end) in row {
                edge_targets.push(target);
                edge_kinds.push(kind);
                byte_starts.push(start);
                byte_ends.push(end);
            }
            edge_offsets.push(u32::try_from(edge_targets.len()).expect("test edge count"));
        }
        let raw = RawPlan {
            start: 0,
            roles,
            edge_offsets,
            edge_targets,
            edge_kinds,
            byte_starts,
            byte_ends,
        };
        let automaton = Automaton::from_raw(raw.clone(), CompileLimits::default())
            .expect("cyclic multi-accept graph validates");
        let accelerated = CompiledProgram::build(
            raw,
            automaton,
            OutputContract::Span,
            CompileMode::Optimizing,
            DeterminizeLimits {
                max_states: 0,
                ..DeterminizeLimits::default()
            },
            usize::MAX,
        )
        .expect("compile cyclic multi-accept fallback");
        assert!(accelerated.nfa_mandatory_suffix.is_none());
        assert_eq!(
            accelerated
                .nfa_mandatory_cut
                .as_ref()
                .expect("common consuming dominator")
                .cardinality,
            1
        );
        let restored = CompiledProgram::deserialize(&accelerated.serialize().unwrap()).unwrap();
        let mut reference = accelerated.clone();
        reference.nfa_mandatory_cut = None;
        let mut accelerated_workspace = accelerated.prepare_workspace().unwrap();
        let mut restored_workspace = restored.prepare_workspace().unwrap();
        let mut reference_workspace = reference.prepare_workspace().unwrap();
        for haystack in generated_byte_strings(b"pxyz7Aa", 4) {
            for start in 0..=haystack.len() {
                for end in start..=haystack.len() {
                    let window = SearchWindow::new(start, end);
                    let expected = reference
                        .search_with_workspace(&haystack, window, &mut reference_workspace)
                        .unwrap();
                    assert_eq!(
                        accelerated
                            .search_with_workspace(&haystack, window, &mut accelerated_workspace,)
                            .unwrap(),
                        expected
                    );
                    assert_eq!(
                        restored
                            .search_with_workspace(&haystack, window, &mut restored_workspace)
                            .unwrap(),
                        expected
                    );
                }
            }
        }
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        clippy::type_complexity,
        reason = "all scanner tiers, contracts, windows, wire reconstruction, the exact narrowing boundary, and malformed fail-open behavior form one differential proof"
    )]
    fn finite_mandatory_cut_narrows_every_scanner_tier_and_preserves_every_window() {
        const SMALL: u8 = 0;
        const ASCII: u8 = 1;
        const FULL: u8 = 2;

        let limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let cases: &[(&str, &[u8], &[u8], u16, u8)] = &[
            ("(?:x|yz)7[A-Za-z]{1,2}", b"xyz7A!", b"yz7AA", 1, SMALL),
            (
                "(?:[A-Z]|[a-z][0-9])[QR][0-9]{1,2}",
                b"Aa0QR!",
                b"a0Q0",
                2,
                SMALL,
            ),
            (
                "(?:[A-Z]|[a-z][0-9])[QWE][0-9]{1,2}",
                b"Aa0QWE!",
                b"a0W0",
                3,
                SMALL,
            ),
            (
                "(?:[A-Z]|[a-z][0-9])[QWER][0-9]{1,2}",
                b"Aa0QWER!",
                b"a0R0",
                4,
                ASCII,
            ),
            (
                r"(?-u:(?:[A-Z]|[a-z][0-9])[\x80-\x83][0-9]{1,2})",
                &[b'A', b'a', b'0', 0x80, 0x83, b'!'],
                &[b'a', b'0', 0x80, b'0'],
                4,
                FULL,
            ),
        ];

        for &(pattern, alphabet, witness, cardinality, tier) in cases {
            let mut haystacks = generated_byte_strings(alphabet, 4);
            for output in [
                OutputContract::Exists,
                OutputContract::SelectedEnd,
                OutputContract::Span,
            ] {
                let accelerated = program(pattern, output, CompileMode::Optimizing, limits);
                assert_eq!(
                    accelerated.engine_kind(),
                    EngineKind::OrderedNfa,
                    "{pattern}"
                );
                assert!(accelerated.nfa_mandatory_suffix.is_none(), "{pattern}");
                let maximum_width = accelerated
                    .max_match_width()
                    .unwrap_or_else(|| panic!("missing finite width for {pattern}"));
                let cut = accelerated
                    .nfa_mandatory_cut
                    .as_ref()
                    .unwrap_or_else(|| panic!("missing mandatory cut for {pattern}"));
                assert!(cut.exact_product().is_none(), "{pattern}");
                assert_eq!(cut.cardinality, cardinality, "{pattern}");
                match (&cut.scanner, tier) {
                    (NfaMandatoryCutScanner::Small { count, .. }, SMALL) => {
                        assert_eq!(u16::from(*count), cardinality, "{pattern}");
                    }
                    (NfaMandatoryCutScanner::Ascii { .. }, ASCII)
                    | (NfaMandatoryCutScanner::Full { .. }, FULL) => {}
                    (scanner, _) => panic!("wrong scanner tier for {pattern}: {scanner:?}"),
                }

                let miss = (u8::MIN..=u8::MAX)
                    .find(|&byte| cut.first_member(&[byte]) == NfaMandatoryCutScan::Exhausted)
                    .expect("selective cut has a nonmember");
                let member = (u8::MIN..=u8::MAX)
                    .find(|&byte| cut.first_member(&[byte]) == NfaMandatoryCutScan::Member(0))
                    .expect("nonempty cut has a member");
                let mut boundary_probe = vec![miss; maximum_width + 12];
                let window = SearchWindow::new(2, boundary_probe.len() - 1);
                let member_position = maximum_width + 5;
                boundary_probe[member_position] = member;
                let width_backtrack = maximum_width
                    .checked_sub(1)
                    .expect("a consuming cut has positive maximum width");
                let maximum_start_backtrack = cut
                    .maximum_start_backtrack
                    .and_then(|distance| usize::try_from(distance).ok())
                    .map_or(width_backtrack, |root| root.min(width_backtrack));
                let narrowed = SearchWindow::new(
                    member_position
                        .saturating_sub(maximum_start_backtrack)
                        .max(window.start),
                    window.end,
                );
                assert!(narrowed.start > window.start, "{pattern}");
                assert_eq!(
                    accelerated.search_nfa_with_mandatory_cut(&boundary_probe, window),
                    NfaMandatoryCutOutcome::Continue(narrowed),
                    "fresh {pattern}/{output:?}"
                );

                let serialized = accelerated.serialize().expect("serialize finite cut");
                let restored =
                    CompiledProgram::deserialize(&serialized).expect("restore finite cut");
                assert_eq!(restored.max_match_width(), Some(maximum_width));
                assert_eq!(
                    restored.search_nfa_with_mandatory_cut(&boundary_probe, window),
                    NfaMandatoryCutOutcome::Continue(narrowed),
                    "wire {pattern}/{output:?}"
                );

                let mut reference = accelerated.clone();
                reference.nfa_mandatory_cut = None;
                let mut malformed = accelerated.clone();
                let malformed_cut = malformed
                    .nfa_mandatory_cut
                    .as_mut()
                    .expect("cut to corrupt");
                malformed_cut.scanner = NfaMandatoryCutScanner::Small {
                    bytes: [member, 0, 0],
                    count: 0,
                };
                assert_eq!(
                    malformed.search_nfa_with_mandatory_cut(&boundary_probe, window),
                    NfaMandatoryCutOutcome::Continue(window),
                    "malformed scanner must fail open for {pattern}/{output:?}"
                );

                let mut late_match = vec![miss; maximum_width + 8];
                late_match.extend_from_slice(witness);
                haystacks.push(boundary_probe.clone());
                haystacks.push(late_match);
                let mut accelerated_workspace = accelerated.prepare_workspace().unwrap();
                let mut restored_workspace = restored.prepare_workspace().unwrap();
                let mut reference_workspace = reference.prepare_workspace().unwrap();
                let mut malformed_workspace = malformed.prepare_workspace().unwrap();
                for haystack in &haystacks {
                    for start in 0..=haystack.len() {
                        for end in start..=haystack.len() {
                            let window = SearchWindow::new(start, end);
                            let expected = reference
                                .search_with_workspace(haystack, window, &mut reference_workspace)
                                .unwrap();
                            assert_eq!(
                                accelerated
                                    .search_with_workspace(
                                        haystack,
                                        window,
                                        &mut accelerated_workspace,
                                    )
                                    .unwrap(),
                                expected,
                                "fresh {pattern}/{output:?}/{haystack:?}/{start}..{end}"
                            );
                            assert_eq!(
                                restored
                                    .search_with_workspace(
                                        haystack,
                                        window,
                                        &mut restored_workspace,
                                    )
                                    .unwrap(),
                                expected,
                                "wire {pattern}/{output:?}/{haystack:?}/{start}..{end}"
                            );
                            assert_eq!(
                                malformed
                                    .search_with_workspace(
                                        haystack,
                                        window,
                                        &mut malformed_workspace,
                                    )
                                    .unwrap(),
                                expected,
                                "fail-open {pattern}/{output:?}/{haystack:?}/{start}..{end}"
                            );
                        }
                    }
                }
                haystacks.truncate(haystacks.len().saturating_sub(2));
            }
        }
    }

    #[test]
    fn finite_prefix_distance_narrows_an_unbounded_mandatory_cut() {
        let pattern = "(?:x|yz)7.*";
        let limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let witness_start = 73;
        let mut haystack = vec![b'!'; witness_start];
        haystack.extend_from_slice(b"yz7tail");
        let original = SearchWindow::new(3, haystack.len());
        let expected_window = SearchWindow::new(witness_start, haystack.len());

        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let accelerated = program(pattern, output, CompileMode::Optimizing, limits);
            assert_eq!(accelerated.engine_kind(), EngineKind::OrderedNfa);
            assert_eq!(accelerated.max_match_width(), None);
            assert!(accelerated.nfa_mandatory_suffix.is_none());
            let cut = accelerated
                .nfa_mandatory_cut
                .as_ref()
                .expect("mandatory interior byte");
            assert!(cut.exact_product().is_none());
            assert_eq!(cut.cardinality, 1);
            assert_eq!(cut.maximum_start_backtrack, Some(2));
            assert_eq!(
                accelerated.search_nfa_with_mandatory_cut(&haystack, original),
                NfaMandatoryCutOutcome::Continue(expected_window)
            );

            let serialized = accelerated.serialize().expect("serialize unbounded cut");
            let restored =
                CompiledProgram::deserialize(&serialized).expect("restore unbounded cut");
            assert_eq!(restored.max_match_width(), None);
            assert_eq!(
                restored
                    .nfa_mandatory_cut
                    .as_ref()
                    .and_then(|cut| cut.maximum_start_backtrack),
                Some(2)
            );
            assert_eq!(
                restored.search_nfa_with_mandatory_cut(&haystack, original),
                NfaMandatoryCutOutcome::Continue(expected_window)
            );

            let mut reference = accelerated.clone();
            reference.nfa_mandatory_cut = None;
            let mut accelerated_workspace = accelerated.prepare_workspace().unwrap();
            let mut restored_workspace = restored.prepare_workspace().unwrap();
            let mut reference_workspace = reference.prepare_workspace().unwrap();
            let expected = reference
                .search_with_workspace(&haystack, original, &mut reference_workspace)
                .unwrap();
            assert_eq!(
                accelerated
                    .search_with_workspace(&haystack, original, &mut accelerated_workspace)
                    .unwrap(),
                expected
            );
            assert_eq!(
                restored
                    .search_with_workspace(&haystack, original, &mut restored_workspace)
                    .unwrap(),
                expected
            );
        }
    }

    #[test]
    fn mandatory_cut_classifiers_cover_every_block_boundary() {
        let limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        for (pattern, member, ascii) in [
            ("(?:[A-Z]|[a-z][0-9])[QWER][0-9]+", b'Q', true),
            (r"(?-u:(?:[A-Z]|[a-z][0-9])[\x80-\x83][0-9]+)", 0x80, false),
        ] {
            let compiled = program(
                pattern,
                OutputContract::Exists,
                CompileMode::Optimizing,
                limits,
            );
            let cut = compiled.nfa_mandatory_cut.as_ref().unwrap();
            assert_eq!(
                matches!(cut.scanner, NfaMandatoryCutScanner::Ascii { .. }),
                ascii
            );
            assert_eq!(
                matches!(cut.scanner, NfaMandatoryCutScanner::Full { .. }),
                !ascii
            );
            for length in 0..=96 {
                let miss = vec![b'!'; length];
                assert!(!cut.has_member(&miss), "{pattern:?}/{length}");
                for position in 0..length {
                    let mut hit = miss.clone();
                    hit[position] = member;
                    assert!(
                        cut.has_member(&hit),
                        "{pattern:?}/{length}/hit-at-{position}"
                    );
                }
            }
        }
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "every scanner tier, source alignment, block extent, member position, and malformed count form one boundary proof"
    )]
    fn mandatory_cut_scanners_return_the_first_member_at_every_block_boundary() {
        fn words(bytes: &[u8]) -> [u64; 4] {
            let mut words = [0_u64; 4];
            for &byte in bytes {
                let index = usize::from(byte);
                words[index / 64] |= 1_u64 << (index % 64);
            }
            words
        }

        let ascii_words = words(&[1, 17, 65, 126]);
        let ascii_set = AsciiByteSet::from_words([ascii_words[0], ascii_words[1]]);
        let full_words = words(&[1, 17, 128, 254]);
        let full_set = ByteSet256::from_words(full_words);
        let scanners = [
            (
                "small-1",
                NfaMandatoryCutScanner::Small {
                    bytes: [1, 0, 0],
                    count: 1,
                },
                vec![1],
            ),
            (
                "small-2",
                NfaMandatoryCutScanner::Small {
                    bytes: [1, 17, 0],
                    count: 2,
                },
                vec![1, 17],
            ),
            (
                "small-3",
                NfaMandatoryCutScanner::Small {
                    bytes: [1, 17, 200],
                    count: 3,
                },
                vec![1, 17, 200],
            ),
            (
                "ascii",
                NfaMandatoryCutScanner::Ascii {
                    set: ascii_set,
                    classifier: AsciiByteSetClassifier::new(ascii_set),
                },
                vec![1, 17, 65, 126],
            ),
            (
                "full",
                NfaMandatoryCutScanner::Full {
                    set: full_set,
                    classifier: ByteSetClassifier::new(full_set),
                },
                vec![1, 17, 128, 254],
            ),
        ];

        // Vary both the slice address and extent through the scalar prefix,
        // 16-byte classifier, 32-byte classifier, and scalar-tail boundaries.
        for (name, scanner, members) in scanners {
            let cut = NfaMandatoryCut {
                root_state: 0,
                cardinality: u16::try_from(members.len()).unwrap(),
                maximum_start_backtrack: None,
                scanner,
            };
            for alignment in 0..32 {
                let mut storage = vec![u8::MAX; alignment + 96];
                for length in 0..=96 {
                    let source = &storage[alignment..alignment + length];
                    assert_eq!(
                        cut.first_member(source),
                        NfaMandatoryCutScan::Exhausted,
                        "{name}/alignment={alignment}/length={length}/miss"
                    );
                    for position in 0..length {
                        for &member in &members {
                            storage[alignment + position] = member;
                            let source = &storage[alignment..alignment + length];
                            assert_eq!(
                                cut.first_member(source),
                                NfaMandatoryCutScan::Member(position),
                                "{name}/alignment={alignment}/length={length}/position={position}/member={member}"
                            );
                            storage[alignment + position] = u8::MAX;
                        }
                    }
                    if length >= 2 {
                        storage[alignment] = members[0];
                        storage[alignment + length - 1] = *members.last().unwrap();
                        let source = &storage[alignment..alignment + length];
                        assert_eq!(
                            cut.first_member(source),
                            NfaMandatoryCutScan::Member(0),
                            "{name}/alignment={alignment}/length={length}/first-of-two"
                        );
                        storage[alignment] = u8::MAX;
                        storage[alignment + length - 1] = u8::MAX;
                    }
                }
            }
        }

        for count in [0_u8, 4, u8::MAX] {
            let malformed = NfaMandatoryCut {
                root_state: 0,
                cardinality: 3,
                maximum_start_backtrack: None,
                scanner: NfaMandatoryCutScanner::Small {
                    bytes: [1, 17, 200],
                    count,
                },
            };
            assert_eq!(malformed.first_member(&[]), NfaMandatoryCutScan::Fallback);
            assert_eq!(
                malformed.first_member(&[1, 17, 200]),
                NfaMandatoryCutScan::Fallback
            );
        }
    }

    #[test]
    fn mandatory_suffix_acceleration_matches_ordered_nfa_for_every_small_window() {
        fn extend_haystacks(
            haystacks: &mut Vec<Vec<u8>>,
            prefix: &mut Vec<u8>,
            alphabet: &[u8],
            remaining: usize,
        ) {
            haystacks.push(prefix.clone());
            if remaining == 0 {
                return;
            }
            for &byte in alphabet {
                prefix.push(byte);
                extend_haystacks(haystacks, prefix, alphabet, remaining - 1);
                prefix.pop();
            }
        }

        let patterns = [
            "(?:a|bb)z",
            "(?:bb|a)z",
            "(?:a|bc)z",
            "..z|.z",
            ".z|..z",
            ".{1,3}z",
            ".{1,3}?z",
            "[ab]{1,3}z",
            "[ab]{1,3}?z",
            "[a-y]{1,7}z",
            "(?:ab|ba){1,2}z",
            "(?:a|ba){1,2}z",
            "(?:a|bb)q[xz]",
        ];
        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let mut haystacks = Vec::new();
        extend_haystacks(&mut haystacks, &mut Vec::new(), b"abzx", 4);
        haystacks.extend([
            b"xaaabz".to_vec(),
            b"xababz".to_vec(),
            b"zzabbbzx".to_vec(),
            b"xabxzbbz".to_vec(),
            b"xaqzbbqx".to_vec(),
        ]);

        for pattern in patterns {
            for output in [
                OutputContract::Exists,
                OutputContract::SelectedEnd,
                OutputContract::Span,
            ] {
                let accelerated =
                    program(pattern, output, CompileMode::Optimizing, fallback_limits);
                assert_eq!(
                    accelerated.engine_kind(),
                    EngineKind::OrderedNfa,
                    "{pattern:?}"
                );
                assert!(
                    accelerated.nfa_mandatory_suffix.is_some(),
                    "eligible fixture was declined: {pattern:?}"
                );
                let mut reference = accelerated.clone();
                reference.nfa_mandatory_suffix = None;
                let mut accelerated_workspace = accelerated.prepare_workspace().unwrap();
                let mut reference_workspace = reference.prepare_workspace().unwrap();

                // Repeating every window reuses any output-specific terminal
                // and reverse facts cached by the first pass.
                for pass in 0..2 {
                    for haystack in &haystacks {
                        for start in 0..=haystack.len() {
                            for end in start..=haystack.len() {
                                let window = SearchWindow::new(start, end);
                                let expected = reference
                                    .search_with_workspace(
                                        haystack,
                                        window,
                                        &mut reference_workspace,
                                    )
                                    .unwrap();
                                let actual = accelerated
                                    .search_with_workspace(
                                        haystack,
                                        window,
                                        &mut accelerated_workspace,
                                    )
                                    .unwrap();
                                assert_eq!(
                                    actual, expected,
                                    "{pattern:?}/{output:?}/pass={pass}/{haystack:?}/{start}..{end}"
                                );
                            }
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn scan_only_mandatory_suffix_is_structural_and_round_trips() {
        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let compiled = program(
                "(?:ab|c)*q[xz]",
                output,
                CompileMode::Optimizing,
                fallback_limits,
            );
            assert_eq!(compiled.engine_kind(), EngineKind::OrderedNfa);
            assert!(compiled.max_match_width.width.is_none());
            assert!(compiled.max_match_width.unbounded);
            let accelerator = compiled
                .nfa_mandatory_suffix
                .as_ref()
                .expect("unbounded selective suffix should construct the sidecar");
            assert_eq!(accelerator.primary_depth, 1);
            assert_eq!(accelerator.primary_bytes[0], b'q');
            assert_eq!(accelerator.maximum_width, None);

            let bytes = compiled.serialize().expect("serialize fallback");
            assert!(compiled.automaton.has_epsilon_closure_dispatch());
            assert_eq!(
                bytes[15],
                PROGRAM_FLAG_NFA_MANDATORY_SUFFIX
                    | PROGRAM_FLAG_NFA_EPSILON_CLOSURE_DISPATCH
                    | PROGRAM_FLAG_NFA_OPTIMIZING_FALLBACK
            );
            let restored = CompiledProgram::deserialize(&bytes).expect("restore fallback");
            assert!(restored.nfa_mandatory_suffix.is_some());
            assert_eq!(
                restored.bit_parallel_exists_stats(),
                compiled.bit_parallel_exists_stats()
            );
            assert_eq!(
                restored
                    .nfa_mandatory_suffix
                    .as_ref()
                    .and_then(|sidecar| sidecar.maximum_width),
                None
            );
            assert_eq!(restored.serialize().unwrap(), bytes);
        }

        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let wide = program(".{1,65}z", output, CompileMode::Optimizing, fallback_limits);
            assert!(
                wide.max_match_width
                    .width
                    .is_some_and(|width| width > MAX_NFA_SUFFIX_CANDIDATE_WORK)
            );
            assert_eq!(
                wide.nfa_mandatory_suffix
                    .as_ref()
                    .expect("wide finite suffix should retain the scan-only sidecar")
                    .maximum_width,
                None
            );
            let bytes = wide.serialize().unwrap();
            assert_eq!(
                bytes[15],
                PROGRAM_FLAG_NFA_MANDATORY_SUFFIX
                    | PROGRAM_FLAG_NFA_ORDERED_EDGE_DISPATCH
                    | PROGRAM_FLAG_NFA_OPTIMIZING_FALLBACK
            );
            let restored = CompiledProgram::deserialize(&bytes).unwrap();
            assert_eq!(restored.serialize().unwrap(), bytes);
            for haystack in [
                b"xxxxxxxxxxxxxxxx".as_slice(),
                b"xxxxxxxxxxxxxxxz",
                b"zxxxxxxxxxxxxxxx",
                b"\n\n\n\n\n\n\n\n",
            ] {
                let mut reference = wide.clone();
                reference.nfa_mandatory_suffix = None;
                assert_eq!(
                    wide.search(haystack, SearchWindow::full(haystack)).unwrap(),
                    reference
                        .search(haystack, SearchWindow::full(haystack))
                        .unwrap(),
                    "{output:?}/{haystack:?}"
                );
            }
        }
    }

    #[test]
    fn scan_only_mandatory_suffix_matches_ordered_nfa_for_every_small_window() {
        fn extend_haystacks(
            haystacks: &mut Vec<Vec<u8>>,
            prefix: &mut Vec<u8>,
            alphabet: &[u8],
            remaining: usize,
        ) {
            haystacks.push(prefix.clone());
            if remaining == 0 {
                return;
            }
            for &byte in alphabet {
                prefix.push(byte);
                extend_haystacks(haystacks, prefix, alphabet, remaining - 1);
                prefix.pop();
            }
        }

        let patterns = [
            "a*z",
            "a*?z",
            "(?:ab)*z",
            "(?:ab)*?z",
            "(?:ab|c)*q[xz]",
            "(?:ab|c)*?q[xz]",
            "(?:a|bc)*qz",
            "(?:a|bc)*?qz",
        ];
        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let mut haystacks = Vec::new();
        extend_haystacks(&mut haystacks, &mut Vec::new(), b"abqzx", 4);
        haystacks.extend([
            b"aaaaaaaaaz".to_vec(),
            b"ababababqz".to_vec(),
            b"ccccccqz".to_vec(),
            b"zqzxqz".to_vec(),
            b"xxxxxxxx".to_vec(),
        ]);

        for pattern in patterns {
            for output in [
                OutputContract::Exists,
                OutputContract::SelectedEnd,
                OutputContract::Span,
            ] {
                let accelerated =
                    program(pattern, output, CompileMode::Optimizing, fallback_limits);
                assert_eq!(
                    accelerated.engine_kind(),
                    EngineKind::OrderedNfa,
                    "{pattern:?}"
                );
                assert!(
                    accelerated.nfa_mandatory_suffix.is_some(),
                    "eligible unbounded fixture was declined: {pattern:?}"
                );
                assert_eq!(
                    accelerated
                        .nfa_mandatory_suffix
                        .as_ref()
                        .and_then(|sidecar| sidecar.maximum_width),
                    None,
                    "{pattern:?}"
                );
                let restored = CompiledProgram::deserialize(
                    &accelerated
                        .serialize()
                        .expect("serialize scan-only sidecar"),
                )
                .expect("restore scan-only sidecar");
                assert!(restored.nfa_mandatory_suffix.is_some());
                let reference = program(
                    pattern,
                    output,
                    CompileMode::Fast,
                    DeterminizeLimits::default(),
                );
                assert!(reference.nfa_mandatory_suffix.is_none());
                let mut accelerated_workspace = accelerated.prepare_workspace().unwrap();
                let mut restored_workspace = restored.prepare_workspace().unwrap();
                let mut reference_workspace = reference.prepare_workspace().unwrap();

                for haystack in &haystacks {
                    for start in 0..=haystack.len() {
                        for end in start..=haystack.len() {
                            let window = SearchWindow::new(start, end);
                            let expected = reference
                                .search_with_workspace(haystack, window, &mut reference_workspace)
                                .unwrap();
                            let actual = accelerated
                                .search_with_workspace(haystack, window, &mut accelerated_workspace)
                                .unwrap();
                            let restored_actual = restored
                                .search_with_workspace(haystack, window, &mut restored_workspace)
                                .unwrap();
                            assert_eq!(
                                actual, expected,
                                "{pattern:?}/{output:?}/{haystack:?}/{start}..{end}"
                            );
                            assert_eq!(
                                restored_actual, expected,
                                "round trip {pattern:?}/{output:?}/{haystack:?}/{start}..{end}"
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn scan_only_mandatory_suffix_escapes_adversarial_candidates() {
        let endpoints = [1_025, 2_049, 3_073, 4_097];
        let mut reverse_work = 0;
        for &endpoint in &endpoints[..3] {
            reverse_work =
                NfaMandatorySuffix::next_scan_only_reverse_work(reverse_work, 0, endpoint)
                    .expect("sparse prefix remains inside the linear reverse-work envelope");
        }
        assert!(
            NfaMandatorySuffix::next_scan_only_reverse_work(reverse_work, 0, endpoints[3],)
                .is_none()
        );

        let fallback_limits = DeterminizeLimits {
            max_states: 0,
            ..DeterminizeLimits::default()
        };
        let mut sparse_false_candidates = vec![b'x'; 5_000];
        for endpoint in endpoints {
            sparse_false_candidates[endpoint - 1] = b'z';
        }
        let dense_candidates = vec![b'z'; 4_096];

        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            for (pattern, haystack) in [
                ("[ab]+z", sparse_false_candidates.as_slice()),
                ("[ab]*z", dense_candidates.as_slice()),
            ] {
                let accelerated =
                    program(pattern, output, CompileMode::Optimizing, fallback_limits);
                assert_eq!(
                    accelerated
                        .nfa_mandatory_suffix
                        .as_ref()
                        .and_then(|sidecar| sidecar.maximum_width),
                    None,
                    "{pattern:?}"
                );
                assert!(accelerated.nfa_mandatory_suffix.is_some(), "{pattern:?}");
                let reference = program(
                    pattern,
                    output,
                    CompileMode::Fast,
                    DeterminizeLimits::default(),
                );
                assert_eq!(
                    accelerated
                        .search(haystack, SearchWindow::full(haystack))
                        .unwrap(),
                    reference
                        .search(haystack, SearchWindow::full(haystack))
                        .unwrap(),
                    "{pattern:?}/{output:?}"
                );
            }
        }
    }

    #[test]
    fn ordered_nfa_workspace_uses_the_output_specific_persistent_cache() {
        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let program = program(
                "(?:ab|ac|ad)+z",
                output,
                CompileMode::Fast,
                DeterminizeLimits::default(),
            );
            let workspace = program.prepare_workspace().expect("prepare NFA workspace");
            let actual = workspace
                .nfa
                .as_ref()
                .expect("ordered NFA retains K0 storage")
                .layout();
            let expected = match output {
                OutputContract::Exists | OutputContract::SelectedEnd => program
                    .automaton
                    .accelerated_workspace_layout()
                    .expect("endpoint workspace layout"),
                OutputContract::Span => program
                    .automaton
                    .bidirectional_workspace_layout()
                    .expect("bidirectional workspace layout"),
            };
            assert_eq!(actual, expected, "{output:?}");
        }

        let fixed_span = program(
            "(?:ab|cd)",
            OutputContract::Span,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        assert_eq!(fixed_span.exact_match_width, Some(2));
        let workspace = fixed_span
            .prepare_workspace()
            .expect("prepare fixed-width span workspace");
        assert_eq!(
            workspace
                .nfa
                .as_ref()
                .expect("ordered NFA retains K0 storage")
                .layout(),
            fixed_span
                .automaton
                .accelerated_workspace_layout()
                .expect("fixed-width span endpoint layout")
        );
        assert_eq!(
            fixed_span
                .search(b"xxcdyy", SearchWindow::full(b"xxcdyy"))
                .expect("fixed-width fallback search"),
            MatchResult::Span(Some((2, 4)))
        );
    }

    #[test]
    fn variable_width_ordered_nfa_span_reuses_the_value_only_warm_route() {
        let compiled = program(
            "(?:ab|ac|ad)+z",
            OutputContract::Span,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        assert_eq!(compiled.engine_kind(), EngineKind::OrderedNfa);
        assert_eq!(compiled.exact_match_width(), None);
        assert!(compiled.partial_dfa().is_none());
        let mut workspace = compiled.prepare_workspace().expect("prepare NFA workspace");

        for (haystack, expected) in [
            (b"xxacadz".as_slice(), Some((2, 7))),
            (b"xxacady".as_slice(), None),
        ] {
            let window = SearchWindow::full(haystack);
            assert_eq!(
                compiled
                    .search_with_workspace(haystack, window, &mut workspace)
                    .expect("cold ordered-NFA Span search"),
                MatchResult::Span(expected)
            );
            assert_eq!(
                compiled
                    .search_with_workspace(haystack, window, &mut workspace)
                    .expect("warm value-only ordered-NFA Span search"),
                MatchResult::Span(expected)
            );
        }
    }

    #[test]
    fn ordered_nfa_workspace_remains_usable_by_a_semantically_identical_clone() {
        let original = program(
            "(?:ab|ac|ad)+z",
            OutputContract::SelectedEnd,
            CompileMode::Optimizing,
            DeterminizeLimits {
                max_states: 0,
                ..DeterminizeLimits::default()
            },
        );
        assert_eq!(original.engine_kind(), EngineKind::OrderedNfa);
        let cloned = original.clone();
        let mut workspace = original.prepare_workspace().expect("prepare NFA workspace");
        let haystack = b"xxacadz";
        assert_eq!(
            cloned
                .search_with_workspace(haystack, SearchWindow::full(haystack), &mut workspace)
                .expect("search cloned semantic program"),
            MatchResult::SelectedEnd(Some(haystack.len()))
        );
    }

    #[test]
    fn exact_width_span_omits_reverse_dfa_and_accepts_legacy_redundancy() {
        let optimized = program(
            "abc",
            OutputContract::Span,
            CompileMode::Optimizing,
            DeterminizeLimits::default(),
        );
        let stats = optimized.dfa_stats().expect("complete exact-width DFA");
        assert_eq!(optimized.exact_match_width, Some(3));
        assert_eq!(stats.reverse_states, 0);
        assert!(
            !optimized
                .determinization_report()
                .expect("fresh determinization receipt")
                .attempted_stages
                .contains(&DeterminizationStage::ReverseSubsetConstruction)
        );
        assert_eq!(
            optimized
                .search(b"xxabcxx", SearchWindow::full(b"xxabcxx"))
                .expect("exact-width direct search"),
            MatchResult::Span(Some((2, 5)))
        );

        // V2 artifacts emitted before this optimization redundantly retained
        // reverse start recovery for every nonnullable Span. Their presence
        // remains canonical under the old construction choice and must stay
        // readable even though new exact-width artifacts omit it.
        let mut legacy = program(
            "abc",
            OutputContract::Span,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        let legacy_machine = match dfa::determinize(&legacy.raw, true, DeterminizeLimits::default())
            .expect("legacy reverse determinization")
        {
            DeterminizeOutcome::Complete { machine, .. } => machine,
            DeterminizeOutcome::Declined { report, .. } => {
                panic!("legacy reverse determinization declined: {report:?}")
            }
        };
        assert!(legacy_machine.stats().reverse_states > 0);
        legacy.engine = ProgramEngine::OrderedDfa(legacy_machine);
        legacy.engine_selection_reason = Some(EngineSelectionReason::CompleteDfa);
        let restored = CompiledProgram::deserialize(
            &legacy
                .serialize()
                .expect("serialize legacy exact-width DFA"),
        )
        .expect("deserialize legacy exact-width DFA");
        assert!(restored.dfa_stats().unwrap().reverse_states > 0);
        assert_eq!(
            restored
                .search(b"xxabcxx", SearchWindow::full(b"xxabcxx"))
                .expect("legacy exact-width direct search"),
            MatchResult::Span(Some((2, 5)))
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "resource rescue, work accounting, wire compatibility and start provenance share one fixture"
    )]
    fn endpoint_dominance_prunes_priority_only_subsets_before_minimization() {
        // The overlapping first two classes keep differently ordered search
        // starts alive through the bounded repetition. Historical complete
        // construction had 131,072 ordered subsets before graph minimization
        // proved that only 19 forward states were observably distinct. The
        // graph-general anchored-continuation proof removes only adjacent
        // priority items that must reproduce the same selected endpoint.
        let pattern = r"[b-c][a-b]{1,16}z";
        let baseline = program(
            pattern,
            OutputContract::Span,
            CompileMode::Optimizing,
            DeterminizeLimits::default(),
        );
        assert_eq!(baseline.engine_kind(), EngineKind::OrderedDfa);
        assert_eq!(
            baseline.engine_selection_reason(),
            Some(EngineSelectionReason::CompleteDfa)
        );
        let baseline_stats = baseline.dfa_stats().expect("complete default DFA");
        assert_eq!(
            baseline_stats.forward_states_before_minimization,
            131_072
        );
        let direct_baseline = match dfa::determinize_current_ordered(
            &baseline.raw,
            true,
            DeterminizeLimits::default(),
        )
        .expect("direct completed ordered baseline")
        {
            DeterminizeOutcome::Complete { machine, .. } => machine,
            DeterminizeOutcome::Declined { report, .. } => {
                panic!("direct ordered baseline declined: {report:?}")
            }
        };
        let ProgramEngine::OrderedDfa(baseline_machine) = &baseline.engine else {
            panic!("baseline did not retain its ordered DFA")
        };
        assert_eq!(baseline_machine, &direct_baseline);

        // A completed baseline is retained unchanged. The more expensive
        // dominance proof is a resource-rescue transaction, not an added tax
        // on every endpoint compilation.
        let legacy_bytes = baseline
            .serialize()
            .expect("serialize historical endpoint DFA");
        let legacy_restored = CompiledProgram::deserialize(&legacy_bytes)
            .expect("deserialize historical endpoint DFA");
        assert_eq!(legacy_restored.serialize().unwrap(), legacy_bytes);

        let rescued = program(
            pattern,
            OutputContract::Span,
            CompileMode::Optimizing,
            DeterminizeLimits {
                max_states: 256,
                ..DeterminizeLimits::default()
            },
        );
        assert_eq!(rescued.engine_kind(), EngineKind::OrderedDfa);
        let stats = rescued.dfa_stats().expect("complete rescued DFA");
        assert_eq!(stats.forward_states_before_minimization, 154);
        assert_eq!(stats.forward_states, 19);
        assert_eq!(stats.reverse_states, 18);
        let report = rescued
            .determinization_report()
            .expect("rescued determinization receipt");
        assert_eq!(report.effective_limits.max_states, 256);
        assert_eq!(report.decline, None);
        assert!(report.work_completed <= report.effective_limits.max_work);
        let ordered_rescue_probe = match dfa::determinize_current_ordered(
            &rescued.raw,
            true,
            DeterminizeLimits {
                max_states: 256,
                ..DeterminizeLimits::default()
            },
        )
        .expect("ordered rescue probe")
        {
            DeterminizeOutcome::Declined { report, .. } => report,
            DeterminizeOutcome::Complete { .. } => {
                panic!("ordered rescue probe unexpectedly completed")
            }
        };
        assert_eq!(
            report.work_completed,
            ordered_rescue_probe
                .work_completed
                .checked_add(stats.build_work)
                .expect("aggregate rescue work")
        );

        let fresh_bytes = rescued.serialize().expect("serialize pruned DFA");
        let fresh_restored = CompiledProgram::deserialize(&fresh_bytes)
            .expect("deserialize canonical pruned DFA");
        assert_eq!(fresh_restored.serialize().unwrap(), fresh_bytes);

        // At the final `z`, both starts can produce the selected end. Endpoint
        // containment is enough to quotient the forward machine, but it is
        // not permission to report the retained lower-priority start. Span
        // must still recover start zero from the untouched reverse graph.
        let start_witness = b"bbz";
        assert_eq!(
            rescued
                .search(start_witness, SearchWindow::full(start_witness))
                .unwrap(),
            MatchResult::Span(Some((0, 3)))
        );
        assert_eq!(
            legacy_restored
                .search(start_witness, SearchWindow::full(start_witness))
                .unwrap(),
            MatchResult::Span(Some((0, 3)))
        );

        let aggregate_work = report.work_completed;
        let exact_work = program(
            pattern,
            OutputContract::Span,
            CompileMode::Optimizing,
            DeterminizeLimits {
                max_states: 256,
                max_work: aggregate_work,
                ..DeterminizeLimits::default()
            },
        );
        assert_eq!(exact_work.engine_kind(), EngineKind::OrderedDfa);
        assert_eq!(exact_work.dfa_stats(), Some(stats));

        let below_work_limit = aggregate_work.checked_sub(1).expect("nonzero DFA work");
        let below_work = program(
            pattern,
            OutputContract::Span,
            CompileMode::Optimizing,
            DeterminizeLimits {
                max_states: 256,
                max_work: below_work_limit,
                ..DeterminizeLimits::default()
            },
        );
        assert_eq!(below_work.engine_kind(), EngineKind::OrderedNfa);
        let below_work_report = below_work
            .determinization_report()
            .expect("one-below endpoint proof receipt");
        assert!(below_work_report.decline.is_some());
        assert_eq!(below_work_report.work_completed, below_work_limit);
        assert!(below_work_report.work_completed <= below_work_report.effective_limits.max_work);

        let below_limits = DeterminizeLimits {
            max_states: 153,
            ..DeterminizeLimits::default()
        };
        let below = program(
            pattern,
            OutputContract::Span,
            CompileMode::Optimizing,
            below_limits,
        );
        assert_eq!(below.engine_kind(), EngineKind::OrderedNfa);
        assert_eq!(
            below.engine_selection_reason(),
            Some(EngineSelectionReason::DeterminizationResourceLimit)
        );
        let decline = below
            .determinization_report()
            .and_then(|report| report.decline)
            .expect("explicit lower state limit must decline");
        assert_eq!(
            decline.stage,
            dfa::DeterminizationStage::ForwardSubsetConstruction
        );
        assert_eq!(
            decline.resource,
            dfa::DeterminizationResource::States {
                limit: 153,
                required: 154,
            }
        );
        assert_eq!(decline.states_completed, 153);

        let ordered_partial = match dfa::determinize_current_ordered(&below.raw, true, below_limits)
            .expect("direct current partial construction")
        {
            DeterminizeOutcome::Declined {
                partial: Some(partial),
                ..
            } => partial,
            _ => panic!("direct legacy construction did not retain a partial"),
        };
        assert_eq!(below.partial_dfa(), Some(&ordered_partial));
        assert!(
            below
                .determinization_report()
                .expect("aggregate failed-rescue report")
                .work_completed
                <= below_limits.max_work
        );
    }

    #[test]
    fn endpoint_dominance_rescue_matches_ordered_nfa_on_generated_windows() {
        let limits = DeterminizeLimits {
            max_states: 256,
            ..DeterminizeLimits::default()
        };
        let mut haystacks = generated_byte_strings(&[b'a', b'b', b'c', b'x', b'z'], 4);
        haystacks.extend([
            b"bbz".to_vec(),
            b"bbzbbz".to_vec(),
            b"cabababababababaz".to_vec(),
            b"xxbbbbbbbbbbbbbbbbzxx".to_vec(),
        ]);
        for pattern in [
            r"[b-c][a-b]{1,16}z",
            r"[b-c][a-b]{1,16}?z",
            r"[b-c][a-b]{1,16}z?",
            r"[b-c][a-b]{1,16}z??",
        ] {
            for output in [OutputContract::SelectedEnd, OutputContract::Span] {
                let optimized = program(pattern, output, CompileMode::Optimizing, limits);
                let reference = program(
                    pattern,
                    output,
                    CompileMode::Fast,
                    DeterminizeLimits::default(),
                );
                if pattern.ends_with('z') {
                    assert_eq!(optimized.engine_kind(), EngineKind::OrderedDfa);
                }
                for haystack in &haystacks {
                    for start in 0..=haystack.len() {
                        for end in start..=haystack.len() {
                            let window = SearchWindow::new(start, end);
                            assert_eq!(
                                optimized.search(haystack, window).unwrap(),
                                reference.search(haystack, window).unwrap(),
                                "{pattern:?}/{output:?}/{haystack:?}/{start}..{end}"
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn default_budget_rescues_endpoint_priority_explosion() {
        // One more bounded repetition doubles the historical ordered subset
        // construction and exhausts the default state budget before Span can
        // build its reverse machine. The same graph-derived proof used by the
        // explicit low-limit test must rescue this ordinary default request.
        let pattern = r"[b-c][a-b]{1,17}z";
        let limits = DeterminizeLimits::default();
        let optimized = program(
            pattern,
            OutputContract::Span,
            CompileMode::Optimizing,
            limits,
        );
        assert!(matches!(
            dfa::determinize(&optimized.raw, true, limits)
                .expect("historical default construction"),
            DeterminizeOutcome::Declined { .. }
        ));
        assert_eq!(optimized.engine_kind(), EngineKind::OrderedDfa);
        let stats = optimized.dfa_stats().expect("default rescued DFA");
        assert!(stats.forward_states_before_minimization < 1_024);
        assert!(stats.forward_states < stats.forward_states_before_minimization);
        let report = optimized
            .determinization_report()
            .expect("default rescue report");
        assert_eq!(report.decline, None);
        assert!(report.work_completed <= report.effective_limits.max_work);
        let bytes = optimized.serialize().expect("serialize default rescue");
        let restored = CompiledProgram::deserialize(&bytes)
            .expect("deserialize canonical default rescue");
        assert_eq!(restored.serialize().unwrap(), bytes);
    }

    #[test]
    fn exists_canonical_subsets_avoid_priority_only_resource_fallback() {
        // Every alternative is semantically just another way to keep a
        // Boolean match alive, but the ordered construction retains their
        // Thompson-priority permutations. The Exists construction must stay
        // bounded by language subsets rather than that unobservable order.
        let pattern = r"(?:a|ab|ba|b){12}z";
        let limits = DeterminizeLimits {
            max_states: 64,
            ..DeterminizeLimits::default()
        };
        let optimized = program(
            pattern,
            OutputContract::Exists,
            CompileMode::Optimizing,
            limits,
        );
        assert_eq!(optimized.engine_kind(), EngineKind::OrderedDfa);
        let stats = optimized.dfa_stats().expect("complete existential DFA");
        assert!(stats.forward_states_before_minimization <= limits.max_states);

        assert!(matches!(
            dfa::determinize(&optimized.raw, false, limits).expect("ordered determinization"),
            DeterminizeOutcome::Declined { .. }
        ));

        let serialized = optimized.serialize().expect("serialize existential DFA");
        let restored = CompiledProgram::deserialize(&serialized)
            .expect("deserialize canonical existential DFA");
        assert_eq!(restored.serialize().unwrap(), serialized);
        let ProgramEngine::OrderedDfa(existential_machine) = &optimized.engine else {
            panic!("existential compilation did not retain its complete machine");
        };
        assert!(
            existential_machine
                .validate_canonical(
                    &optimized.raw,
                    OutputContract::SelectedEnd,
                    DfaReplayOrder::DescendingEstimatedClassFrequency,
                )
                .is_err(),
            "existential terminal edges are not canonical for endpoint selection"
        );

        // Artifacts emitted before Exists subset canonicalization remain
        // readable through the legacy ordered canonical-validation path.
        let mut legacy = program(
            pattern,
            OutputContract::Exists,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        let legacy_machine = match dfa::determinize(
            &legacy.raw,
            false,
            DeterminizeLimits::default(),
        )
        .expect("legacy ordered determinization")
        {
            DeterminizeOutcome::Complete { machine, .. } => machine,
            DeterminizeOutcome::Declined { report, .. } => {
                panic!("legacy ordered determinization declined: {report:?}")
            }
        };
        assert!(
            legacy_machine.stats().forward_states_before_minimization
                > stats.forward_states_before_minimization
        );
        legacy.engine = ProgramEngine::OrderedDfa(legacy_machine);
        legacy.engine_selection_reason = Some(EngineSelectionReason::CompleteDfa);
        let legacy_bytes = legacy.serialize().expect("serialize legacy Exists DFA");
        let legacy_restored = CompiledProgram::deserialize(&legacy_bytes)
            .expect("deserialize legacy ordered Exists DFA");
        assert_eq!(legacy_restored.serialize().unwrap(), legacy_bytes);

        let small = r"(?:a|ab|ba|b){4}z";
        let existential = program(
            small,
            OutputContract::Exists,
            CompileMode::Optimizing,
            DeterminizeLimits::default(),
        );
        let reference = program(
            small,
            OutputContract::Exists,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        for haystack in generated_byte_strings(b"abz", 5) {
            for start in 0..=haystack.len() {
                for end in start..=haystack.len() {
                    let window = SearchWindow::new(start, end);
                    assert_eq!(
                        existential.search(&haystack, window).unwrap(),
                        reference.search(&haystack, window).unwrap(),
                        "{haystack:?}/{start}..{end}"
                    );
                }
            }
        }
    }

    #[test]
    fn exists_partial_wire_accepts_frequency_mass_and_fifo_frontier_orders() {
        let pattern = r"a+Q|[b-c][a-b]{1,5}(?:x+|y+)";
        let limits = DeterminizeLimits {
            max_states: 8,
            ..DeterminizeLimits::default()
        };
        let semantic = program(
            pattern,
            OutputContract::Exists,
            CompileMode::Optimizing,
            limits,
        );
        assert!(semantic.partial_dfa().is_some());
        let semantic_bytes = semantic.serialize().expect("serialize semantic partial");
        assert_eq!(
            u32::from_le_bytes(semantic_bytes[8..12].try_into().unwrap()),
            PROGRAM_FORMAT_VERSION_V8
        );
        let semantic_restored = CompiledProgram::deserialize(&semantic_bytes)
            .expect("deserialize semantic partial");
        assert_eq!(semantic_restored.serialize().unwrap(), semantic_bytes);

        let mass = class_mass_program(pattern, OutputContract::Exists, limits);
        assert!(mass.partial_dfa().is_some());
        let mass_bytes = mass.serialize().expect("serialize class-mass partial");
        assert_eq!(
            u32::from_le_bytes(mass_bytes[8..12].try_into().unwrap()),
            PROGRAM_FORMAT_VERSION_V6
        );
        let mass_restored = CompiledProgram::deserialize(&mass_bytes)
            .expect("deserialize class-mass partial");
        assert_eq!(mass_restored.serialize().unwrap(), mass_bytes);
        assert_eq!(
            mass_restored.optimization_sidecar.partial_replay_order(),
            Some(DfaReplayOrder::DescendingClassMass),
        );

        // Some graphs legitimately retain the same prefix under both ranked
        // orders. Use a graph whose equal-mass branches are deliberately
        // distinguished by the stable frequency model when checking that a
        // differing payload cannot claim the other replay identity.
        let replay_raw = frequency_replay_distinguishing_raw();
        let replay_limits = DeterminizeLimits {
            max_states: 4,
            ..DeterminizeLimits::default()
        };
        let frequency_replay = raw_program(
            &replay_raw,
            OutputContract::Exists,
            CompileMode::Optimizing,
            replay_limits,
        );
        let mass_replay = with_class_mass_determinization(
            raw_program(
                &replay_raw,
                OutputContract::Exists,
                CompileMode::Fast,
                DeterminizeLimits::default(),
            ),
            OutputContract::Exists,
            replay_limits,
        );
        assert!(frequency_replay.partial_dfa().is_some());
        assert!(mass_replay.partial_dfa().is_some());
        let frequency_replay_bytes = frequency_replay.serialize().unwrap();
        let mass_replay_bytes = mass_replay.serialize().unwrap();
        let mut frequency_claiming_mass = frequency_replay_bytes.clone();
        frequency_claiming_mass[8..12]
            .copy_from_slice(&PROGRAM_FORMAT_VERSION_V6.to_le_bytes());
        assert!(CompiledProgram::deserialize(&frequency_claiming_mass).is_err());
        let mut mass_claiming_frequency = mass_replay_bytes.clone();
        mass_claiming_frequency[8..12]
            .copy_from_slice(&PROGRAM_FORMAT_VERSION_V8.to_le_bytes());
        assert!(CompiledProgram::deserialize(&mass_claiming_frequency).is_err());

        let mut legacy = program(
            pattern,
            OutputContract::Exists,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        let (legacy_partial, legacy_report) =
            match dfa::determinize(&legacy.raw, false, limits).expect("legacy partial build") {
                DeterminizeOutcome::Declined {
                    report,
                    partial: Some(partial),
                    ..
                } => (partial, report),
                DeterminizeOutcome::Complete { .. } => {
                    panic!("legacy limits unexpectedly completed")
                }
                DeterminizeOutcome::Declined { partial: None, .. } => {
                    panic!("legacy limits retained no completed row")
                }
            };
        legacy.optimization_sidecar = ProgramOptimizationSidecar::Partial(Box::new(
            ReplayPartialDfa {
                partial: legacy_partial,
                replay_order: DfaReplayOrder::Fifo,
            },
        ));
        legacy.engine_selection_reason = Some(EngineSelectionReason::DeterminizationResourceLimit);
        legacy.determinization_report = Some(legacy_report);
        assert!(
            legacy
                .automaton
                .try_enable_epsilon_closure_dispatch()
                .expect("derive current graph marker for legacy FIFO partial")
        );
        let legacy_bytes = legacy.serialize().expect("serialize legacy partial");
        assert_eq!(
            u32::from_le_bytes(legacy_bytes[8..12].try_into().unwrap()),
            PROGRAM_FORMAT_VERSION_V5
        );
        assert_ne!(legacy_bytes, semantic_bytes);
        assert_ne!(legacy_bytes, mass_bytes);
        assert_ne!(mass_bytes, semantic_bytes);
        let legacy_restored = CompiledProgram::deserialize(&legacy_bytes)
            .expect("deserialize legacy ordered partial");
        assert_eq!(legacy_restored.serialize().unwrap(), legacy_bytes);
        assert_eq!(
            legacy_restored.optimization_sidecar.partial_replay_order(),
            Some(DfaReplayOrder::Fifo),
        );
        assert!(legacy_restored.automaton.has_epsilon_closure_dispatch());

        let reference = program(
            pattern,
            OutputContract::Exists,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        let mut semantic_workspace = semantic_restored.prepare_workspace().unwrap();
        let mut mass_workspace = mass_restored.prepare_workspace().unwrap();
        let mut legacy_workspace = legacy_restored.prepare_workspace().unwrap();
        for haystack in [
            b"".as_slice(),
            b"xxcbbbbxyy",
            b"bbbbbbbbbbbb",
            b"xxbaaaayyy",
            b"aaaQ",
        ] {
            let window = SearchWindow::full(haystack);
            let expected = reference.search(haystack, window).unwrap();
            assert_eq!(
                semantic_restored
                    .search_with_retained_partial_workspace(
                        haystack,
                        window,
                        &mut semantic_workspace,
                    )
                    .unwrap(),
                expected
            );
            assert_eq!(
                mass_restored
                    .search_with_retained_partial_workspace(
                        haystack,
                        window,
                        &mut mass_workspace,
                    )
                    .unwrap(),
                expected
            );
            assert_eq!(
                legacy_restored
                    .search_with_retained_partial_workspace(
                        haystack,
                        window,
                        &mut legacy_workspace,
                    )
                    .unwrap(),
                expected
            );
        }
        assert!(semantic_workspace.partial.as_deref().unwrap().state.resumed > 0);
        assert!(mass_workspace.partial.as_deref().unwrap().state.resumed > 0);
        assert!(legacy_workspace.partial.as_deref().unwrap().state.resumed > 0);
    }

    #[test]
    fn complete_frequency_v8_mass_v6_and_fifo_v4_are_all_output_general() {
        let pattern = r"(?:a|bb)+Q";
        let haystacks = generated_byte_strings(&[0, b'a', b'b', b'Q', 255], 5);
        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let ranked = program(
                pattern,
                output,
                CompileMode::Optimizing,
                DeterminizeLimits::default(),
            );
            assert_eq!(ranked.engine_kind(), EngineKind::OrderedDfa);
            assert_eq!(
                ranked.engine.replay_order(),
                Some(DfaReplayOrder::DescendingEstimatedClassFrequency),
            );
            let ranked_bytes = ranked.serialize().expect("serialize frequency-ranked DFA");
            assert_eq!(
                u32::from_le_bytes(ranked_bytes[8..12].try_into().unwrap()),
                PROGRAM_FORMAT_VERSION_V8,
            );
            let ranked_restored = CompiledProgram::deserialize(&ranked_bytes)
                .expect("deserialize frequency-ranked DFA");
            assert_eq!(ranked_restored.serialize().unwrap(), ranked_bytes);

            let mass = class_mass_program(pattern, output, DeterminizeLimits::default());
            assert_eq!(mass.engine_kind(), EngineKind::OrderedDfa);
            let mass_bytes = mass.serialize().expect("serialize class-mass DFA");
            assert_eq!(
                u32::from_le_bytes(mass_bytes[8..12].try_into().unwrap()),
                PROGRAM_FORMAT_VERSION_V6,
            );
            let mass_restored = CompiledProgram::deserialize(&mass_bytes)
                .expect("deserialize class-mass DFA");
            assert_eq!(mass_restored.serialize().unwrap(), mass_bytes);
            assert_eq!(
                mass_restored.engine.replay_order(),
                Some(DfaReplayOrder::DescendingClassMass),
            );
            assert_ne!(ranked_bytes, mass_bytes);

            let mut wrong_replay = ranked_bytes.clone();
            wrong_replay[8..12].copy_from_slice(&PROGRAM_FORMAT_VERSION_V4.to_le_bytes());
            assert!(
                CompiledProgram::deserialize(&wrong_replay).is_err(),
                "V8 frequency work/table identity authenticated as V4 FIFO for {output:?}",
            );

            let mut fifo = program(
                pattern,
                output,
                CompileMode::Fast,
                DeterminizeLimits::default(),
            );
            let wants_span = output == OutputContract::Span && fifo.exact_match_width.is_none();
            let fifo_machine = match dfa::determinize(
                &fifo.raw,
                wants_span,
                DeterminizeLimits::default(),
            )
            .expect("legacy FIFO complete construction")
            {
                DeterminizeOutcome::Complete { machine, .. } => machine,
                DeterminizeOutcome::Declined { report, .. } => {
                    panic!("legacy FIFO fixture declined: {report:?}")
                }
            };
            fifo.engine = ProgramEngine::OrderedDfa(fifo_machine);
            fifo.engine_selection_reason = Some(EngineSelectionReason::CompleteDfa);
            let fifo_bytes = fifo.serialize().expect("serialize FIFO DFA");
            assert_eq!(
                u32::from_le_bytes(fifo_bytes[8..12].try_into().unwrap()),
                PROGRAM_FORMAT_VERSION_V4,
            );
            let fifo_restored =
                CompiledProgram::deserialize(&fifo_bytes).expect("deserialize FIFO DFA");
            assert_eq!(fifo_restored.serialize().unwrap(), fifo_bytes);
            assert_ne!(ranked_bytes, fifo_bytes);

            let reference = program(
                pattern,
                output,
                CompileMode::Fast,
                DeterminizeLimits::default(),
            );
            for haystack in &haystacks {
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        let expected = reference.search(haystack, window).unwrap();
                        assert_eq!(
                            ranked_restored.search(haystack, window).unwrap(),
                            expected,
                            "ranked/{output:?}/{haystack:?}/{window:?}",
                        );
                        assert_eq!(
                            mass_restored.search(haystack, window).unwrap(),
                            expected,
                            "class-mass/{output:?}/{haystack:?}/{window:?}",
                        );
                        assert_eq!(
                            fifo_restored.search(haystack, window).unwrap(),
                            expected,
                            "FIFO/{output:?}/{haystack:?}/{window:?}",
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn resource_decline_retains_canonical_partial_rows_for_every_contract() {
        // The disjoint terminal alternatives deliberately leave no suffix
        // sidecar eligible, so every missing retained row exercises the
        // authenticated K0 continuation rather than another accelerator.
        let pattern = r"a+Q|[b-c][a-b]{1,5}(?:x+|y+)";
        let mut haystacks = generated_byte_strings(&[0, b'a', b'b', b'c', b'x', b'z', 255], 5);
        haystacks.extend([
            b"xxcbbbbxyy".to_vec(),
            b"bbbbbbbbbbbb".to_vec(),
            b"xxbaaaayyy".to_vec(),
            b"aaaQ".to_vec(),
            vec![b'a'; 257],
            {
                let mut value = vec![b'x'; 255];
                value.extend_from_slice(b"cbbbbx");
                value
            },
        ]);
        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            // Keep both endpoint attempts below their complete state count so
            // this remains a retained-prefix test after endpoint rescue was
            // added. Exists already needs the same tighter ceiling to retain
            // its canonical set-valued K0-resumable prefix.
            let limits = DeterminizeLimits {
                // Span needs enough retained rows to complete at least one
                // selected-end probe and exercise reverse recovery. Both
                // endpoint routes still decline below their complete size.
                max_states: if output == OutputContract::Exists {
                    8
                } else {
                    16
                },
                ..DeterminizeLimits::default()
            };
            let partial = program(pattern, output, CompileMode::Optimizing, limits);
            assert_eq!(partial.engine_kind(), EngineKind::OrderedNfa);
            let retained = partial
                .partial_dfa()
                .unwrap_or_else(|| panic!("missing retained rows for {output:?}"));
            let (complete_rows, discovered_states) = retained.retained_dimensions();
            assert!(complete_rows > 0);
            assert!(complete_rows < discovered_states);
            let report = partial.determinization_report().unwrap();
            assert!(report.decline.is_some(), "{output:?}");
            assert!(partial.nfa_mandatory_suffix.is_none(), "{output:?}");
            let bit_parallel_stats = partial
                .bit_parallel_exists_stats()
                .unwrap_or_else(|| panic!("missing retained-row existence machine: {output:?}"));
            assert_eq!(
                partial.native_bit_parallel_exists_view().is_some(),
                output == OutputContract::Exists,
                "endpoint oracle entered the standalone native Exists ABI"
            );

            let bytes = partial.serialize().expect("serialize partial DFA");
            assert_eq!(
                u32::from_le_bytes(bytes[8..12].try_into().unwrap()),
                PROGRAM_FORMAT_VERSION_V8
            );
            assert_ne!(bytes[15] & PROGRAM_FLAG_NFA_PARTIAL_DFA, 0);
            assert_ne!(
                bytes[15] & PROGRAM_FLAG_NFA_EPSILON_CLOSURE_DISPATCH,
                0
            );
            let restored = CompiledProgram::deserialize(&bytes).expect("restore partial DFA");
            assert_eq!(
                restored.optimization_sidecar.partial_replay_order(),
                Some(DfaReplayOrder::DescendingEstimatedClassFrequency)
            );
            assert_eq!(restored.serialize().unwrap(), bytes);
            assert_eq!(
                restored.bit_parallel_exists_stats(),
                Some(bit_parallel_stats),
                "wire reconstruction omitted the existence machine for {output:?}"
            );

            let reference = program(
                pattern,
                output,
                CompileMode::Fast,
                DeterminizeLimits::default(),
            );
            let mut partial_workspace = partial.prepare_workspace().unwrap();
            let mut restored_workspace = restored.prepare_workspace().unwrap();
            let mut reference_workspace = reference.prepare_workspace().unwrap();
            for haystack in &haystacks {
                let haystack = haystack.as_slice();
                for start in 0..=haystack.len() {
                    for end in start..=haystack.len() {
                        let window = SearchWindow::new(start, end);
                        let expected = reference
                            .search_with_workspace(haystack, window, &mut reference_workspace)
                            .unwrap();
                        assert_eq!(
                            partial
                                .search_with_retained_partial_workspace(
                                    haystack,
                                    window,
                                    &mut partial_workspace,
                                )
                                .unwrap(),
                            expected,
                            "fresh {output:?} {haystack:?} {start}..{end}"
                        );
                        assert_eq!(
                            restored
                                .search_with_retained_partial_workspace(
                                    haystack,
                                    window,
                                    &mut restored_workspace,
                                )
                                .unwrap(),
                            expected,
                            "restored {output:?} {haystack:?} {start}..{end}"
                        );
                    }
                }
            }
            assert!(
                partial_workspace.partial.as_deref().unwrap().state.resumed > 0,
                "fresh {output:?} never exercised stateful K0 resume"
            );
            assert!(
                restored_workspace.partial.as_deref().unwrap().state.resumed > 0,
                "restored {output:?} never exercised stateful K0 resume"
            );
            if output == OutputContract::Span {
                assert!(
                    partial_workspace
                        .partial
                        .as_deref()
                        .unwrap()
                        .state
                        .reverse_recovered
                        > 0,
                    "fresh Span never exercised selected-end reverse recovery"
                );
                assert!(
                    restored_workspace
                        .partial
                        .as_deref()
                        .unwrap()
                        .state
                        .reverse_recovered
                        > 0,
                    "restored Span never exercised selected-end reverse recovery"
                );
            }
        }
    }

    #[test]
    fn pike_only_variable_span_declines_selected_end_accelerators_before_source() {
        let pattern = r"a+Q|[b-c][a-b]{1,5}(?:x+|y+)";
        let compiled = program(
            pattern,
            OutputContract::Span,
            CompileMode::Optimizing,
            DeterminizeLimits {
                max_states: 16,
                ..DeterminizeLimits::default()
            },
        );
        assert_eq!(compiled.engine_kind(), EngineKind::OrderedNfa);
        assert_eq!(compiled.exact_match_width(), None);
        assert!(compiled.partial_dfa().is_some());

        let mut haystack = vec![b'x'; PARTIAL_DFA_MIN_INPUT_BYTES + 32];
        haystack.extend_from_slice(b"aaaQ");
        let window = SearchWindow::full(&haystack);
        let expected = compiled.search(&haystack, window).unwrap();
        assert_eq!(
            expected,
            MatchResult::Span(Some((haystack.len() - 4, haystack.len())))
        );

        let mut workspace = compiled.prepare_workspace().unwrap();
        workspace.nfa = Some(
            K0Workspace::new(&compiled.automaton, WorkspaceLimits::unlimited()).unwrap(),
        );
        assert!(!compiled.selected_end_acceleration_has_reverse_only_recovery(&workspace));
        assert!(
            !compiled
                .prepared_partial_should_enter_with_workspace(&mut workspace, haystack.len())
                .unwrap()
        );
        assert_eq!(
            compiled
                .search_optimized_with_workspace(&haystack, window, &mut workspace)
                .unwrap(),
            expected
        );
        let partial = &workspace.partial.as_deref().unwrap().state;
        assert_eq!(partial.resumed, 0);
        assert_eq!(partial.reverse_recovered, 0);
        assert_eq!(partial.forward_start_certified, 0);
        assert_eq!(partial.complete_accelerated, 0);

        assert_eq!(
            compiled
                .preflight_retained_partial_with_workspace(
                    &haystack,
                    window,
                    &mut workspace,
                    compiled.artifact_identity(),
                )
                .unwrap(),
            RetainedPartialPreflight::Complete(expected)
        );
        let partial = &workspace.partial.as_deref().unwrap().state;
        assert_eq!(partial.resumed, 0);
        assert_eq!(partial.reverse_recovered, 0);

        let mut static_workspace = compiled.prepare_workspace().unwrap();
        static_workspace.nfa = Some(
            K0Workspace::new(&compiled.automaton, WorkspaceLimits::unlimited()).unwrap(),
        );
        assert!(
            compiled
                .compiler_private_static_prefix_preflight_may_search_with_workspace(
                    &static_workspace,
                    haystack.len(),
                )
                .unwrap()
        );
        assert_eq!(
            compiled
                .preflight_static_prefix_complete_proofs_with_workspace(
                    &haystack,
                    window,
                    &mut static_workspace,
                    compiled.artifact_identity(),
                )
                .unwrap(),
            RetainedPartialPreflight::Complete(expected)
        );

        let mut dynamic_workspace = compiled.prepare_workspace().unwrap();
        dynamic_workspace.nfa = Some(
            K0Workspace::new(&compiled.automaton, WorkspaceLimits::unlimited()).unwrap(),
        );
        assert_eq!(
            compiled
                .preflight_dynamic_native_rows_with_workspace(
                    &haystack,
                    window,
                    &mut dynamic_workspace,
                    compiled.artifact_identity(),
                )
                .unwrap(),
            (RetainedPartialPreflight::Complete(expected), 0, 0)
        );
    }

    #[test]
    fn repeated_retained_resume_values_match_every_output_at_nonzero_windows() {
        let pattern = r"a+Q|[b-c][a-b]{1,5}(?:x+|y+)";
        let mut sources = Vec::new();
        for tail in [
            b"cbbbbx".as_slice(),
            b"cbbbbbyyyyy".as_slice(),
            b"baaaaaxxxxx".as_slice(),
        ] {
            let mut source = vec![b'!'; 3];
            source.extend(core::iter::repeat_n(b'x', PARTIAL_DFA_MIN_INPUT_BYTES));
            source.extend_from_slice(tail);
            source.push(b'!');
            sources.push(source);
        }
        let mut repeated = 0_usize;
        for output in [
            OutputContract::Exists,
            OutputContract::SelectedEnd,
            OutputContract::Span,
        ] {
            let limits = DeterminizeLimits {
                max_states: if output == OutputContract::Exists {
                    8
                } else {
                    16
                },
                ..DeterminizeLimits::default()
            };
            let mut partial = program(pattern, output, CompileMode::Optimizing, limits);
            assert!(partial.partial_dfa().is_some(), "{output:?}");
            // This test owns the retained continuation itself. Complete
            // suffix/cut proofs are independently covered and would hide the
            // warm resume boundary under test.
            partial.nfa_mandatory_suffix = None;
            partial.nfa_mandatory_cut = None;
            let reference = program(
                pattern,
                output,
                CompileMode::Fast,
                DeterminizeLimits::default(),
            );
            let mut found_witness = false;
            for source in &sources {
                let window = SearchWindow::new(3, source.len() - 1);
                let expected = reference.search(source, window).unwrap();
                let mut workspace = partial.prepare_workspace().unwrap();
                assert_eq!(
                    partial
                        .search_with_retained_partial_workspace(source, window, &mut workspace)
                        .unwrap(),
                    expected,
                    "cold retained {output:?}"
                );
                let resumed = workspace.partial.as_deref().unwrap().state.resumed;
                if resumed == 0 {
                    continue;
                }
                assert_eq!(
                    partial
                        .search_with_retained_partial_workspace(source, window, &mut workspace)
                        .unwrap(),
                    expected,
                    "warm retained {output:?}"
                );
                let state = &workspace.partial.as_deref().unwrap().state;
                assert_eq!(
                    state.resumed, resumed,
                    "the repeated {output:?} witness was not completed by warm rows"
                );
                assert_eq!(state.consecutive_fallbacks, 0);
                assert_eq!(state.bypass_remaining, 0);
                found_witness = true;
                repeated = repeated.checked_add(1).unwrap();
                break;
            }
            assert!(
                found_witness,
                "no nonzero-window retained-hole witness for {output:?}"
            );
        }
        assert_eq!(repeated, 3);
    }

    #[test]
    fn nullable_retained_span_keeps_the_proved_window_start() {
        // The nullable branch fixes the selected start at the authoritative
        // window boundary, while the overlapping positive branch creates
        // enough ordered subsets to exercise a genuinely retained prefix.
        let pattern = r"(?:[b-c][a-b]{1,16}z)?";
        let mut limited = (2..=128)
            .find_map(|max_states| {
                let candidate = program(
                    pattern,
                    OutputContract::Span,
                    CompileMode::Optimizing,
                    DeterminizeLimits {
                        max_states,
                        ..DeterminizeLimits::default()
                    },
                );
                let retained_nullable = candidate
                    .partial_dfa()
                    .is_some_and(PartialDfa::initial_pending);
                retained_nullable.then_some(candidate)
            })
            .expect("nullable graph must retain a canonical row prefix");
        assert_eq!(limited.exact_match_width, None);
        // Isolate retained execution from unrelated complete no-match
        // sidecars. The start proof itself depends only on the initial ordered
        // subset and remains valid for every source/window.
        limited.nfa_mandatory_suffix = None;
        limited.nfa_mandatory_cut = None;

        let reference = program(
            pattern,
            OutputContract::Span,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        let mut limited_workspace = limited.prepare_workspace().unwrap();
        let mut reference_workspace = reference.prepare_workspace().unwrap();
        let haystacks = generated_byte_strings(&[b'a', b'b', b'x'], 4);
        for haystack in &haystacks {
            for start in 0..=haystack.len() {
                for end in start..=haystack.len() {
                    let window = SearchWindow::new(start, end);
                    let expected = reference
                        .search_with_workspace(haystack, window, &mut reference_workspace)
                        .unwrap();
                    assert_eq!(
                        limited
                            .search_with_retained_partial_workspace(
                                haystack,
                                window,
                                &mut limited_workspace,
                            )
                            .unwrap(),
                        expected,
                        "nullable retained Span mismatch for {haystack:?} in {start}..{end}"
                    );
                }
            }
        }
        let mut warmed_initial_pending = false;
        for repeated_b in 1..=16 {
            let mut haystack = vec![b'!'; 3];
            haystack.push(b'c');
            haystack.extend(core::iter::repeat_n(b'b', repeated_b));
            haystack.push(b'z');
            haystack.resize(3 + PARTIAL_DFA_MIN_INPUT_BYTES + 32, b'x');
            let window = SearchWindow::new(3, haystack.len());
            let expected = reference.search(&haystack, window).unwrap();
            assert!(matches!(
                expected,
                MatchResult::Span(Some((start, _))) if start == window.start
            ));
            let mut workspace = limited.prepare_workspace().unwrap();
            assert_eq!(
                limited
                    .search_with_retained_partial_workspace(&haystack, window, &mut workspace)
                    .unwrap(),
                expected
            );
            let resumed = workspace.partial.as_deref().unwrap().state.resumed;
            if resumed == 0 {
                continue;
            }
            assert_eq!(
                limited
                    .search_with_retained_partial_workspace(&haystack, window, &mut workspace)
                    .unwrap(),
                expected
            );
            let state = &workspace.partial.as_deref().unwrap().state;
            assert_eq!(
                state.resumed, resumed,
                "the repeated initial-pending Span did not complete through warm rows"
            );
            assert_eq!(state.consecutive_fallbacks, 0);
            assert_eq!(state.bypass_remaining, 0);
            assert_eq!(
                state.reverse_recovered, 0,
                "initial-pending Span must retain the authoritative window start"
            );
            warmed_initial_pending = true;
            break;
        }
        assert!(
            warmed_initial_pending,
            "nullable retained Span produced no repeated initial-pending hole"
        );
        let state = &limited_workspace.partial.as_deref().unwrap().state;
        assert_eq!(
            state.reverse_recovered, 0,
            "nullable retained completions must not invoke reverse recovery"
        );
    }

    #[test]
    fn retained_forward_start_certificate_is_exact_after_priority_commit() {
        // The short alternative can commit a selected match entirely inside
        // retained rows. The overlapping bounded alternative forces a later
        // subset-construction decline, so the same partial artifact also owns
        // authenticated K0 holes on other inputs.
        let pattern = r"a|[b-c][a-b]{1,10}z";
        let probe = b"axxx";
        let mut limited = (2..=64)
            .find_map(|max_states| {
                let candidate = program(
                    pattern,
                    OutputContract::Span,
                    CompileMode::Optimizing,
                    DeterminizeLimits {
                        max_states,
                        ..DeterminizeLimits::default()
                    },
                );
                let Some(partial) = candidate.partial_dfa() else {
                    return None;
                };
                let (prefix_plan, supported) =
                    PartialDfaPrefixPlan::derive(candidate.anchored_prefix.sets());
                if !supported {
                    return None;
                }
                let certified = matches!(
                    partial.selected_span_end(
                        probe,
                        0,
                        probe.len(),
                        candidate.anchored_prefix.sets(),
                        prefix_plan,
                    ),
                    Ok(PartialDfaResult::Complete(selection))
                        if selection.end.is_some() && selection.start.is_some()
                );
                certified.then_some(candidate)
            })
            .expect("fixture must retain a start-certified forward path");
        limited.nfa_mandatory_suffix = None;
        limited.nfa_mandatory_cut = None;
        let serialized = limited.serialize().unwrap();
        let mut restored = CompiledProgram::deserialize(&serialized).unwrap();
        restored.nfa_mandatory_suffix = None;
        restored.nfa_mandatory_cut = None;
        let reference = program(
            pattern,
            OutputContract::Span,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        let mut limited_workspace = limited.prepare_workspace().unwrap();
        let mut restored_workspace = restored.prepare_workspace().unwrap();
        limited_workspace.nfa = Some(
            K0Workspace::new(&limited.automaton, WorkspaceLimits::unlimited()).unwrap(),
        );
        restored_workspace.nfa = Some(
            K0Workspace::new(&restored.automaton, WorkspaceLimits::unlimited()).unwrap(),
        );
        assert!(!limited
            .selected_end_acceleration_has_reverse_only_recovery(&limited_workspace));
        assert!(!restored
            .selected_end_acceleration_has_reverse_only_recovery(&restored_workspace));
        let mut reference_workspace = reference.prepare_workspace().unwrap();
        let mut haystacks = generated_byte_strings(&[b'a', b'b', b'c', b'x', b'z'], 4);
        haystacks.extend([probe.to_vec(), b"xxax".to_vec(), b"cbbbbbbbbbbz".to_vec()]);
        for haystack in &haystacks {
            for start in 0..=haystack.len() {
                for end in start..=haystack.len() {
                    let window = SearchWindow::new(start, end);
                    let expected = reference
                        .search_with_workspace(haystack, window, &mut reference_workspace)
                        .unwrap();
                    assert_eq!(
                        limited
                            .search_with_retained_partial_workspace(
                                haystack,
                                window,
                                &mut limited_workspace,
                            )
                            .unwrap(),
                        expected,
                        "fresh start certificate mismatch for {haystack:?} in {start}..{end}"
                    );
                    assert_eq!(
                        restored
                            .search_with_retained_partial_workspace(
                                haystack,
                                window,
                                &mut restored_workspace,
                            )
                            .unwrap(),
                        expected,
                        "restored start certificate mismatch for {haystack:?} in {start}..{end}"
                    );
                }
            }
        }
        for workspace in [&limited_workspace, &restored_workspace] {
            assert!(
                workspace
                    .partial
                    .as_deref()
                    .unwrap()
                    .state
                    .forward_start_certified
                    > 0
            );
        }
    }

    #[test]
    fn retained_span_does_not_restart_an_older_initial_subset_provenance() {
        // After the first `a`, the lazy repetition returns to the canonical
        // initial subset. That equality is an endpoint-search restart point,
        // but it does not erase the older ordered start carried by the
        // repetition. The bounded repeated-atom alternative only forces a
        // retained resource decline; it is not part of the semantic witness.
        let pattern = r"(?:a|[c-d][a-b]{1,10}z)*?b";
        let probe = b"ab";
        let mut limited = (2..=128)
            .find_map(|max_states| {
                let candidate = program(
                    pattern,
                    OutputContract::Span,
                    CompileMode::Optimizing,
                    DeterminizeLimits {
                        max_states,
                        ..DeterminizeLimits::default()
                    },
                );
                let partial = candidate.partial_dfa()?;
                let (prefix_plan, supported) =
                    PartialDfaPrefixPlan::derive(candidate.anchored_prefix.sets());
                if !supported {
                    return None;
                }
                matches!(
                    partial.selected_span_end(
                        probe,
                        0,
                        probe.len(),
                        candidate.anchored_prefix.sets(),
                        prefix_plan,
                    ),
                    Ok(PartialDfaResult::Complete(selection))
                        if selection.end == Some(2) && selection.start == Some(0)
                )
                .then_some(candidate)
            })
            .expect("fixture must retain and certify the lazy-star witness");
        limited.nfa_mandatory_suffix = None;
        limited.nfa_mandatory_cut = None;

        let mut workspace = limited.prepare_workspace().unwrap();
        assert_eq!(
            limited
                .search_with_retained_partial_workspace(
                    probe,
                    SearchWindow::full(probe),
                    &mut workspace,
                )
                .unwrap(),
            MatchResult::Span(Some((0, 2)))
        );
        assert!(
            workspace
                .partial
                .as_deref()
                .unwrap()
                .state
                .forward_start_certified
                > 0
        );
    }

    #[test]
    fn general_byte_set_prefix_executes_retained_rows() {
        let pattern = r"[b-f][a-e]{1,10}Z";
        let mut limited = program(
            pattern,
            OutputContract::SelectedEnd,
            CompileMode::Optimizing,
            DeterminizeLimits {
                // A limit just below the historical complete machine is no
                // longer a guaranteed decline: endpoint rescue can finish a
                // smaller, equivalent machine. This ceiling is below both
                // routes while retaining useful canonical rows.
                max_states: 8,
                ..DeterminizeLimits::default()
            },
        );
        let stats = limited
            .partial_dfa_stats()
            .unwrap()
            .expect("retained rows");
        assert!(stats.optimized_entry_supported);
        assert!(stats.complete_rows > 0);
        assert!(stats.resume_frontiers > 0);
        assert_eq!(stats.min_input_bytes, PARTIAL_DFA_MIN_INPUT_BYTES);
        let (prefix_plan, supported) = PartialDfaPrefixPlan::derive(limited.anchored_prefix.sets());
        assert!(supported);
        assert!(prefix_plan.is_some());

        // This test isolates the retained prefix classifier. Complete NFA
        // sidecars are covered separately and now intentionally precede it.
        limited.nfa_mandatory_suffix = None;
        limited.nfa_mandatory_cut = None;

        let mut haystack = vec![b'x'; PARTIAL_DFA_MIN_INPUT_BYTES];
        haystack.extend_from_slice(b"beeeeeeeeeeZ");
        let reference = program(
            pattern,
            OutputContract::SelectedEnd,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        let expected = reference
            .search(&haystack, SearchWindow::full(&haystack))
            .unwrap();
        let mut workspace = limited.prepare_workspace().unwrap();
        assert_eq!(
            limited
                .search_optimized_with_workspace(
                    &haystack,
                    SearchWindow::full(&haystack),
                    &mut workspace,
                )
                .unwrap(),
            expected
        );
        assert!(workspace.partial.as_deref().unwrap().state.resumed > 0);
    }

    #[test]
    fn partial_entry_runs_complete_suffix_before_a_retained_hole() {
        let pattern = r"[b-c][a-b]{1,10}z";
        let limited = program(
            pattern,
            OutputContract::SelectedEnd,
            CompileMode::Optimizing,
            DeterminizeLimits {
                max_states: 32,
                ..DeterminizeLimits::default()
            },
        );
        let partial = limited.partial_dfa().expect("retained rows");
        assert!(limited.nfa_mandatory_suffix.is_some());
        assert!(limited.native_dynamic_rows_view().is_some());
        let (prefix_plan, supported) = PartialDfaPrefixPlan::derive(limited.anchored_prefix.sets());
        assert!(supported);
        let haystack = b"cbbbbbbbbbbz";
        let resume = match partial
            .selected_end(
                haystack,
                0,
                haystack.len(),
                limited.anchored_prefix.sets(),
                prefix_plan,
            )
            .expect("partial probe")
        {
            PartialDfaResult::Resume(resume) => resume,
            PartialDfaResult::Complete(found) => {
                panic!("test input did not reach a retained hole: {found:?}")
            }
        };
        assert!(resume.position > 0);
        assert!(resume.position < haystack.len());

        let reference = program(
            pattern,
            OutputContract::SelectedEnd,
            CompileMode::Fast,
            DeterminizeLimits::default(),
        );
        let expected = reference
            .search(haystack, SearchWindow::full(haystack))
            .expect("reference search");
        let mut workspace = limited.prepare_workspace().expect("workspace");
        assert!(workspace.dynamic_native_rows.is_some());
        for attempt in 0..2 {
            assert_eq!(
                limited
                    .search_with_retained_partial_workspace(
                        haystack,
                        SearchWindow::full(haystack),
                        &mut workspace,
                    )
                    .expect("accelerated search"),
                expected,
                "attempt {attempt}"
            );
        }
        let state = &workspace.partial.as_deref().unwrap().state;
        assert_eq!(state.complete_accelerated, 2);
        assert_eq!(state.resumed, 0);
        assert_eq!(state.consecutive_fallbacks, 0);
        assert_eq!(state.bypass_remaining, 0);
    }

